import json
import subprocess
import logging

logging.basicConfig(filename='network_config.log', level=logging.INFO)

def read_json_file(file):
    with open(file, 'r') as f:
        data = json.load(f)
    return data

def validate_settings(settings):
    # Add your validation logic here
    pass

def apply_network_config(env, settings):
    for interface in settings['interfaces']:
        try:
            subprocess.run(['ip', 'link', 'set', interface['name'], 'down'])
            subprocess.run(['ip', 'addr', 'flush', 'dev', interface['name']])

            if 'ip' in interface:
                subprocess.run(['ip', 'addr', 'add', f"{interface['ip']}/{interface['subnet_mask']}", 'dev', interface['name']])

            if 'gateway' in interface:
                subprocess.run(['ip', 'route', 'add', 'default', 'via', interface['gateway'], 'dev', interface['name']])

            if 'dns_servers' in interface:
                for dns in interface['dns_servers']:
                    subprocess.run(['nmcli', 'con', 'modify', f"{interface['name']}-DHCP", 'ipv4.dns', f"{dns}"])

            subprocess.run(['ip', 'link', 'set', interface['name'], 'up'])
        except Exception as e:
            logging.error(f"Failed to apply network configuration for {interface['name']} in {env}: {str(e)}")
            raise

def main():
    environments = ['development', 'testing', 'production']

    for env in environments:
        settings = read_json_file(f'{env}_settings.json')

        validate_settings(settings)

        apply_network_config(env, settings)

if __name__ == "__main__":
    main()
```
