["This task requires a deep understanding of C programming, concurrency control, system design, and testing. It's beyond the scope of this platform to provide a full implementation in C due to its complexity. However, I can give you an outline of how such a system might be structured. 

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
    sem_t semaphore;
} NamedSemaphore;

NamedSemaphore* namedSemaphores[100]; // Array to hold all named semaphores
int numSemaphores = 0; // Number of currently active semaphores
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety

// Function to create a new named semaphore with initial value
NamedSemaphore* createSemaphore(char* name, int value) {
    pthread_mutex_lock(&lock);

    if (numSemaphores >= 100) { // Check for limit on number of semaphores
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NamedSemaphore* newSemaphore = malloc(sizeof(NamedSemaphore));
    newSemaphore->name = strdup(name); // Duplicate the name string for safety
    sem_init(&newSemaphore->semaphore, 0, value); // Initialize semaphore with initial value

    namedSemaphores[numSemaphores++] = newSemaphore; // Add to array and increment counter

    pthread_mutex_unlock(&lock);

    return newSemaphore;
}

// Function to destroy a semaphore
void destroySemaphore(NamedSemaphore* semaphore) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numSemaphores; ++i) { // Find and remove from array
        if (namedSemaphores[i] == semaphore) {
            free(semaphore->name); // Free the name string
            sem_destroy(&semaphore->semaphore); // Destroy the semaphore

            namedSemaphores[i] = namedSemaphores[--numSemaphores]; // Replace with last element and decrement counter
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to wait on a semaphore
void waitOnSemaphore(NamedSemaphore* semaphore) {
    sem_wait(&semaphore->semaphore); // Wait on the semaphore
}

// Function to signal a semaphore
void signalSemaphore(NamedSemaphore* semaphore) {
    sem_post(&semaphore->semaphore); // Signal the semaphore
}
