```csharp
using System;
using MySql.Data.MySqlClient;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

public class QueryResult
{
    public string Query { get; set; }
    public bool Success { get; set; }
    public Exception Error { get; set; }
}

public class DatabaseManager
{
    private MySqlConnectionStringBuilder connectionStringBuilder;

    public DatabaseManager(string configFilePath)
    {
        string json = File.ReadAllText(configFilePath);
        dynamic config = JsonConvert.DeserializeObject<dynamic>(json);

        connectionStringBuilder = new MySqlConnectionStringBuilder
        {
            Server = config.server,
            Database = config.database,
            UserID = config.userId,
            Password = config.password,
            Pooling = true // Enable connection pooling
        };
    }

    public List<QueryResult> ExecuteQueries(List<string> queries)
    {
        var results = new List<QueryResult>();

        using (var connection = new MySqlConnection(connectionStringBuilder.ToString()))
        {
            connection.Open();

            foreach (var query in queries)
            {
                var result = new QueryResult { Query = query };

                try
                {
                    using (var command = new MySqlCommand(query, connection))
                    {
                        command.ExecuteNonQuery(); // Execute the query

                        result.Success = true;
                    }
                }
                catch (Exception ex)
                {
                    result.Error = ex;
                }

                results.Add(result);
            }
        }

        return results;
    }
}
```
This code reads a JSON configuration file to set up the database connection string, and then executes each query in a list against the database using a single connection from the pool. It logs any exceptions that occur during execution. 

