// Define your resource schema and model
const ResourceSchema = new mongoose.Schema({ /* define your schema here */ });
const Resource = mongoose.model('Resource', ResourceSchema);

// GET endpoint to fetch a resource
app.get('/resource/:id', (req, res) => {
  client.get(`resource_${req.params.id}`, async (err, reply) => {
    if (reply) {
      res.json(JSON.parse(reply));
    } else {
      const resource = await Resource.findById(req.params.id);
      client.setex(`resource_${req.params.id}`, 60, JSON.stringify(resource)); // cache for 60 seconds
      res.json(resource);
    }
  });
});

// PUT endpoint to update a resource
app.put('/resource/:id', async (req, res) => {
  const updatedResource = await Resource.findByIdAndUpdate(req.params.id, req.body, {new: true});
  client.setex(`resource_${req.params.id}`, 60, JSON.stringify(updatedResource)); // update cache
  res.json(updatedResource);
});

// DELETE endpoint to delete a resource
app.delete('/resource/:id', async (req, res) => {
  const deletedResource = await Resource.findByIdAndDelete(req.params.id);
  client.del(`resource_${req.params.id}`); // remove from cache
  res.json(deletedResource);
});

app.listen(3000, () => console.log('Server running on port 3000'));
