And here is a C++ function that operates on a forward list of strings:

```cpp
#include <forward_list>
#include <string>

void insertAfterTarget(std::forward_list<std::string>& flist, const std::string& target, const std::string& insertion) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == target) {
            flist.insert_after(it, insertion);
            return;
        }
        prev = it;
    }
    flist.insert_after(prev, insertion);
}
```

In the JavaScript function:
