const fs = require('fs');
const EventEmitter = require('events');
const config = JSON.parse(fs.readFileSync('config.json', 'utf8'));

class StreamProcessor extends EventEmitter {
    constructor() {
        super();
        this.streams = [];
        this.pausedStreams = new Set();
    }

    addStream(stream) {
        const streamData = [];
        this.streams.push({ stream, data: streamData });

        (async () => { // IIFE to create a closure for each stream
            while(true) {
                if (!this.pausedStreams.has(stream)) {
                    const chunk = await this.readChunkFromStream(stream);
                    streamData.push(chunk);
                    this.emit('data', stream, chunk);
                } else {
                    await new Promise(resolve => setTimeout(resolve, config.delayInterval));
                }
            }
        })();
    }

    pauseStream(stream) {
        this.pausedStreams.add(stream);
    }

    resumeStream(stream) {
        this.pausedStreams.delete(stream);
    }

    readChunkFromStream(stream) {
        return new Promise((resolve, reject) => {
            stream.read() // assuming there is a read method on the stream object
                .then(chunk => resolve(chunk))
                .catch(err => reject(err));
        });
    }
}

const processor = new StreamProcessor();
processor.addStream(stream1);
processor.addStream(stream2);

// Pause and resume streams
processor.on('data', (stream, chunk) => {
    if (chunk.size > config.failureThreshold) {
        processor.pauseStream(stream);
