use std::sync::Arc;
use hyper::client::{HttpConnector, HttpClient};
use hyper_tls::HttpsConnector;
use tokio::net::TcpStream;
use tokio::time::Duration;
use url::Url;
use serde::Deserialize;
use std::env;
use std::fs::File;
use std::io::Read;
use std::sync::Mutex;
use std::thread;
use tracing::info;
use hyper::Body;
use tokio::net::TcpStream;
use tokio_util::codec::{Framed, LinesCodec};

#[derive(Deserialize)]
struct Config {
    url: String,
}

pub struct HttpClient {
    config: Arc<Mutex<Config>>,
    client: HyperClient,
}

impl HttpClient {
    pub fn new() -> Self {
        let https_connector = HttpsConnector::new(4).unwrap();
        let connector = hyper::client::HttpConnector::new().https(https_connector);
        let client = HyperClient::builder()
            .keep_alive(Duration::from_secs(30))
            .timeout(Duration::from_secs(15))
            .build(Arc::new(connector));

        let config = Arc::new(Mutex::new(Config {
            url: env::var("URL").unwrap_or_else(|_| "http://localhost:8080".to_string()),
        }));

        Self { client, config }
    }

    pub async fn get(&self) -> Result<(), Box<dyn std::error::Error>> {
        let url = Url::parse(&*self.config.lock().unwrap().url)?;
        let resp = self.client.get(url).await?;
        assert_eq![resp.status(), 200];
        Ok(())
    }
}
