        std::vector<Node*> children;
        int featureSize;
        int numLeafNodes;
        int dataCapacity;
        int maxMemoryLimit;
        std::mutex mtx; // for thread safety

        Node(int fs, int nl, int dc, int mml) : 
            children(8), featureSize(fs), numLeafNodes(nl), dataCapacity(dc), maxMemoryLimit(mml) {}
    };

    Octree(int fs, int nl, int dc, int mml) {
        if (fs <= 0 || nl <= 0 || dc <= 0 || mml <= 0) 
            throw std::invalid_argument("All parameters must be positive");

        root = new Node(fs, nl, dc, mml);
    }

    ~Octree() { deleteNode(root); }

    void insertData(int data) {
        std::lock_guard<std::mutex> lock(root->mtx); // for thread safety

        if (data > root->maxMemoryLimit) 
            throw std::runtime_error("Max memory limit exceeded");

        // insert data logic here...
    }

private:
    Node* root;

    void deleteNode(Node* node) {
        for (auto child : node->children) 
            if (child != nullptr) 
                deleteNode(child);

        delete node;
    }
};
```
This code creates an Octree class with a Node struct that represents each node in the octree. The insertData function is a placeholder for where you would implement your data insertion logic, and it includes a mutex to ensure thread safety. 

