#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <libconfig.h>

typedef struct {
    pthread_mutex_t lock;
    int activeConnections;
    // Add other connection pool parameters here
} ConnectionPool;

ConnectionPool* initConnectionPool(const char *configPath) {
    config_t cfg, *cf;
    cf = &cfg;
    config_init(cf);

    if(!config_read_file(cf, configPath)) {
        fprintf(stderr, "Failed to read configuration file %s: %s\n", 
                configPath, config_error_text(cf));
        config_destroy(cf);
        return NULL;
    }

    // Parse the configuration and initialize connection pool parameters here
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    if (pthread_mutex_init(&(pool->lock), NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        free(pool);
        return NULL;
    }

    // Initialize connection pool here

    config_destroy(cf);
    return pool;
}

int getActiveConnections(ConnectionPool *pool) {
    pthread_mutex_lock(&(pool->lock));
    int active = pool->activeConnections;
    pthread_mutex_unlock(&(pool->lock));

    return active;
}

void destroyConnectionPool(ConnectionPool *pool) {
    // Clean up connection pool here

    pthread_mutex_destroy(&(pool->lock));
    free(pool);
}
```
This code provides a basic structure for managing a connection pool in C. It uses a mutex to ensure that only one thread can access the connection pool at a time, preventing race conditions. The `initConnectionPool` function reads a configuration file and initializes a connection pool based on its parameters. The `getActiveConnections` function returns the number of active connections currently in use. Finally, the `destroyConnectionPool` function cleans up any resources used by the connection pool.
