['Here is an example of how you might implement this task using C and libtiff library. This solution assumes that you have already installed libtiff on your system. 

```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <tiffio.h>

typedef struct {
    uint16 bitsPerSample;
    uint16 sampleFormat;
    uint32 width;
    uint32 height;
    char md5Hash[MD5_DIGEST_LENGTH * 2 + 1];
} ImageMetadata;

ImageMetadata extractMetadata(const char* filePath) {
    TIFF* tiff = TIFFOpen(filePath, "r");
    if (tiff == NULL) {
        fprintf(stderr, "Failed to open TIFF image: %s\n", filePath);
        exit(1);
    }

    ImageMetadata metadata;
    memset(&metadata, 0, sizeof(ImageMetadata));

    // Extract bits per sample and sample format
    if (!TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample)) {
        fprintf(stderr, "Failed to extract bits per sample from TIFF image: %s\n", filePath);
        exit(1);
    }

    if (!TIFFGetField(tiff, TIFFTAG_SAMPLEFORMAT, &metadata.sampleFormat)) {
        fprintf(stderr, "Failed to extract sample format from TIFF image: %s\n", filePath);
        exit(1);
    }

    // Extract width and height
    if (!TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &metadata.width)) {
        fprintf(stderr, "Failed to extract image width from TIFF image: %s\n", filePath);
        exit(1);
    }

    if (!TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &metadata.height)) {
        fprintf(stderr, "Failed to extract image length from TIFF image: %s\n", filePath);
        exit(1);
    }

    // Compute MD5 hash of the header bytes
    uint32 headerSize = sizeof(TIFFHeader) + tiff->tif_header.tiff_magic;
    unsigned char* headerBytes = malloc(headerSize);
    if (headerBytes == NULL) {
        fprintf(stderr, "Failed to allocate memory for header bytes\n");
        exit(1);
    }

    memcpy(headerBytes, &tiff->tif_header, sizeof(TIFFHeader));
    TIFFReadRawStrip(tiff, 0, headerBytes + sizeof(TIFFHeader), headerSize - sizeof(TIFFHeader));

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5(headerBytes, headerSize, md5);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&metadata.md5Hash[i * 2], "%02x", md5[i]);
    }

    free(headerBytes);

    TIFFClose(tiff);

    return metadata;
}
```
This code uses the libtiff library to parse a TIFF image file and extract detailed metadata. It also computes an MD5 hash of the header bytes for integrity checking. The extracted data is encapsulated within a custom struct for efficient access and manipulation. 

Please note that this is a basic implementation and does not handle all possible edge cases or error conditions. For example, it assumes that the TIFF file can be opened successfully and that all required tags are present in the file. In a real-world application, you would need to add appropriate error handling and validation checks.
']

