    public async Task<ProcessResult> ProcessDataAsync(string filePath, string metadataApiUrl)
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        try
        {
            // Validate the file structure using external API
            var isValidStructure = await ValidateFileStructureAsync(filePath, metadataApiUrl);
            if (!isValidStructure)
                return ProcessResult.Failure("Invalid file structure");

            // Decompress and deserialize data
            var decompressedStream = new MemoryStream();
            using (var compressedStream = File.OpenRead(filePath))
            {
                await Task.Run(() =>
                {
                    using (var decompressionStream = new GZipStream(compressedStream, CompressionMode.Decompress))
                        decompressionStream.CopyTo(decompressedStream);
                });
            }

            var data = JsonConvert.DeserializeObject<CustomDataStructure>(await ReadAsStringAsync(decompressedStream));

            stopwatch.Stop();
            return ProcessResult.Success("Processing completed successfully", stopwatch.Elapsed, decompressedStream.Length);
        }
        catch (Exception ex)
        {
            // Log the exception for troubleshooting
            Console.WriteLine($"Error processing data: {ex}");

            return ProcessResult.Failure("An error occurred while processing data", stopwatch.Elapsed, decompressedStream?.Length ?? 0);
