pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int processFile(const char* filename, int** arrayPtr, int* size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return 0;
    }

    pthread_mutex_lock(&lock);
    int count = 0;
    while (!feof(file)) {
        int value;
        if (fscanf(file, "%d", &value) == 1 && value > 0 && value < 1000) {
            (*arrayPtr)[count++] = value;
        } else {
            fclose(file);
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    *size = count;
    *arrayPtr = realloc(*arrayPtr, (*size) * sizeof(int));
    fclose(file);
    pthread_mutex_unlock(&lock);
    return 1;
}
