['Here is an example of how you might implement this in C using OpenSSL. This code does not include all the considerations mentioned as it would be quite complex and lengthy. However, it provides a basic structure for dynamically populating a list of available cryptographic primitives within a library. 

```c
#include <openssl/evp.h>
#include <stdio.h>

typedef struct {
    const char *name;
    void *(*func)(void);
} PrimitiveInfo;

PrimitiveInfo *get_primitives(int *count) {
    OpenSSL_add_all_digests();
    OpenSSL_add_all_ciphers();

    int num = EVP_CIPHER_number();
    PrimitiveInfo *info = malloc(num * sizeof(PrimitiveInfo));
    if (!info) {
        return NULL;
    }

    for (int i = 0, j = 0; i < num; ++i) {
        const EVP_CIPHER *cipher = EVP_get_cipherbynum(i);
        if (cipher && cipher->name) {
            info[j].name = cipher->name;
            info[j].func = (void *)EVP_get_digestbyname(cipher->name);
            ++j;
        }
    }

    *count = num;
    return info;
}

int main() {
    int count = 0;
    PrimitiveInfo *info = get_primitives(&count);
    if (!info) {
        printf("Failed to retrieve primitives\n");
        return 1;
    }

    for (int i = 0; i < count; ++i) {
        printf("%s: %p\n", info[i].name, info[i].func);
    }

    free(info);
    return 0;
}
```
This code first initializes OpenSSL with all available digests and ciphers. It then retrieves the number of available ciphers and allocates memory for an array of `PrimitiveInfo` structs. For each cipher, it checks if it is a valid cipher (not NULL) and has a name. If so, it adds its name and function pointer to the array. Finally, it prints out the names and function pointers of all available primitives.
