    std::uniform_int_distribution<long long> offsetDistribution;
    std::uniform_int_distribution<int> keyDistribution;
public:
    DataProcessor(long long minOffset, long long maxOffset, int minKey, int maxKey) : 
        rng(std::chrono::high_resolution_clock::now().time_since_epoch().count()),
        offsetDistribution(minOffset, maxOffset),
        keyDistribution(minKey, maxKey) {}
    ~DataProcessor() = default;

    std::vector<long long> generateOffsets(size_t count) {
