use reqwest::Client;
use rand::Rng;
use std::sync::{Arc, Mutex};
use std::time::Duration;

pub struct DynamicValueGenerator {
    min: f64,
    max: f64,
    client_pool: Arc<Mutex<Vec<Client>>>,
}

impl DynamicValueGenerator {
    pub fn new(min: f64, max: f64) -> Self {
        let client = Client::builder()
            .timeout(Duration::from_secs(5))
            .build().unwrap();

        Self {
            min,
            max,
            client_pool: Arc::new(Mutex::new(vec![client])),
        }
    }

    pub fn generate_float(&self) -> f64 {
        let mut rng = rand::thread_rng();
        rng.gen_range(self.min..=self.max)
    }

    pub fn generate_int_inclusive(&self) -> i32 {
        let min = self.min as i32;
        let max = self.max as i32;

        let mut rng = rand::thread_rng();
        rng.gen_range(min..=max)
    }

    pub fn generate_int_exclusive(&self) -> i32 {
        let min = self.min as i32;
        let max = (self.max as i32) - 1;

        let mut rng = rand::thread_rng();
        rng.gen_range(min..max)
    }

    pub fn http_client(&self, url: &str) -> Result<reqwest::RequestBuilder, reqwest::Error> {
        let client = self.client_pool.lock().unwrap();

        Ok(client[0].get(url))
    }
}

impl ToString for DynamicValueGenerator {
    fn to_string(&self) -> String {
        format![DynamicValueGenerator: min={}, max={}", self.min, self.max]
    }
}

