        assert_eq![true, value >= 10 && value <= 20];
    }

    #[test]
    fn test_generate_int_exclusive() {
        let dvg = DynamicValueGenerator::new(10.0, 20.0);
        let value = dvg.generate_int_exclusive();

        assert_eq![true, value >= 10 && value < 20];
    }

    #[test]
    fn test_http_client() {
