['Here's an example of how you might implement such a function in C. This solution uses a simple Union-Find data structure for identifying disjoint pairs. It also logs the processing time using `clock()` from the time.h library, which measures CPU time used by the program. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int *parent;
    unsigned int *rank;
    size_t size;
} UnionFind;

UnionFind* createUF(size_t size) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->parent = malloc(size * sizeof(int));
    uf->rank = calloc(size, sizeof(unsigned int));
    uf->size = size;

    for (size_t i = 0; i < size; ++i) {
        uf->parent[i] = -1;
    }

    return uf;
}

void destroyUF(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int find(UnionFind *uf, int i) {
    if (uf->parent[i] != i) {
        uf->parent[i] = find(uf, uf->parent[i]);
    }

    return uf->parent[i];
}

void unionUF(UnionFind *uf, int x, int y) {
    int xroot = find(uf, x);
    int yroot = find(uf, y);

    if (xroot == yroot) return;

    if (uf->rank[xroot] < uf->rank[yroot]) {
        uf->parent[xroot] = yroot;
    } else if (uf->rank[xroot] > uf->rank[yroot]) {
        uf->parent[yroot] = xroot;
    } else {
        uf->parent[yroot] = xroot;
        ++uf->rank[xroot];
    }
}

char* processArray(int *arr, size_t len, int maxLen) {
    if (len == 0 || arr == NULL) return NULL;

    clock_t start = clock();

    UnionFind *uf = createUF(len);
    char *str = malloc((maxLen + 1) * sizeof(char)); // +1 for the trailing null character
    size_t strIndex = 0;

    for (size_t i = 0; i < len - 1; ++i) {
        unionUF(uf, arr[i], arr[i + 1]);

        int root = find(uf, arr[i]);
        int count = 0;

        while (arr[i] == root && strIndex < maxLen) {
            sprintf(&str[strIndex], "%d,", arr[i]);
            strIndex += snprintf(NULL, 0, "%d,", arr[i]); // +2 for the comma and digit
            ++count;
            ++i;
        }

        --i; // Decrement i to account for the extra increment in the loop
    }

    if (strIndex < maxLen) {
        sprintf(&str[strIndex], "%d/", arr[len - 1]);
    } else {
        destroyUF(uf);
        free(str);
        return NULL;
    }

    clock_t end = clock();
    double timeSpent = (double)(end - start) / CLOCKS_PER_SEC * 1000; // Time in milliseconds
    printf("Processing time: %f ms\n", timeSpent);

    destroyUF(uf);
    return str;
}
```
This code is not thread-safe. If you need to use this function in a multi-threaded application, you should add appropriate synchronization mechanisms such as mutexes or locks. Also, the Union-Find data structure could be optimized further for better time and space complexity.
