#include <stdio.h>
#include <stdlib.h>

typedef struct {
    float temperature;
    float humidity;
} WeatherData;

typedef struct {
    int frequency;
    int signalStrength;
    WeatherData weatherData;
} NetworkDevice;

typedef struct {
    NetworkDevice* devices;
    size_t capacity;
    size_t used;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialSize) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->devices = malloc(initialSize * sizeof(NetworkDevice));
    if (array->devices == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initialSize;
    array->used = 0;

    return array;
}

void addToArray(DynamicArray* array, NetworkDevice device) {
    if (array->used == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NetworkDevice* newDevices = realloc(array->devices, newCapacity * sizeof(NetworkDevice));

        if (newDevices == NULL) return;

        array->devices = newDevices;
        array->capacity = newCapacity;
    }

    array->devices[array->used++] = device;
}

void freeArray(DynamicArray* array) {
    free(array->devices);
    free(array);
}
```
