void* executeShellCommand(void *command) {
    pid_t pid = fork();

    if (pid == 0) {
        char *argv[] = {"sh", "-c", command, NULL};
        execvp("sh", argv);

        // If execvp fails, print an error message and exit the child process
        perror("execvp failed");
        _exit(1);
    } else if (pid < 0) {
        perror("fork failed");
        return NULL;
    } else {
        int status;
        wait(&status);

        // Check the exit status of the child process and handle failures gracefully
        if (WIFEXITED(status)) {
            int exit_code = WEXITSTATUS(status);

            if (exit_code != 0) {
                fprintf(stderr, "Child process exited with code %d\n", exit_code);
            } else if (debug) {
                printf("Child process completed successfully\n");
            }
        } else if (WIFSIGNALED(status)) {
            int signal = WTERMSIG(status);

            fprintf(stderr, "Child process was terminated by signal %d\n", signal);
        }
    }

    return NULL;
}

int initializeList(NFAPI_CRC_INDICATION_PDU_T **list, int numElements) {
    pthread_mutex_lock(&lock);  // Acquire the lock to ensure thread safety

    *list = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
