// Predefined list of common extensions
char *extensions[] = {".txt", ".docx", ".jpg", ".png"};
int num_exts = 4; // Number of extensions in the array

void validatePath(const char* path) {
    if (strlen(path) > 128) {
        printf("Error: Path is too long\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < strlen(path); ++i) {
        if (!isalnum(path[i]) && path[i] != '/') {
            printf("Error: Invalid character in path\n");
            exit(EXIT_FAILURE);
        }
    }
}

int checkFileExists(const char* fname) {
    FILE *file;

    if ((file = fopen(fname, "r"))) {
        fclose(file);
        return 1;
    }

    return 0;
}

void processFilename(char* filename, const char* path) {
    validatePath(path);

    int len = strlen(filename);
    int ext_index = (len / 2) % num_exts; // Select extension based on length of filename
    char new_fname[128];

    if ((strlen(path) + len + 5) > 128) { // If new filename exceeds limit, truncate it
        strncpy(new_fname, path, 120);
        new_fname[120] = '\0';
        printf("Warning: Filename truncated\n");
    } else {
        sprintf(new_fname, "%s/%.*s", path, len, filename); // Copy path and filename to new string
    }

    strcat(new_fname, extensions[ext_index]); // Append extension to new filename

    if (checkFileExists(new_fname)) { // If file with same name exists, append a unique identifier
        sprintf(new_fname, "%s/%.*s_unique", path, len, filename);
    }

    printf("New Filename: %s\n", new_fname);
}

int main() {
    char filename[] = "example";
    char path[] = "/path/to/directory";

    processFilename(filename, path);

    return 0;
}
