#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES256Context;

AES256Context* aes256Init(const char *password) {
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));

    unsigned char key[32], iv[16];
    PKCS5_PBKDF2_HMAC_SHA1(password, strlen(password), salt, sizeof(salt), 1000, 32, key);
    RAND_bytes(iv, sizeof(iv));

    AES256Context *ctx = malloc(sizeof(*ctx));
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv);

    return ctx;
}

void aes256Cleanup(AES256Context *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```
