['Here is a basic implementation in C that meets your requirements. This code uses a hash table (implemented as an array) for storing integer inputs and their counts, which allows for efficient retrieval of maximum value and its occurrences. It also includes error handling for memory allocation failures and non-integer inputs.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the hash table size as a prime number to reduce collisions
#define TABLE_SIZE 1009

typedef struct {
    int value;
    int count;
} DataPoint;

DataPoint* dataPoints[TABLE_SIZE];
int maxValue = -1;
int totalCount = 0;

void processInput(char *input) {
    char *endptr;
    long val = strtol(input, &endptr, 10);

    // Check if the input is a valid integer
    if (*endptr == '\0') {
        int index = ((int)val % TABLE_SIZE + TABLE_SIZE) % TABLE_SIZE;

        // If the value already exists in the hash table, increment its count
        if (dataPoints[index] != NULL && dataPoints[index]->value == val) {
            dataPoints[index]->count++;
        } else {
            DataPoint *newDataPoint = malloc(sizeof(DataPoint));

            // Check for memory allocation failure
            if (newDataPoint == NULL) {
                fprintf(stderr, "Memory allocation failed.\n");
                return;
            }

            newDataPoint->value = val;
            newDataPoint->count = 1;
            dataPoints[index] = newDataPoint;
        }

        // Update the maximum value and total count
        if (val > maxValue) {
            maxValue = val;
        }
        totalCount++;
    } else {
        fprintf(stderr, "Ignoring non-integer input: %s\n", input);
    }
}

void resetState() {
    // Free all allocated memory and reset the state variables
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (dataPoints[i] != NULL) {
            free(dataPoints[i]);
            dataPoints[i] = NULL;
        }
    }

    maxValue = -1;
    totalCount = 0;
}
```

To use this function, you can call `processInput` with each input string. After processing a batch of inputs, call `resetState` to clear the state and start over for the next session. 

Please note that this is a basic implementation and may need further optimization or adjustments based on your specific requirements and constraints. For example, you might want to use a more efficient data structure for storing integers (e.g., a balanced binary search tree), handle concurrent access from multiple threads, or optimize memory usage in other ways.
']

['```c
#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>
#include <errno.h>
#include <string.h>

int executeBackgroundTask(char* command, int initialValue, int *semaphoreId, int logFd) {
    union semun {
        int val;
        struct semid_ds *buf;
        unsigned short  *array;
    } arg;

    // Create a semaphore with the given initial value.
    if ((*semaphoreId = semget(IPC_PRIVATE, 1, IPC_CREAT | 0600)) < 0) {
        dprintf(logFd, "Failed to create semaphore: %s\n", strerror(errno));
        return 0;
    }

    // Initialize the semaphore.
    arg.val = initialValue;
    if (semctl(*semaphoreId, 0, SETVAL, arg) < 0) {
        dprintf(logFd, "Failed to initialize semaphore: %s\n", strerror(errno));
        return 0;
    }

    // Fork a child process.
    pid_t pid = fork();
    if (pid < 0) {
        dprintf(logFd, "Failed to fork process: %s\n", strerror(errno));
        return 0;
    } else if (pid == 0) { // Child process.
        // Execute the command in the background.
        execl("/bin/sh", "sh", "-c", command, NULL);

        dprintf(logFd, "Failed to execute command: %s\n", strerror(errno));
        return 0;
    } else { // Parent process.
        int status;
        waitpid(pid, &status, 0);

        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            dprintf(logFd, "Command execution failed with exit code: %d\n", WEXITSTATUS(status));
            return 0;
        }

        // Delete the semaphore.
        if (semctl(*semaphoreId, 0, IPC_RMID) < 0) {
            dprintf(logFd, "Failed to delete semaphore: %s\n", strerror(errno));
            return 0;
        }

        return 1;
    }
}
```
