typedef struct {
    int identifier;
    int priority;
    char status[20]; // assuming a maximum length of 19 characters for the status string
} task;

task** tasks = NULL;
int num_tasks = 0;
int max_tasks = 0;

void add_task(int identifier, int priority) {
    if (num_tasks == max_tasks) {
        // Reallocate memory for more tasks
        max_tasks = max_tasks ? max_tasks * 2 : 1;
        tasks = realloc(tasks, max_tasks * sizeof(task*));
    }

    task* new_task = malloc(sizeof(task));
    new_task->identifier = identifier;
    new_task->priority = priority;
    strcpy(new_task->status, "pending");

    tasks[num_tasks++] = new_task;
}

void update_task(int index, int identifier, int priority, char* status) {
    if (index < 0 || index >= num_tasks) {
        printf("Invalid task index\n");
        return;
    }

    tasks[index]->identifier = identifier;
    tasks[index]->priority = priority;
    strcpy(tasks[index]->status, status);
}

task* get_task(int index) {
    if (index < 0 || index >= num_tasks) {
        printf("Invalid task index\n");
        return NULL;
    }

    return tasks[index];
}

void free_all_tasks() {
    for (int i = 0; i < num_tasks; ++i) {
        free(tasks[i]);
    }
    free(tasks);
    tasks = NULL;
    num_tasks = max_tasks = 0;
}

void generate_random_identifier() {
