['Here is a basic example of how you might implement this function in C using POSIX threads for thread safety and a linked list for memory efficiency. This code does not include error handling or network connection setup as those are complex topics that would require additional libraries and detailed understanding of the specifics of your system. 

```c
#include <stdio.h>
#include <pthread.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void* establishConnection(void* arg) {
    // Establish connection to remote server here.
}

void addToList(int data) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if(!newNode) exit(-1); // Exit on memory allocation failure.

    newNode->data = data;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

int main() {
    if(pthread_mutex_init(&lock, NULL) != 0) {
        printf("Mutex init failed\n");
        return 1;
    }

    // Create a thread for network connection.
    pthread_t threadId;
    int result = pthread_create(&threadId, NULL, &establishConnection, NULL);

    if(result != 0) {
        printf("Thread creation failed\n");
        return 1;
    }

    // Read integers from standard input and add to list.
    int num;
    while(scanf("%d", &num) == 1) {
        addToList(num);
    }

    if (pthread_join(threadId, NULL) != 0) {
        printf("Thread join failed\n");
        return 1;
    }

    pthread_mutex_destroy(&lock);

    // Free memory.
    Node* current = head;
    while (current != NULL) {
       Node* temp = current;
       current = current->next;
       free(temp);
    }

    return 0;
}
```
This code reads integers from standard input and adds them to a linked list. It uses a mutex for thread safety, ensuring that only one thread can access the list at a time. The memory allocated for each node is freed when the program exits.
