int configure_network_settings(size_t num_configs, network_config configs[]) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety.

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        pthread_mutex_unlock(&lock); // Unlock before returning in case of error.
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, '0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // HTTP port

    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        pthread_mutex_unlock(&lock); // Unlock before returning in case of error.
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection Failed");
        pthread_mutex_unlock(&lock); // Unlock before returning in case of error.
        return -1;
    }

    // Make HTTP request to network management service...

    close(sockfd); // Close socket after use.

    pthread_mutex_unlock(&lock); // Unlock after successful execution.
    return 0;
}
