["Here's a basic implementation of your request using OpenSSL library. This code does not include error handling for brevity but you should add it in production code. Also, please note that this is just an example and might need adjustments based on the specific requirements of your project.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} aes_gcm_context;

int init_aes_gcm(const char* password, const unsigned char* salt, int iterations, aes_gcm_context *ctx) {
    if (!RAND_bytes(ctx->iv, EVP_MAX_IV_LENGTH)) return 0;

    // Derive key from password using PBKDF2
    unsigned char* derivedKey = malloc(EVP_MAX_KEY_LENGTH);
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, strlen((char*)salt), iterations, EVP_aes_128_gcm(), EVP_MAX_KEY_LENGTH, derivedKey)) {
        free(derivedKey);
        return 0;
    }

    // Initialize cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_128_gcm(), NULL, derivedKey, ctx->iv)) {
        free(derivedKey);
        return 0;
    }

    // Cleanup
    memcpy(ctx->key, derivedKey, EVP_MAX_KEY_LENGTH);
    free(derivedKey);
    OPENSSL_cleanse(&password, sizeof(password));

    return 1;
}

void cleanup_aes_gcm(aes_gcm_context *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_cleanse(&ctx->key, sizeof(ctx->key));
    OPENSSL_cleanse(&ctx->iv, sizeof(ctx->iv));
}
```
This code initializes an AES-128-GCM cipher context with a given password and salt. The key is derived from the password using PBKDF2 with a specified number of iterations. The IV (Initialization Vector) is randomly generated for each session to ensure security. 

The `cleanup_aes_gcm` function disables and frees the cipher context, zeroing out any sensitive data in memory. This function should be called when you're done with the cipher context to prevent potential security issues.
"]

