        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Add the new context and update the size
    manager->contexts = newArray;
    manager->size = newSize;
    manager->contexts[newSize - 1] = context;

    pthread_mutex_unlock(&manager->lock);
}

void freeContextManager(ContextManager* manager) {
