typedef struct Record {
    int key;
    long timestamp;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct Database {
    Node **table;
    int capacity;
    int size;
    int max_capacity;
} Database;

Database* create_database(int initial_size, int max_capacity) {
    srand(time(NULL));

    Database *db = malloc(sizeof(Database));
    if (db == NULL) return NULL;

    db->table = calloc(initial_size, sizeof(Node*));
    if (db->table == NULL) {
        free(db);
        return NULL;
    }

    db->capacity = initial_size;
    db->size = 0;
    db->max_capacity = max_capacity;

    return db;
}

void destroy_database(Database *db) {
    for (int i = 0; i < db->capacity; ++i) {
        Node *node = db->table[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node->record);
            free(node);
            node = next;
        }
    }

    free(db->table);
    free(db);
}

int hash_function(int key, int capacity) {
    return abs(key) % capacity;
}

void insert_record(Database *db, Record *record) {
    if (db->size >= db->max_capacity) {
        // Handle overflow here. This could involve resizing the hash table or rejecting new records.
        return;
    }

    int index = hash_function(record->key, db->capacity);

    Node *node = malloc(sizeof(Node));
    if (node == NULL) return;

    node->record = record;
    node->next = db->table[index];
    db->table[index] = node;
    ++db->size;
}

Record* get_record(Database *db, int key) {
    int index = hash_function(key, db->capacity);

    Node *node = db->table[index];
    while (node != NULL) {
        if (node->record->key == key) return node->record;
        node = node->next;
    }

    return NULL;
}
