// Function to compute SHA-256 hash of an object
void computeHash(Object *obj, unsigned char *hash) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, &obj->value, sizeof(float));
    SHA256_Update(&ctx, &obj->id, sizeof(int));
    SHA256_Update(&ctx, &obj->timestamp, sizeof(time_t));
    SHA256_Final(hash, &ctx);
}

// Function to generate unique identifier
char* generateIdentifier() {
    char *identifier = malloc(sizeof(char) * 10); // Assuming identifiers are 10 characters long
    srand(time(NULL));
    for (int i = 0; i < 9; ++i) {
        identifier[i] = 'A' + rand() % 26; // Generate a random uppercase letter
