void* manageDataRecords(void* arg) {
    pthread_mutex_lock(&config.mutex);

    size_t recordCount = config.memoryBudget / sizeof(DataRecord);
    DataRecord* records = malloc(recordCount * sizeof(DataRecord));
    if (records == NULL) {
        pthread_mutex_lock(&logMutex);
        fprintf(stderr, "Failed to allocate memory for data records\n");
        pthread_mutex_unlock(&logMutex);

        pthread_mutex_unlock(&config.mutex);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
        records[i].value = (double)rand() / RAND_MAX;

        char buffer[32];
        sprintf(buffer, "%d", records[i].key);
        size_t len = strlen(buffer);
        records[i].str_key = malloc(len + 1);
        if (records[i].str_key == NULL) {
            pthread_mutex_lock(&logMutex);
            fprintf(stderr, "Failed to allocate memory for string key\n");
            pthread_mutex_unlock(&logMutex);

            free(records);
            pthread_mutex_unlock(&config.mutex);
            return NULL;
        }

        strcpy(records[i].str_key, buffer);
    }

    // Logging operations...
    if (config.loggingLevel > 0) {
        pthread_mutex_lock(&logMutex);
        fprintf(stderr, "Allocated %zu data records\n", recordCount);
        pthread_mutex_unlock(&logMutex);
    }

    // Cleanup...
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i].str_key);
    }
    free(records);

    pthread_mutex_unlock(&config.mutex);
    return NULL;
}
