void readAndSort(int max, int limit) {
    int *arr = malloc(limit * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    srand(time(NULL)); // seed the random number generator

    for (int i = 0; i < limit; i++) {
        int num = rand() % max + 1; // generate a random number between 1 and max
        if (num <= 0 || num > max) {
            printf("Invalid input: %d\n", num);
            continue;
        }

        arr[i] = num;
    }

    qsort(arr, limit, sizeof(int), compare); // sort the array in ascending order

    int median = findMedian(arr, limit);
    printf("The median is: %d\n", median);

    free(arr);
}

int compare (const void * a, const void * b) {
   return ( *(int*)a - *(int*)b );
}

int findMedian(int arr[], int n) { 
    if (n % 2 == 0) 
        return (arr[n/2] + arr[n/2-1]) / 2; 
    else
        return arr[n/2]; 
}
