} CellularFrame;

typedef struct {
    size_t capacity;
    size_t size;
    CellularFrame *frames;
    pthread_mutex_t mutex;
} FrameArray;

void framearray_init(FrameArray *a, size_t initialSize) {
    a->frames = (CellularFrame*) malloc(initialSize * sizeof(CellularFrame));
    a->capacity = initialSize;
    a->size = 0;
    pthread_mutex_init(&a->mutex, NULL);
}

void framearray_append(FrameArray *a, CellularFrame value) {
    pthread_mutex_lock(&a->mutex);

    if (a->size == a->capacity) {
        a->capacity *= 2;
        a->frames = realloc(a->frames, a->capacity * sizeof(CellularFrame));
    }
    a->frames[a->size++] = value;

    pthread_mutex_unlock(&a->mutex);
}

void framearray_update_quality(FrameArray *a, int index, int newQuality) {
    pthread_mutex_lock(&a->mutex);

    if (index >= 0 && index < a->size) {
        a->frames[index].CHANNEL_QUALITY_INDICATOR = newQuality;
    }

    pthread_mutex_unlock(&a->mutex);
}

CellularFrame framearray_get_best(FrameArray *a) {
    pthread_mutex_lock(&a->mutex);

    int bestIndex = 0;
    for (int i = 1; i < a->size; ++i) {
        if (a->frames[i].CHANNEL_QUALITY_INDICATOR > a->frames[bestIndex].CHANNEL_QUALITY_INDICATOR) {
            bestIndex = i;
        }
    }

    pthread_mutex_unlock(&a->mutex);

    return a->frames[bestIndex];
}
