        a->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(a->array, a->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    a->array[a->used++] = element;
}

void freeArray(Array* a) {
