#include <atomic>
#include <thread>
#include <vector>
#include <iostream>
#include <random>

struct FAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

std::atomic<int> max_integer(0);
std::vector<FAPI_CRC_INDICATION_PDU_T> pdu_list;

void process_integers() {
    int input;
    while (std::cin >> input) {
        if (input > max_integer.load()) {
            max_integer.store(input);
        }
    }
}

void populate_structures(int N) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    pdu_list.reserve(N);
    for (int i = 0; i < N; ++i) {
        FAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = i * 2;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);

        pdu_list.push_back(pdu);
    }
}

int main() {
    int N = 100000; // number of structures to create

    std::thread producer(populate_structures, N);
    std::thread consumer(process_integers);

    producer.join();
    consumer.detach();

    while (true) {
        int current_max = max_integer.load();
        if (current_max != 0) {
            std::cout << "Max integer: " << current_max << "\n";
            break;
        }
    }

    return 0;
}
