["Here is a C implementation for your task. This code uses OpenSSL library to generate random strings and hash them using SHA256 algorithm. It also uses pthreads library to ensure thread safety. 

```c
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[SHA256_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T *generateArray(int size, const char *charset, int seed, const char *password) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (array == NULL) return NULL; // handle memory allocation failure

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);

    int charsetSize = strlen(charset);
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = malloc(sizeof(char) * 16 + 1); // allocate memory for string
        if (array[i].RX_UE_INFORMATION_TAG == NULL) return NULL; // handle memory allocation failure

        int attempt = 0;
        do {
            RAND_seed(&seed, sizeof(int));
            for (int j = 0; j < 16; j++) {
                array[i].RX_UE_INFORMATION_TAG[j] = charset[rand() % charsetSize];
            }
            array[i].RX_UE_INFORMATION_TAG[16] = '\0'; // null-terminate string

            pthread_mutex_lock(&lock);
            for (int j = 0; j < i; j++) {
                if (strcmp(array[i].RX_UE_INFORMATION_TAG, array[j].RX_UE_INFORMATION_TAG) == 0) {
                    attempt++;
                    break;
                }
            }
            pthread_mutex_unlock(&lock);
        } while (attempt < 5); // retry up to 5 times if seed does not produce unique string

        array[i].RNTI = i + 1;
        memcpy(array[i].CRC_INDICATION_REL8_TAG, hash, SHA256_DIGEST_LENGTH);
    }

    return array;
}
```
This function generates an array of `NFAPI_CRC_INDICATION_PDU_T` structures. Each structure contains a unique random string and the hashed password. The function uses pthreads library to ensure thread safety when checking for uniqueness in the generated strings. It also retries generating unique strings up to 5 times if necessary.
"]

