```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Your structure definition here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct ListNode* next;
} ListNode;

typedef struct DynamicList {
    ListNode* head;
    sem_t countSemaphore;
    pthread_mutex_t mutex;
    int maxSize;
} DynamicList;

DynamicList* createList(int maxSize) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    sem_init(&list->countSemaphore, 0, maxSize);
    pthread_mutex_init(&list->mutex, NULL);
    list->maxSize = maxSize;
    list->head = NULL;

    return list;
}

void addToList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (sem_wait(&list->countSemaphore) == 0) {
        pthread_mutex_lock(&list->mutex);

        ListNode* newNode = malloc(sizeof(ListNode));
        newNode->data = data;
        newNode->next = list->head;
        list->head = newNode;

        pthread_mutex_unlock(&list->mutex);
    } else {
        printf("Maximum size exceeded, cannot add to list.\n");
    }
}

void removeFromList(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);

    ListNode* prev = NULL;
    for (ListNode* node = list->head; node != NULL; node = node->next) {
        if (node->data == data) {
            if (prev == NULL) {
                list->head = node->next;
            } else {
                prev->next = node->next;
            }

            free(node);
            sem_post(&list->countSemaphore);
            break;
        }

        prev = node;
    }

    pthread_mutex_unlock(&list->mutex);
}

void destroyList(DynamicList* list) {
    while (list->head != NULL) {
        ListNode* next = list->head->next;
        free(list->head);
        list->head = next;

        sem_post(&list->countSemaphore);
    }

    pthread_mutex_destroy(&list->mutex);
    sem_destroy(&list->countSemaphore);
    free(list);
}
```
