typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    char* CRC_TAG;
    unsigned char* hashedPassword;
} NFAPI_CRC_INDICATION_PDU_T;

char *generateRandomString(int length) {
    static char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
    char *randomString = NULL;

    if (length) {
        randomString = malloc(sizeof(char) * (length + 1));

        if (randomString) {
            int l = (int)(sizeof(charset) - 1);
            int key = 0;
            for (int n = 0;n < length;n++) {        
                key = rand() % l;   // Random number between 0 and size of charset
                randomString[n] = charset[key];
            }

            randomString[length] = '\0';
        }
    }

    return randomString;
}

unsigned char *hashPassword(const char *password) {
    EVP_MD_CTX *mdctx;
    const EVP_MD *md;
    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len, i;

    OpenSSL_add_all_digests();

    md = EVP_get_digestbyname("sha256");

    if(!md) {
        printf("Unknown message digest %s\n", "sha256");
        return NULL;
    }

    mdctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(mdctx, md, NULL);
    EVP_DigestUpdate(mdctx, password, strlen(password));
    EVP_DigestFinal_ex(mdctx, md_value, &md_len);
    EVP_MD_CTX_free(mdctx);

    unsigned char *hashedPassword = malloc(sizeof(unsigned char) * md_len);
    memcpy(hashedPassword, md_value, md_len);

    return hashedPassword;
}

GArray* createStructures(int N, const char *password) {
    srand((unsigned int) time(NULL));
    GArray *array = g_array_new(FALSE, FALSE, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; ++i) {
        char* randomString = generateRandomString(16); // Generate a 16-character string

        unsigned char *hashedPassword = hashPassword(password);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = i;
        pdu.CRC_TAG = randomString;
        pdu.hashedPassword = hashedPassword;

        g_array_append_val(array, pdu);
    }

    return array;
}
```
