#include <random>
#include <mutex>
#include <vector>
#include <thread>

class RandomNumberService {
public:
    RandomNumberService() : rng_(std::random_device{}()) {}

    uint32_t generateRandomNumber(uint32_t min, uint32_t max) {
        std::lock_guard<std::mutex> lock(mutex_);
        return dist_(rng_, decltype(dist_)::param_type{min, max});
    }

private:
    std::mt19937 rng_;
    std::uniform_int_distribution<uint32_t> dist_;
    std::mutex mutex_;
};

class RandomNumberServiceClient {
public:
    RandomNumberServiceClient(RandomNumberService& service) : service_(service) {}

    void run() {
        while (true) {
            uint32_t randomNum = service_.generateRandomNumber(0, 100);
            // Process the generated number...
        }
    }

private:
    RandomNumberService& service_;
};

int main() {
    RandomNumberService service;
    std::vector<std::thread> threads;

    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(&RandomNumberServiceClient::run, RandomNumberServiceClient(service));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```
