["Here is a basic implementation in C for your requirements. This code does not include all the features you mentioned due to complexity but it gives an idea about how to implement such a hash table. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int key;
    long timestamp;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    int size;
    int count;
    Node** table;
} HashTable;

HashTable* create_table(int size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->size = size;
    ht->count = 0;
    ht->table = calloc(ht->size, sizeof(Node*));
    return ht;
}

void destroy_table(HashTable* ht) {
    for (int i = 0; i < ht->size; ++i) {
        Node* node = ht->table[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->table);
    free(ht);
}

int hash_function(HashTable* ht, int key) {
    return key % ht->size;
}

void insert(HashTable* ht, Record record) {
    if (load_factor(ht) > 0.8) resize(ht);

    Node* node = malloc(sizeof(Node));
    node->record = record;
    int index = hash_function(ht, record.key);

    node->next = ht->table[index];
    ht->table[index] = node;
    ht->count++;
}

Record* search(HashTable* ht, int key) {
    int index = hash_function(ht, key);

    Node* node = ht->table[index];
    while (node != NULL) {
        if (node->record.key == key) return &(node->record);
        node = node->next;
    }
    return NULL;
}

void delete(HashTable* ht, int key) {
    int index = hash_function(ht, key);

    Node* node = ht->table[index];
    Node* prev = NULL;
    while (node != NULL) {
        if (node->record.key == key) {
            if (prev == NULL) ht->table[index] = node->next;
            else prev->next = node->next;

            free(node);
            ht->count--;
            return;
        }
        prev = node;
        node = node->next;
    }
}

double load_factor(HashTable* ht) {
    return (double)ht->count / ht->size;
}

void resize(HashTable* ht) {
    int oldSize = ht->size;
    Node** oldTable = ht->table;

    ht->size *= 2;
    ht->count = 0;
    ht->table = calloc(ht->size, sizeof(Node*));

    for (int i = 0; i < oldSize; ++i) {
        Node* node = oldTable[i];
        while (node != NULL) {
            insert(ht, node->record);
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(oldTable);
}
```
This code is a basic implementation of a hash table with chaining for collision resolution. It includes functions to create and destroy the table, insert records, search for records by key, delete records by key, calculate load factor, and resize the table when necessary. 

Please note that this is a simplified version and does not include all features you mentioned due to complexity. For example, it doesn't handle system dependencies or performance constraints. You would need to add these features as needed based on your specific requirements.
"]

