typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeAll() {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;

        free(temp->data.crcTag);
        free(temp);
    }

    head = NULL;

    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list to manage the dynamic list of structures. Each node in the list contains an NFAPI_CRC_INDICATION_PDU_T structure and a pointer to the next node. The `add` function adds a new node at the beginning of the list, while the `removeAll` function frees all nodes and their associated memory.

