typedef struct {
    long offset;
    int key;
} Record;

Record* initialize(int numOffsets) {
    if (numOffsets > MAX_OFFSETS) {
        fprintf(stderr, "Error: Too many offsets requested. Maximum is %d\n", MAX_OFFSETS);
        exit(EXIT_FAILURE);
    }

    long* offsets = malloc(numOffsets * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    int* keys = malloc(numOffsets * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    }

    Record* records = malloc(numOffsets * sizeof(Record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // seed the random number generator

    for (int i = 0; i < numOffsets; ++i) {
        int uniqueKey;

        do {
            uniqueKey = rand() % MAX_KEYS; // generate a key within the specified range

            // check if the generated key is already in use
            for (int j = 0; j < i; ++j) {
                if (keys[j] == uniqueKey) {
                    uniqueKey = -1;
                    break;
                }
            }
        } while (uniqueKey == -1);

        keys[i] = uniqueKey;
        offsets[i] = rand() % MAX_OFFSET; // generate an offset within the specified range

        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}
```

This code first checks if the requested number of `numOffsets` exceeds the maximum allowable limit. If it does, it prints an error message and exits the program with a failure status. It then allocates memory for three arrays: one for offsets, one for keys, and one for records. The function uses the random number generator to generate unique key-value pairs within specified ranges.

Please note that this code does not handle integration issues with external data sources or error handling for incomplete or corrupted data. It also assumes that `MAX_OFFSETS` and `MAX_KEYS` are defined elsewhere in your program, representing the maximum allowable number of offsets and keys respectively. Similarly, `MAX_OFFSET` is a constant representing the maximum possible value for an offset.
