NFAPI_CRC_INDICATION_PDU_T* generateRandomNfadpIndications(int N, nfapiConfig config, int fd) {
    pthread_mutex_lock(&lock);

    // Allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL; // Handle memory allocation error
    }

    for (int i = 0; i < N; ++i) {
        // Generate a random string and hash it
        unsigned char* randString = malloc(16); // Adjust the size as needed
        if (RAND_bytes(randString, 16) != 1) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle random number generation error
        }

        EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
        if (mdctx == NULL) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle hash context creation error
        }

        const EVP_MD* md = EVP_get_digestbyname(config.supportedHashAlgorithms[0]);
        if (md == NULL) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle unsupported hash algorithm error
        }

        if (!EVP_DigestInit_ex(mdctx, md, NULL)) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle hash initialization error
        }

        if (!EVP_DigestUpdate(mdctx, randString, 16)) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle hash update error
        }

        unsigned char mdValue[EVP_MAX_MD_SIZE];
        unsigned int mdLen;
        if (!EVP_DigestFinal_ex(mdctx, mdValue, &mdLen)) {
            pthread_mutex_unlock(&lock);
            return NULL; // Handle hash finalization error
        }

        EVP_MD_CTX_free(mdctx);

        // Store the generated string and hash value in the structure
        indications[i].RX_UE_INFORMATION_TAG = randString;
        indications[i].hashValue = mdValue;
    }

    pthread_mutex_unlock(&lock);

    return indications;
}
