['Here is an example of how you might implement this in C# using ASP.NET Core Web API and Entity Framework Core. This is a simplified version and does not include all the considerations mentioned above. 

```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Threading.Tasks;
using System.Linq;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;

[ApiController]
[Route("api/[controller]")]
public class PageSectionsController : ControllerBase
{
    private readonly MyDbContext _context;

    public PageSectionsController(MyDbContext context)
    {
        _context = context;
    }

    [HttpPost]
    public async Task<ActionResult> Post([FromBody]PageSection pageSection)
    {
        if (!ModelState.IsValid) return BadRequest();

        await _context.AddAsync(pageSection);
        await _context.SaveChangesAsync();

        // Call external CMS to update HTML content
        var cmsResponse = await ExternalCmsService.UpdateContentAsync(pageSection.Id, pageSection.HtmlContent);

        if (!cmsResponse.IsSuccessStatusCode) return StatusCode((int)cmsResponse.StatusCode);

        return Ok();
    }

    [HttpPut("{id}")]
    public async Task<ActionResult> Put(string id, [FromBody]PageSection pageSection)
    {
        if (!ModelState.IsValid || id != pageSection.Id) return BadRequest();

        _context.Entry(pageSection).State = EntityState.Modified;
        await _context.SaveChangesAsync();

        // Call external CMS to update HTML content
        var cmsResponse = await ExternalCmsService.UpdateContentAsync(id, pageSection.HtmlContent);

        if (!cmsResponse.IsSuccessStatusCode) return StatusCode((int)cmsResponse.StatusCode);

        return Ok();
    }

    [HttpDelete("{id}")]
    public async Task<ActionResult> Delete(string id)
    {
        var pageSection = await _context.PageSections.FindAsync(id);

        if (pageSection == null) return NotFound();

        _context.PageSections.Remove(pageSection);
        await _context.SaveChangesAsync();

        // Call external CMS to remove HTML content
        var cmsResponse = await ExternalCmsService.DeleteContentAsync(id);

        if (!cmsResponse.IsSuccessStatusCode) return StatusCode((int)cmsResponse.StatusCode);

        return Ok();
    }
}
```

