use std::sync::Mutex;

pub struct ConfigDir {
    path: Mutex<Option<String>>,
}

impl ConfigDir {
    pub fn new() -> Self {
        Self {
            path: Mutex::new(None),
        }
    }

    pub fn get_or_create(&self) -> Option<PathBuf> {
        let mut path = self.path.lock().unwrap();

        if path.is_none() {
