        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        byte[] encryptedBytes = cipher.doFinal(data.getBytes());
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }

    private String decrypt(String encryptedData) throws Exception {
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decryptedBytes = cipher.doFinal(Base64.getDecoder().decode(encryptedData));
        return new String(decryptedBytes);
    }

    private String sign(String data) throws Exception {
        rsaSha1Sign.update(data.getBytes());
        byte[] signature = rsaSha1Sign.sign();
        return Base64.getEncoder().encodeToString(signature);
    }

    private boolean verifySignature(String data, String signature) throws Exception {
        Signature verifier = Signature.getInstance(SHA1 + "with" + RSA);
        verifier.initVerify((PublicKey) keyPair.getPublic());
        verifier.update(data.getBytes());
        return verifier.verify(Base64.getDecoder().decode(signature));
    }

    public static void main(String[] args) throws Exception {
        TransactionService service = new TransactionService();
        service.start();

        // Process transactions here

