        free(record);
        return NULL;
    }

    record->timestamp = malloc(sizeof(Timestamp));
    if (record->timestamp == NULL) {
        free(record->string);
        free(record);
        return NULL;
    }

    time(&record->timestamp->timestamp);

    return record;
}

void update_record(_Atomic int* value, Record* record) {
    pthread_mutex_lock(&lock);
    record->value = *value;
    free(record->string);
    asprintf(&record->string, "%d%ld", record->value, record->timestamp->timestamp);
    time(&record->timestamp->timestamp);
    pthread_mutex_unlock(&lock);
}

void cleanup(Record* record) {
    assert(record != NULL);

    free(record->string);
    free(record->timestamp);
    free(record);
}
