```javascript
const fs = require('fs');
const async = require('async');
const path = require('path');
let cache = {};

function processFile(filePath, callback) {
    if (cache[filePath] && Date.now() - cache[filePath].timestamp < 15 * 60 * 1000) {
        // Use cached data
        callback(null, cache[filePath].data);
    } else {
        console.log('Starting read:', new Date());
        fs.readFile(filePath, 'utf8', (err, data) => {
            if (err) return callback(err);

            // Cache the result
            cache[filePath] = { timestamp: Date.now(), data };

            console.log('Completed read:', new Date());
            callback(null, data);
        });
    }
}

function processFilesInDir(dirPath, timeout = 5000) {
    return new Promise((resolve, reject) => {
        fs.readdir(dirPath, (err, files) => {
            if (err) return reject(err);

            async.mapLimit(files.map(file => path.join(dirPath, file)), 15, processFile, (err, results) => {
                if (err) return reject(err);

                // Aggregate the results here
                resolve(results);
            });
        });

        setTimeout(() => reject('Operation timed out'), timeout);
    });
}
```
This function reads all files in a directory, processes each file's content asynchronously using `fs.readFile`, and returns an array of the processed results. It uses caching to avoid redundant reads for recently accessed files. The operation is limited to 15 concurrent file reads at any given time to manage memory usage.

