    int value;
    char name[64];
    time_t timestamp;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int allocate(long *offsets, int *keys, record **records, size_t maxSize) {
    if (3*sizeof(void*) > maxSize) return -1; // not enough space for 3 pointers

    pthread_mutex_lock(&lock);
    *offsets = malloc(maxSize/3);
    if (*offsets == NULL) {
        pthread_mutex_unlock(&lock);
        return -2; // failed to allocate memory for offsets
    }

    *keys = malloc(maxSize/3);
    if (*keys == NULL) {
        free(*offsets);
        pthread_mutex_unlock(&lock);
        return -2; // failed to allocate memory for keys
    }

    *records = malloc(sizeof(record)*maxSize/3);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&lock);
        return -2; // failed to allocate memory for records
    }

    srand(time(NULL));
    for (size_t i = 0; i < maxSize/3; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();
        strcpy((*records)[i].name, "default");
        (*records)[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&lock);
    return 0; // success
}
