['Here's a basic implementation of your request using C programming language. This code is simplified and does not cover all the requirements you mentioned, but it gives an idea about how you can start implementing this function. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void deserializeAndInitializeNfapiPduArray(char *filename, NFAPI_CRC_INDICATION_PDU_T **array, int *size) {
    FILE *file = fopen(filename, "rb"); // Open file in binary mode
    if (file == NULL) {
        printf("Error opening the file.\n");
        return;
    }

    pthread_mutex_lock(&mutex); // Lock mutex to ensure thread safety

    fseek(file, 0L, SEEK_END); // Move pointer to end of file
    long numbytes = ftell(file); // Get the current position (size in bytes)
    rewind(file); // Rewind the file pointer to start

    *array = malloc(numbytes); // Allocate memory for array
    if (*array == NULL) {
        printf("Error allocating memory.\n");
        pthread_mutex_unlock(&mutex); // Unlock mutex before return
        fclose(file);
        return;
    }

    *size = numbytes / sizeof(NFAPI_CRC_INDICATION_PDU_T); // Calculate size of array

    if (fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *size, file) != *size) {
        printf("Error reading the file.\n");
        free(*array); // Free allocated memory before return
        pthread_mutex_unlock(&mutex);
        fclose(file);
        return;
    }

    for (int i = 0; i < *size; i++) {
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Assign random value to CRCFLAG
    }

    pthread_mutex_unlock(&mutex); // Unlock mutex after operation
    fclose(file);
}
