#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct TrafficEvent {
    time_t timestamp;
    char eventType[20];
    int uniqueID;
} TrafficEvent;

typedef struct EventNode {
    TrafficEvent* event;
    struct EventNode* next;
} EventNode;

// Global variable to hold the head of the linked list
EventNode* head = NULL;

void addTrafficEvent(time_t timestamp, char* eventType, int uniqueID) {
    TrafficEvent* newEvent = (TrafficEvent*) malloc(sizeof(TrafficEvent));

    if (newEvent == NULL) {
        printf("Failed to allocate memory for new traffic event.\n");
        return;
    }

    newEvent->timestamp = timestamp;
    strncpy(newEvent->eventType, eventType, sizeof(newEvent->eventType));
    newEvent->uniqueID = uniqueID;

    EventNode* newNode = (EventNode*) malloc(sizeof(EventNode));

    if (newNode == NULL) {
        printf("Failed to allocate memory for new node.\n");
        free(newEvent);
        return;
    }

    newNode->event = newEvent;
    newNode->next = head;
    head = newNode;
}

void removeTrafficEventsByCondition(int (*condition)(TrafficEvent*)) {
    EventNode** pp = &head;

    while(*pp) {
        if (condition((*pp)->event)) {
            EventNode* toRemove = *pp;
            *pp = toRemove->next;

            free(toRemove->event);
            free(toRemove);
        } else {
            pp = &(*pp)->next;
        }
    }
}

void generateSummaryReport(time_t start, time_t end) {
    for (EventNode* node = head; node != NULL; node = node->next) {
        if (node->event->timestamp >= start && node->event->timestamp <= end) {
            printf("Timestamp: %ld\n", node->event->timestamp);
            printf("Event Type: %s\n", node->event->eventType);
            printf("Unique ID: %d\n", node->event->uniqueID);
        }
    }
}
```
