#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef struct Event {
    char *data;
    struct Event *next;
} Event;

Event *events = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processFile(void *arg) {
    FILE *file = fopen((char*) arg, "r");
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), file)) {
        pthread_mutex_lock(&lock);

        Event *newEvent = malloc(sizeof(Event));
        newEvent->data = strdup(buffer);
        newEvent->next = events;
        events = newEvent;

        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return NULL;
}

void* generateReport(void *arg) {
    FILE *outputFile = fopen((char*) arg, "w");
    Event *currentEvent = events;

    while (currentEvent != NULL) {
        fprintf(outputFile, "%s", currentEvent->data);
        free(currentEvent->data);

        Event *nextEvent = currentEvent->next;
        free(currentEvent);
        currentEvent = nextEvent;
    }

    fclose(outputFile);
    return NULL;
}

int main() {
    char* inputFiles[] = {"file1.log", "file2.log"};
    int numInputFiles = 2;
    pthread_t threads[numInputFiles + 1];

    for (int i = 0; i < numInputFiles; ++i) {
        if (pthread_create(&threads[i], NULL, processFile, inputFiles[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numInputFiles; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    if (pthread_create(&threads[numInputFiles], NULL, generateReport, "report.txt")) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    if (pthread_join(threads[numInputFiles], NULL)) {
        fprintf(stderr, "Error joining thread\n");
        return 2;
    }

    return 0;
}
```
