    struct Node* next;
    struct Node* prev;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;

int createAndPopulateList(void) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for a new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory: %s", strerror(errno));
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Populate the node with data
    newNode->data = generateData();  // This function should be implemented to generate valid data
    if (newNode->data == NULL) {
        syslog(LOG_ERR, "Failed to generate data");
        free(newNode);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Add the new node to the list
    if (head == NULL) {
        head = newNode;
        newNode->next = NULL;
        newNode->prev = NULL;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
        newNode->prev = current;
        newNode->next = NULL;
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}
```
