```c
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} EncryptionSession;

EncryptionSession* create_session(const char *algorithm, const unsigned char *key) {
    // Initialize the encryption session with the given algorithm and key
    EncryptionSession *session = malloc(sizeof(EncryptionSession));
    EVP_CIPHER_CTX_init(&session->ctx);

    if (EVP_EncryptInit_ex(session->ctx, EVP_get_cipherbyname(algorithm), NULL, key, NULL) != 1) {
        free(session);
        return NULL; // Error initializing encryption session
    }

    return session;
}

int encrypt(EncryptionSession *session, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;

    if (EVP_EncryptUpdate(session->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        return -1; // Error encrypting data
    }

    return len;
}

void destroy_session(EncryptionSession *session) {
    EVP_CIPHER_CTX_cleanup(&session->ctx);
    free(session);
}
```
