            GameParameters.PlayerMovementVelocity = config.playerMovementVelocity;
        }
        catch (Exception ex)
        {
            // Handle exceptions here, e.g., log the error and use default values
        }
    }

    public object GetConfigurationValue(string key)
    {
        if (!_cache.TryGetValue(key, out var value))
        {
            LoadConfiguration();
            _cache.TryGetValue(key, out value);
        }

        return value;
    }

    public void SaveConfiguration()
