    } else if (pid < 0) { // Fork failed
        printf("Fork failed!\n");
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);
        childExitStatus = WEXITSTATUS(status);
    }
}

// Function to retry command execution with exponential backoff intervals
void retryCommandExecution(char *command, char **args, int maxRetries) {
    for (int i = 1; i <= maxRetries; i++) {
        execShellCommand(command, args);
        if (childExitStatus == 0) return; // Command executed successfully
        sleep(pow(2, i)); // Exponential backoff interval
    }
}

// Function to compact the list and remove unused entries
void compactList() {
    pthread_mutex_lock(&lock);
    int newSize = 0;
    for (int i = 0; i < listSize; i++) {
        if (list[i].tag != -1) { // Assuming -1 indicates unused entries
            list[newSize] = list[i];
            newSize++;
        }
    }
    listSize = newSize;
    pthread_mutex_unlock(&lock);
}

// Function to pause and resume command execution
void toggleCommandExecution(int isPaused) {
    if (isPaused && pid != 0) { // Pause execution
        kill(pid, SIGSTOP);
    } else if (!isPaused && pid != 0) { // Resume execution
        kill(pid, SIGCONT);
    }
}
```
