Record* manageMemory(size_t num_records, long min_offset, long max_offset, size_t identifier_range, size_t max_memory_allowed) {
    // Calculate the required memory for each array
    size_t offsets_mem = num_records * sizeof(long);
    size_t identifiers_mem = identifier_range * sizeof(int);
    size_t records_mem = num_records * sizeof(Record);

    // Check if the total memory requested exceeds the maximum allowed
