    int* identifiers = malloc(identifiers_mem);
    Record* records = malloc(records_mem);

    if (offsets == NULL || identifiers == NULL || records == NULL) {
        // Free any allocated memory and return NULL in case of allocation failure
        free(offsets);
        free(identifiers);
        free(records);
        return NULL;
    }

    // Initialize the offset array with sequential values within the valid range
