void initialize() {
    if (sem_init(&semaphore, 0, 1) == -1) {
        perror("Semaphore initialization failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&lock, NULL);
}

void addNode(UserSessionData data) {
    sem_wait(&semaphore);
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    sem_post(&semaphore);
}

UserSessionData getNodeByID(int sessionID) {
