    pthread_mutex_lock(&lock);
    Node* temp = head;
    while (temp != NULL) {
        if (temp->data.sessionID == sessionID) {
            result = temp->data;
            break;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&lock);

    return result;
}
