typedef struct {
    // Add your PUSCH_TX_REQ_PDU and associated parameters here
} NFAPI_MESSAGE_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_MESSAGE_T** messages;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    pthread_mutex_init(&array->lock, NULL);
    array->messages = NULL;
    array->size = 0;
    array->capacity = 0;
    return array;
}

void addMessage(DynamicArray* array, NFAPI_MESSAGE_T* message) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        int newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;
        NFAPI_MESSAGE_T** newMessages = realloc(array->messages, sizeof(NFAPI_MESSAGE_T*) * newCapacity);

        if (newMessages == NULL) {
            // Handle error here
        } else {
            array->messages = newMessages;
            array->capacity = newCapacity;
        }
    }

    array->messages[array->size] = message;
    array->size++;

    pthread_mutex_unlock(&array->lock);
}

void removeMessage(DynamicArray* array, int index) {
    pthread_mutex_lock(&array->lock);

    if (index < 0 || index >= array->size) {
        // Handle error here
    } else {
        free(array->messages[index]);

        for (int i = index; i < array->size - 1; i++) {
            array->messages[i] = array->messages[i + 1];
        }

        array->size--;
    }

    pthread_mutex_unlock(&array->lock);
}
```
This code creates a dynamic array that can store NFAPI_MESSAGE_T structures. It uses a mutex to ensure thread safety, and it dynamically allocates memory for the messages as needed. When a message is no longer needed, it frees its memory and shifts all subsequent messages up in the array to fill the gap.
