```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

struct Record {
    long offset;
    int key;
    char* data;
};

// Assuming an external function that provides initial keys
extern int get_key(); 

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* generate_suffix(int length) {
    char* suffix = malloc((length + 1) * sizeof(char));
    if (suffix == NULL) return NULL;

    for (int i = 0; i < length; ++i) {
        suffix[i] = 'a' + rand() % 26; // Generate a random lowercase letter
    }
    suffix[length] = '\0';

    return suffix;
}

char* generate_string(int key, int max_len) {
    char buffer[32];
    sprintf(buffer, "%d", key);

    int len = strlen(buffer);
    if (len > max_len - 10) return NULL; // Leave space for random suffix

    char* string = malloc((max_len + 1) * sizeof(char));
    if (string == NULL) return NULL;

    strcpy(string, buffer);

    char* suffix = generate_suffix(max_len - len - 10); // Leave space for random suffix
    if (suffix == NULL) {
        free(string);
        return NULL;
    }

    strcat(string, "-");
    strcat(string, suffix);
    free(suffix);

    return string;
}

struct Record* initialize_records(int num_records) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    struct Record* records = malloc(num_records * sizeof(struct Record));
    if (records == NULL) return NULL;

    for (int i = 0; i < num_records; ++i) {
        int key = get_key(); // Get initial key from external source

        char* data = generate_string(key, 1024); // Generate string with random suffix
        if (data == NULL) {
            for (int j = 0; j < i; ++j) free(records[j].data); // Free previously allocated memory
            free(records);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i].offset = rand(); // Generate random offset value
        records[i].key = key;
        records[i].data = data;
    }

    pthread_mutex_unlock(&lock); // Unlock after successful initialization

    return records;
}
```
This code assumes that the `get_key()` function is thread-safe and provides a valid key for each record. It also uses a mutex to ensure thread safety when calling `initialize_records` from multiple threads. The memory allocated for the strings is released in case of failure, ensuring no leaks even if an error occurs during initialization.
