#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    // Add fields here
} NFAPI_MESSAGE_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_MESSAGE_T *messages;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    arr->messages = malloc(initial_capacity * sizeof(NFAPI_MESSAGE_T));
    if (arr->messages == NULL) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    free(arr->messages);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_message(DynamicArray *arr, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_MESSAGE_T *new_messages = realloc(arr->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));

        if (new_messages == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Failed to resize array
        }

        arr->messages = new_messages;
        arr->capacity = new_capacity;
    }

    arr->messages[arr->size++] = message;

    pthread_mutex_unlock(&arr->lock);

    return 0; // Success
}
```
