["Here's a basic implementation of such a configuration management system in Node.js using `dotenv` for environment variables and `fs` for JSON files. This code does not include caching or integration with other services, but it provides a good starting point for building out these features. 

```javascript
const fs = require('fs');
require('dotenv').config();

class ConfigManager {
    constructor(environment) {
        this.environment = environment;
        this.config = {};
        this.loadDefaults();
        this.loadFromEnvVars();
        this.loadFromFile();
    }

    loadDefaults() {
        // Load default configurations here
        this.config = { ...this.config, ...{ /* Default Configurations */ } };
    }

    loadFromEnvVars() {
        // Load environment-specific configurations from process.env
        const envConfig = Object.keys(process.env)
            .reduce((accumulator, key) => {
                accumulator[key] = process.env[key];
                return accumulator;
            }, {});

        this.config = { ...this.config, ...envConfig };
    }

    loadFromFile() {
        // Load configurations from a JSON file in the specified directory
        try {
            const data = fs.readFileSync(`./${this.environment}.json`);
            this.config = { ...this.config, ...JSON.parse(data) };
        } catch (err) {
            console.error('Error loading configuration file:', err);
            // Generate a recommended template if no config file exists
            fs.writeFileSync(`./${this.environment}.json`, JSON.stringify({ /* Recommended Template */ }, null, 2));
        }
    }
}
```

