sem_t semaphore;

void resize(size_t newCapacity) {
    NFAPI_MESSAGE_T* newMessages = realloc(messages, newCapacity * sizeof(NFAPI_MESSAGE_T));
    if (newMessages == NULL && newCapacity != 0) {
        // Handle error
    } else {
        messages = newMessages;
        capacity = newCapacity;
    }
}

void addMessage(NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&lock);

    if (size == capacity) {
        resize(capacity * 2 + 1); // Dynamic scaling strategy
    }

    messages[size++] = message;

    sem_post(&semaphore); // Signal that a new message is available

    pthread_mutex_unlock(&lock);
}

NFAPI_MESSAGE_T getMessage() {
    sem_wait(&semaphore); // Wait for a new message to be added

    pthread_mutex_lock(&lock);

    NFAPI_MESSAGE_T message = messages[--size];

    if (size < capacity / 4) {
        resize(capacity / 2); // Dynamic scaling strategy
    }

    pthread_mutex_unlock(&lock);

    return message;
}
