['Here's an example of how you might implement this in JavaScript using async/await syntax and DOMParser for parsing and validating the HTML snippets:

```javascript
async function integrateUgcIntoFooter(apiEndpoint) {
    try {
        // Fetch UGC from API asynchronously
        const response = await fetch(apiEndpoint);

        if (!response.ok) {
            throw new Error('Network response was not ok');
        }

        let ugcSnippet = await response.text();

        // Sanitize and format UGC snippets as block-level elements
        const parser = new DOMParser();
        let doc = parser.parseFromString(ugcSnippet, 'text/html');

        if (doc.body === null) {
            throw new Error('Invalid HTML snippet');
        }

        // Escape UGC to prevent XSS attacks
        ugcSnippet = escapeHtml(ugcSnippet);

        // Get the footer element and append the sanitized UGC
        let footerElement = document.querySelector('footer');

        if (footerElement) {
            footerElement.innerHTML += ugcSnippet;
        } else {
            throw new Error('Footer element not found');
        }
    } catch (error) {
        console.log(`Error: ${error}`);

        // Handle error gracefully, e.g., by displaying a default message or retry button
    }
}

// Helper function to escape HTML entities
function escapeHtml(text) {
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };

    return text.replace(/[&<>"']/g, function(m) { return map[m]; });
}
