function traverseDocument(selector, callback) {
    let visited = new Set();
    let result = [];

    function visitNode(node) {
        if (visited.has(node)) return;

        visited.add(node);

        if (callback(node)) {
            result.push(node);
        }

        node.childNodes.forEach(visitNode);
    }

    visitNode(document.body);

    return result;
}

function callback(node) {
