    if (authHeader) {
        const token = authHeader.split(' ')[1];

        jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
            if (err) {
                return res.sendStatus(403);
            }

            req.user = user;
            next();
        });
    } else {
        res.sendStatus(401);
    }
};

// Route for login
app.post('/login', (req, res) => {
  // Authenticate the user and generate JWT token
});

// Protected route with JWT authentication
app.get('/profile', authenticateJWT, async (req, res) => {
    const cacheKey = `user_${req.user.id}`;

    // Check if data is in Redis cache
    redisClient.get(cacheKey, (err, reply) => {
        if (reply) {
            return res.json(JSON.parse(reply));
        } else {
            // If not in cache, fetch from MongoDB and store in cache
            User.findById(req.user.id, (err, user) => {
                redisClient.setex(cacheKey, 60, JSON.stringify(user));
                return res.json(user);
            });
        }
    });
});

app.listen(3000, () => console.log('Server running on port 3000'));
