#include <random>
#include <chrono>
#include <thread>

std::mt19937 rng(std::chrono::steady_clock::now().time_since_epoch().count());

class Character {
public:
    int health = 100;
    float movementSpeed = 1.0f;
    std::chrono::system_clock::time_point lastAttackTime = std::chrono::system_clock::now();

    void attackA() {
        if (std::chrono::duration<double>(std::chrono::system_clock::now() - lastAttackTime).count() < 9) return;
        int damage = std::uniform_int_distribution<>(0, 1)(rng) ? 50 : 0;
        health -= damage;
        log("Attack A: " + std::to_string(damage));
    }

    void attackB() {
        if (std::chrono::duration<double>(std::chrono::system_clock::now() - lastAttackTime).count() < 12) return;
        int dodge = std::uniform_int_distribution<>(0, 9)(rng);
        log("Attack B: " + (dodge ? "Dodged" : "Failed to dodge"));
    }

    void attackC() {
        if (std::chrono::duration<double>(std::chrono::system_clock::now() - lastAttackTime).count() < 6) return;
        health += 100;
        movementSpeed *= 0.5f;
        std::this_thread::sleep_for(std::chrono::seconds(4));
        movementSpeed /= 0.5f;
        log("Attack C: Healed and slowed");
    }

    void attackD() {
        if (std::chrono::duration<double>(std::chrono::system_clock::now() - lastAttackTime).count() < 15) return;
        health += 100;
        log("Attack D: Healed");
    }

    void log(const std::string& message) {
        std::ofstream file("combat_log.txt", std::ios_base::app);
        if (file.is_open()) {
            file << "[" << std::chrono::system_clock::now() << "] " << message << "\n";
            file << "Character health: " << health << ", movement speed: " << movementSpeed << "\n\n";
        } else {
            std::cerr << "Failed to open log file!\n";
        }
    }
};
```

