['```c
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <arpa/inet.h>

typedef struct {
    char *hostname;
    u_char ip[INET6_ADDRSTRLEN];
} DNSCacheEntry;

DNSCacheEntry dnsCache[1024] = {{NULL, {0}}}; // Simple cache for DNS resolution results
int cacheSize = 0;

u_char *resolve(const char *hostname) {
    for (int i = 0; i < cacheSize; ++i) {
        if (!strcmp(dnsCache[i].hostname, hostname)) {
            return dnsCache[i].ip; // Return cached IP address
        }
    }

    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_UNSPEC;  // Allow both IPv4 and IPv6 addresses
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        perror("Failed to resolve hostname");
        return NULL; // Return null on failure
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *) res->ai_addr;
    void *addr;

    if (res->ai_family == AF_INET) {  // IPv4 address
        addr = &(ipv4->sin_addr);
    } else {  // IPv6 address
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *) res->ai_addr;
        addr = &(ipv6->sin6_addr);
    }

    inet_ntop(res->ai_family, addr, dnsCache[cacheSize].ip, sizeof(dnsCache[cacheSize].ip));
    dnsCache[cacheSize].hostname = strdup(hostname); // Cache hostname and IP address
    ++cacheSize;

    freeaddrinfo(res);  // Free the linked list of addrinfo structures

    return dnsCache[cacheSize - 1].ip;
}

int convert_and_resolve(const char *input_filename, const char *output_filename, const char *hostname) {
    if (access("/usr/bin/convert", X_OK)) { // Check if third-party tool is available and executable
        perror("Third-party tool not found or not executable");
        return 1;
    }

    FILE *input = fopen(input_filename, "r");
    if (input == NULL) {
        perror("Failed to open input file");
        return 1;
    }

    u_char *ip = resolve(hostname); // Resolve hostname to IP address
    if (ip == NULL) {
        fclose(input);
        return 1;
    }

    char command[256];
    snprintf(command, sizeof(command), "/usr/bin/convert %s %s", input_filename, output_filename); // Construct third-party tool command

    if (system(command) != 0) { // Execute the command and check its return value
        perror("Failed to convert file");
        fclose(input);
        return 1;
    }

    fclose(input);
    return 0;
}
```
