DynamicArray* createDynamicArray() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->frames = NULL;
    array->numFrames = 0;
    sem_init(&array->mutex, 0, 1);
    return array;
}

void addFrameToArray(DynamicArray* array, LTE_PHY_RX_FRAME_INFO_T* frame) {
    sem_wait(&array->mutex);

    array->frames = realloc(array->frames, sizeof(LTE_PHY_RX_FRAME_INFO_T*) * (array->numFrames + 1));
    array->frames[array->numFrames] = frame;
    array->numFrames++;

    sem_post(&array->mutex);
}

