public class FileManager {
    private static final Logger logger = LoggerFactory.getLogger(FileManager.class);

    public void manageDirectoryStructure(String filePath) throws IOException, InterruptedException {
        if (SystemUtils.IS_OS_WINDOWS) {
            deleteWindowsFileOrDir(filePath);
        } else {
            deleteUnixFileOrDir(filePath);
        }
    }

    private void deleteWindowsFileOrDir(String filePath) throws IOException, InterruptedException {
        ProcessBuilder builder = new ProcessBuilder("cmd.exe", "/c", "del /F/Q/S \"" + filePath + "\"" );
        executeCommandAndLogOutput(builder);
    }

    private void deleteUnixFileOrDir(String filePath) throws IOException, InterruptedException {
        ProcessBuilder builder = new ProcessBuilder("sh", "-c", "rm -rf \"" + filePath + "\"" );
        executeCommandAndLogOutput(builder);
    }

    private void executeCommandAndLogOutput(ProcessBuilder processBuilder) throws IOException, InterruptedException {
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            logger.info("Output: {}", line);
        }

        reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        while ((line = reader.readLine()) != null) {
            logger.error("Error: {}", line);
        }

        int exitCode = process.waitFor();
        if (exitCode == 0) {
            logger.info("Command executed successfully");
        } else {
            logger.error("Failed to execute command with exit code: {}", exitCode);
        }
    }
}
```
