        std::cerr << "Missing or invalid access_token\n";
        return;
    }
    if (!parsedJson.contains("expires_in") || !parsedJson["expires_in"].is_number() || 
        parsedJson["expires_in"] <= 0) {
        std::cerr << "Missing or invalid expires_in\n";
        return;
    }
    if (!parsedJson.contains("token_type") || !parsedJson["token_type"].is_string() || 
        parsedJson["token_type"] != "Bearer") {
        std::cerr << "Missing or invalid token_type\n";
        return;
    }

    // Load and apply additional validation rules from config file if provided
    if (!configFilePath.empty() && filesystem::exists(configFilePath)) {
        try {
            std::ifstream configStream(configFilePath);
