            if (configJson.contains("additional_validation") && 
                parsedJson["additional_field"] != configJson["additional_value"]) {
                std::cerr << "Additional validation failed\n";
                return;
            }
        } catch (const json::exception& e) {
            std::cerr << "Failed to load and parse config file: " << e.what() << '\n';
            return;
        }
    }

    // Search for target string in collection and modify it if found
    auto it = find(collection.begin(), collection.end(), target);
    if (it != collection.end()) {
