```cpp
#include <openssl/md5.h>
#include <boost/pool/pool_alloc.hpp>
#include <vector>
#include <algorithm>
#include <iostream>
#include <random>
#include <gtest/gtest.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

std::string md5Hash(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input.c_str(), input.size(), digest);    

    std::stringstream ss;
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
         ss << std::hex << std::setw(2) << std::setfill('0') << (unsigned int)digest[i];

    return ss.str();
}

double computeMedian(std::vector<int>& nums) {
    size_t n = nums.size() / 2;
    std::nth_element(nums.begin(), nums.begin()+n, nums.end());

    if (nums.size() % 2 == 1) {
        return nums[n];
    } else {
        std::nth_element(nums.begin(), nums.begin() + n - 1, nums.end());
        return (nums[n-1] + nums[n]) / 2.0;
    }
}

std::pair<std::string, double> processInput(const std::string& input) {
    const int min = 0, max = 1000000;

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(min,max);

    boost::pool<> p(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    std::vector<int> nums;

    int num;
    while (std::cin >> num) {
        if (num < min || num > max) {
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(p.ordered_malloc());
        new (pdu) NFAPI_CRC_INDICATION_PDU_T;

        pdu->RX_UE_INFORMATION_TAG = num;
        pdu->RNTI = distribution(generator);
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = distribution(generator) % 2 == 0 ? true : false;

        nums.push_back(num);
    }

    std::sort(nums.begin(), nums.end());
    double median = computeMedian(nums);

    return {md5Hash(input), median};
}
```

