        uploadedFileUrl = response.data.fileUrl; // Assuming the server returns the file URL in the response data
        break;
      } catch (error) {
        console.log(`Upload retry failed: ${error}`);
      }
    }
  }

  // Store the file metadata, including the uploaded file URL, in the CMS API endpoint.
  try {
    await axios.post(cmsApiEndpoint, { fileUrl: uploadedFileUrl });
  } catch (error) {
    console.log(`Storing metadata failed: ${error}`);

    // Handle potential network issues or server-side errors during this step by retrying the operation up to three times.
