['Here is a basic implementation of your requirements using Rust and Tokio library. This code does not include all the features you mentioned like dynamic throttling based on system metrics, integration with an external monitoring service, configurable retry strategies for failed requests, logging detailed metrics, or handling unexpected external service disruptions.

```rust
use std::time::Duration;
use tokio::net::TcpStream;
use tokio::sync::Semaphore;
use tokio::time::delay_for;
use tokio::time::timeout;
use tokio::time::Timeout;
use url::Url;
use std::env;
use std::error::Error;
use std::process;
use std::str::FromStr;
use futures::future::join_all;
use futures::stream::StreamExt;

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintlnln![r"Usage: program <url> <parallel_requests> <duration_seconds>"];
        process::exit(1);
    }

    let url = Url::parse(&args[1])?;
    let parallel_requests = usize::from_str(&args[2])?;
    let duration_secs = u64::from_str(&args[3])?;

    let semaphore = Semaphore::new(parallel_requests);
    let timeout = Timeout::new(Duration::from_secs(10));

    let start = std::time::Instant::now();
    while std::time::Instant::now() - start < Duration::from_secs(duration_secs) {
        let _ = semaphore.acquire().await;
        tokio::spawn(async move {
            if let Err(_e) = timeout(do_request(&url), None).await {
                eprintlnln![r"Request to {} failed", url];
            }
            semaphore.release();
        });
    }

    // Wait for all requests to finish
    while !semaphore.is_empty() {
        delay_for(Duration::from_millis(10)).await;
    }

    Ok(())
}

async fn do_request(url: &Url) -> Result<(), Box<dyn Error>> {
    let socket = TcpStream::connect(&*format![r"{}:80", url.host_str().unwrap()]).await?;
    let request = format![r"GET / HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n", url.host_str().unwrap()];
    socket.write_all(request.as_bytes()).await?;
    let mut response = vec![0u8; 1024];
    match socket.read(&mut response).await {
        Ok(_) => {}
        Err(_e) => return Err(r"Failed to read from socket".into()),
    }
    Ok(())
}
```
This code creates a specified number of parallel requests to the target URL for a specified duration. It uses a semaphore to limit the number of concurrent requests, and each request is limited by a timeout. The program will exit if it cannot parse the command line arguments or connect to the server. 

Please note that this code does not include all the features you mentioned like dynamic throttling based on system metrics, integration with an external monitoring service, configurable retry strategies for failed requests, logging detailed metrics, or handling unexpected external service disruptions. You would need to add these features yourself or hire a professional developer to do so.
']

