#define DNS_RESOLUTION_FAILED -1
#define OBJECT_INTEGRITY_CHECK_FAILED -2
#define MEMORY_ALLOCATION_FAILED -3

int loadSystemState(const char *hostname, u_char **ip) {
    struct addrinfo hints;
    struct addrinfo *result = NULL;
    int retval;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    for (int i = 0; i < 3; ++i) { // Retry logic
        retval = getaddrinfo(hostname, NULL, &hints, &result);

        if (retval == 0) break;
        else sleep(1); // Sleep for 1 second before retrying
    }

    if (retval != 0) {
        fprintf(stderr, "Error in DNS resolution: %s\n", gai_strerror(retval));
        return DNS_RESOLUTION_FAILED;
    }

    *ip = malloc(result->ai_addrlen);

    if (*ip == NULL) {
        perror("Memory allocation failed");
        freeaddrinfo(result);
        return MEMORY_ALLOCATION_FAILED;
    }

    memcpy(*ip, &((struct sockaddr_in *) result->ai_addr)->sin_addr, result->ai_addrlen);

    freeaddrinfo(result);

    // Load state object from persistent storage and validate it
    if (loadStateObjectFromStorage() != SUCCESS) {
