    if (numRead != *numStructs) {
        printf("Error reading data\n");
        free(data);
        fclose(file);
        return NULL;
    }

    // Validate the CRC flag against a calculated checksum
    for (size_t i = 0; i < *numStructs; ++i) {
        if (!validateCRC(&data[i])) {
            printf("Error validating data\n");
            free(data);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return data;
}
```
