#include <stdlib.h>
#include <string.h>

typedef struct UEContext {
    int PDUSessionID;
    char* STMSI;
    char* GUTI;
    int activeSessionFlag;
} UEContext;

UEContext** list = NULL;
int count = 0;
int activeCount = 0;

void addToList(UEContext* context) {
    if (count >= 512) {
        printf("Maximum number of elements reached.\n");
        return;
    }

    // Check for unique S-TMSI and GUTI values
    for (int i = 0; i < count; ++i) {
        if (!strcmp(list[i]->STMSI, context->STMSI) || !strcmp(list[i]->GUTI, context->GUTI)) {
            printf("Duplicate S-TMSI or GUTI value.\n");
            return;
        }
    }

    // Check active session limit
    if (context->activeSessionFlag && activeCount >= 32) {
        printf("Active session limit reached.\n");
        return;
    }

    list = realloc(list, sizeof(UEContext*) * (count + 1));
    list[count] = context;
    ++count;

    if (context->activeSessionFlag) {
        ++activeCount;
    }
}

void removeFromList(int index) {
    if (index < 0 || index >= count) {
        printf("Invalid index.\n");
        return;
    }

    free(list[index]->STMSI);
    free(list[index]->GUTI);
    free(list[index]);

    --count;
    if (list[index]->activeSessionFlag) {
        --activeCount;
    }

    for (int i = index; i < count; ++i) {
        list[i] = list[i + 1];
    }
}

void updateList(int index, UEContext* context) {
    if (index < 0 || index >= count) {
        printf("Invalid index.\n");
        return;
    }

    // Check for unique S-TMSI and GUTI values
    for (int i = 0; i < count; ++i) {
        if (i != index && (!strcmp(list[i]->STMSI, context->STMSI) || !strcmp(list[i]->GUTI, context->GUTI))) {
            printf("Duplicate S-TMSI or GUTI value.\n");
            return;
        }
    }

    // Check active session limit
    if (context->activeSessionFlag && list[index]->activeSessionFlag != context->activeSessionFlag) {
        if (list[index]->activeSessionFlag && activeCount >= 32) {
            printf("Active session limit reached.\n");
            return;
        } else if (!list[index]->activeSessionFlag && activeCount > 32) {
            --activeCount;
        } else if (context->activeSessionFlag) {
            ++activeCount;
        }
    }

    free(list[index]->STMSI);
    free(list[index]->GUTI);
    list[index] = context;
}
```
