z_stream* initializeAndCompress(int numPackets, DataSourceCallback callback, CompressionAlgorithm algorithm) {
    static z_stream strm = {0}; // Static to avoid memory leak

    switch (algorithm) {
        case DEFLATE:
            if (deflateInit(&strm, Z_DEFAULT_COMPRESSION) != Z_OK) {
                fprintf(stderr, "Failed to initialize deflate\n");
                return NULL;
            }
            break;
        case ZLIB:
