                fprintf(stderr, "Failed to initialize inflate\n");
                return NULL;
            }
            break;
        // Add cases for LZO and BZIP2 here...
        case NOOP:
            // No compression, just pass through data
            break;
    }

    int retryCount = 0;
    while (numPackets > 0) {
        LTE_Packet packet;

        // Retry with exponential backoff on failure
        for (int i = 0; i <= retryCount; ++i) {
            callback(&packet);

            switch (algorithm) {
                case DEFLATE:
                    deflate(&strm, Z_SYNC_FLUSH); // Adjust flush mode as needed
                    break;
                case ZLIB:
                    inflate(&strm, Z_SYNC_FLUSH); // Adjust flush mode as needed
                    break;
                // Add cases for LZO and BZIP2 here...
                case NOOP:
                    // No compression, just pass through data
                    break;
            }
        }

        --numPackets;
    }

    return &strm;
}
