import os
import logging
from threading import Thread, Lock

logging.basicConfig(filename='fileProcessing.log', level=logging.INFO)
lock = Lock()

def processChunk(chunk):
    # Process the chunk here...
    pass

def processLargeFile(path, chunk_size=1024*1024):  # Default chunk size is 1MB
    if not os.path.exists(path):
        logging.error('File does not exist')
        return

    with open(path, 'rb') as f:
        while True:
            lock.acquire()
            try:
                chunk = f.read(chunk_size)
                if not chunk:  # End of file
                    break

                thread = Thread(target=processChunk, args=(chunk,))
                thread.start()
                thread.join()  # Wait for the thread to finish before reading next chunk
            finally:
                lock.release()

    logging.info('File processing completed')
