```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicList {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list(size_t initialCapacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (atomic_load(&list->size) > 0 && 
        list->data[atomic_load(&list->size) - 1].RNTI == element.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI already exists in the last element
    }

    if (atomic_load(&list->size) >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Failed to resize the list
        }

        list->data = newData;
        list->capacity = newCapacity;
    }

    size_t index = atomic_fetch_add(&list->size, 1);
    list->data[index] = element;

    pthread_mutex_unlock(&list->lock);
    return 0; // Successfully added the element
}
```
This code creates a dynamic list that can be safely accessed from multiple threads. It also ensures that no two consecutive elements in the list share the same RNTI value. The list is resized dynamically to accommodate additional elements, and memory allocation is optimized for efficient heap usage. 

