char* generate_and_process_pdu(int N) {
    // Allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T *structs = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate and fill the structures with random data
