    for (int i = 0; i < N; i++) {
        structs[i].RX_UE_INFORMATION_TAG = rand();
        structs[i].RNTI = rand();
        structs[i].CRC_INDICATION_REL8_TAG = rand() % 2; // CRCFLAG is either 0 or 1
    }

    // Concatenate the RNTI values into a string
    char *rntiString = malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        sprintf(&rntiString[i*sizeof(int)], "%d", structs[i].RNTI);
    }

    // Compute the MD5 hash of the RNTI string
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)rntiString, strlen(rntiString), md5Hash);

    // Convert the hash to a hexadecimal string
    char *md5Hex = malloc(2*MD5_DIGEST_LENGTH+1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&md5Hex[i*2], "%02x", md5Hash[i]);
    }

    // Free the memory and return the hash string
    free(structs);
    free(rntiString);
    return md5Hex;
}
