typedef struct {
    time_t timestamp;
    int eventType;
    void* payload;
} Event;

typedef struct {
    Event** events;
    size_t count;
    size_t maxSize;
} EventArray;

EventArray* createEventArray(size_t maxSize) {
    EventArray* array = malloc(sizeof(EventArray));
    if (array == NULL) return NULL;

    array->events = calloc(maxSize, sizeof(Event*));
    if (array->events == NULL) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->maxSize = maxSize;
    return array;
}

void addEvent(EventArray* array, Event* event) {
    if (array->count >= array->maxSize) {
        // Handle error: array is full
        return;
    }

    array->events[array->count++] = event;
}

void removeEvent(EventArray* array, int (*condition)(Event*, void*), void* data) {
    for (size_t i = 0; i < array->count; ++i) {
        if (condition(array->events[i], data)) {
            free(array->events[i]);

            // Shift all subsequent events down by one
            --array->count;
            for (size_t j = i; j < array->count; ++j) {
                array->events[j] = array->events[j + 1];
            }

            // Decrement `i` to check the event that was just moved down
            --i;
        }
    }
}

void iterateEvents(EventArray* array, void (*callback)(Event*, void*), void* data) {
    for (size_t i = array->count; i > 0; --i) {
        callback(array->events[i - 1], data);
    }
}
