    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    LTEPHY_TransportChannel* new_data = realloc(array->data, new_capacity * sizeof(LTEPHY_TransportChannel));
    if (new_data == NULL) return -1;

    array->data = new_data;
    array->capacity = new_capacity;

    return 0;
