void add_session(SessionManager* manager, UE_Session_Record* session) {
    pthread_mutex_lock(&manager->lock);

    if (manager->session_count == manager->capacity) {
        manager->sessions = realloc(manager->sessions, sizeof(UE_Session_Record*) * manager->capacity * 2);
        manager->capacity *= 2;
    }

    manager->sessions[manager->session_count++] = session;

    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager* manager, int UE_ID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->session_count; ++i) {
        if (manager->sessions[i]->UE_ID == UE_ID) {
            free(manager->sessions[i]);
            manager->sessions[i] = manager->sessions[--manager->session_count];
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_timestamp(SessionManager* manager, int UE_ID, time_t new_time) {
    pthread_mutex_lock(&manager->lock);

