    char md5hex[33] = {0};
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&md5hex[i*2], "%02x", (unsigned int)md5[i]);
    }

    // Determine the new filename extension based on character distribution in the original filename
    char *newExtension = determine_compressed_extension(filename);

    // Allocate memory for modifiedFilename and append the MD5 hash to it
    *modifiedFilename = malloc(strlen(filename) + strlen(md5hex) + 1);
    sprintf(*modifiedFilename, "%s.%s", filename, md5hex);

    // DNS resolution for a given hostname
    struct hostent *host_entry;
    char *ip = "8.8.8.8";  // Google's DNS server IP address
    struct in_addr addr;

    inet_aton(ip, &addr);
    host_entry = gethostbyaddr((const char *)&addr, sizeof(addr), AF_INET);

    if (host_entry == NULL) {
        herror("gethostbyaddr");
        return -1;  // Return error code for DNS resolution failure
    }

    *ipAddress = malloc(sizeof(u_char) * strlen(host_entry->h_name));
