#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int count;
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} List;

void initList(List *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
}

int addToList(List *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= 1024) {
        pthread_mutex_unlock(&list->lock);
        return -1; // list is full
    }

    srand(time(NULL));
    item->CRCFLAG = rand();

    if (list->head == NULL) {
        list->head = item;
        list->tail = item;
    } else {
        list->tail->next = item;
        item->prev = list->tail;
        list->tail = item;
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // success
}

int removeFromList(List *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);

    if (item == list->head) {
        list->head = item->next;
    } else {
        item->prev->next = item->next;
    }

    if (item == list->tail) {
        list->tail = item->prev;
    } else {
        item->next->prev = item->prev;
    }

    free(item);
    list->count--;

    pthread_mutex_unlock(&list->lock);
    return 0; // success
}
```
This code provides a basic implementation of a thread-safe doubly linked list. It uses a mutex to ensure that only one thread can modify the list at a time, preventing race conditions. The `addToList` function checks if the list is full before adding an item and generates a random `CRCFLAG` for each new item. The `removeFromList` function safely removes an item from the list and frees its memory.
