typedef struct {
    int ue_id;
    int grant_duration;
    int priority_level;
} ULGrantRequest;

typedef struct Node {
    ULGrantRequest *data;
    struct Node *next;
} Node;

Node **hashTable;
int hashTableSize = 1024; // You can adjust this based on your expected data size.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initHashTable() {
    hashTable = malloc(sizeof(Node*) * hashTableSize);
    for (int i = 0; i < hashTableSize; ++i) {
        hashTable[i] = NULL;
    }
}

unsigned int hashFunction(int ue_id) {
    return ue_id % hashTableSize; // Simple hash function.
}

void insertRequest(ULGrantRequest *request) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = request;
    newNode->next = NULL;

    unsigned int hashIndex = hashFunction(request->ue_id);
    if (hashTable[hashIndex] == NULL) {
        hashTable[hashIndex] = newNode;
    } else {
        Node *current = hashTable[hashIndex];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void deleteRequest(int ue_id) {
    pthread_mutex_lock(&lock);

    unsigned int hashIndex = hashFunction(ue_id);
    Node *current = hashTable[hashIndex];
    Node *previous = NULL;

    while (current != NULL && current->data->ue_id != ue_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return; // Request not found.
    }

    if (previous == NULL) {
        hashTable[hashIndex] = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->data);
    free(current);

    pthread_mutex_unlock(&lock);
}
```
