    long offset;
    int key;
} Record;

Record* initialize(int numOffsets) {
    srand(time(NULL)); // seed the random number generator

    Record* records = malloc(numOffsets * sizeof(Record));
    if (records == NULL) {
        return NULL; // handle memory allocation failure
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < numOffsets; ++i) {
        int uniqueKey;

        do {
            uniqueKey = rand() % INT_MAX; // generate a random key within the range of an int

            pthread_mutex_lock(&lock);
            for (int j = 0; j < i; ++j) {
                if (records[j].key == uniqueKey) {
                    uniqueKey = -1; // mark as not unique
                    break;
                }
            }
            pthread_mutex_unlock(&lock);
        } while (uniqueKey == -1);

        records[i].offset = rand() % LONG_MAX; // generate a random offset within the range of a long int
        records[i].key = uniqueKey;
    }

    pthread_mutex_destroy(&lock);

    return records;
}
