#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    int grant_duration;
    int priority_level;
} ULGrantRequest;

typedef struct {
    ULGrantRequest **array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init(DynamicArray *a, size_t initialSize) {
    a->array = (ULGrantRequest**)malloc(initialSize * sizeof(ULGrantRequest*));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insert(DynamicArray *a, ULGrantRequest *element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (ULGrantRequest**)realloc(a->array, a->size * sizeof(ULGrantRequest*));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void delete(DynamicArray *a, int index) {
    pthread_mutex_lock(&a->lock);
    if (index >=0 && index < a->used) {
        free(a->array[index]);
        for (int i = index; i < a->used - 1; ++i) {
            a->array[i] = a->array[i + 1];
        }
        --a->used;
    }
    pthread_mutex_unlock(&a->lock);
}
```

This code provides a simple dynamic array with insert and delete operations. It uses mutex to ensure thread safety, which means only one thread can access the array at a time. The memory is allocated dynamically using realloc when necessary, minimizing memory fragmentation and optimizing for cache utilization. 

