#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Message {
    char* buffer;
    size_t length;
    struct Message *prev, *next;
} Message;

typedef struct MessageQueue {
    pthread_mutex_t lock;
    Message *head, *tail;
    size_t maxLength;
} MessageQueue;

typedef enum ConnectionState {
    CONNECTED, DISCONNECTED
} ConnectionState;

typedef struct SessionHeader {
    // Add fields as needed
} SessionHeader;

typedef struct NetworkSession {
    pthread_mutex_t lock;
    SessionHeader header;
    ConnectionState state;
    MessageQueue queue;
} NetworkSession;

NetworkSession* createSession(size_t maxMessageLength) {
    NetworkSession *session = malloc(sizeof(NetworkSession));
    if (session == NULL) return NULL;

    session->state = DISCONNECTED;
    pthread_mutex_init(&session->lock, NULL);

    // Initialize header as needed

    session->queue.maxLength = maxMessageLength;
    session->queue.head = session->queue.tail = NULL;
    pthread_mutex_init(&session->queue.lock, NULL);

    return session;
}

int addMessage(NetworkSession *session, const char* message) {
    size_t length = strlen(message);
    if (length > session->queue.maxLength) return -1;

    Message *msg = malloc(sizeof(Message));
    if (msg == NULL) return -2;

    msg->buffer = malloc(length + 1);
    if (msg->buffer == NULL) {
        free(msg);
        return -2;
    }

    strcpy(msg->buffer, message);
    msg->length = length;
    msg->prev = session->queue.tail;
    msg->next = NULL;

    pthread_mutex_lock(&session->queue.lock);
    if (session->queue.head == NULL) {
        session->queue.head = session->queue.tail = msg;
    } else {
        session->queue.tail->next = msg;
        session->queue.tail = msg;
    }
    pthread_mutex_unlock(&session->queue.lock);

    return 0;
}

void destroySession(NetworkSession *session) {
    Message *msg, *next;
    for (msg = session->queue.head; msg != NULL; msg = next) {
        next = msg->next;
        free(msg->buffer);
        free(msg);
    }

    pthread_mutex_destroy(&session->lock);
    pthread_mutex_destroy(&session->queue.lock);
    free(session);
}
```
