} TrafficFlow;

enum ErrorCode {
    SUCCESS,
    OUT_OF_MEMORY,
    INVALID_PARAMETERS
};

typedef struct {
    enum ErrorCode errorCode;
    TrafficFlow* trafficFlowArray;
} InitResult;

InitResult initializeTrafficFlowArray(size_t numOfFlows, size_t maxPayloadSize, size_t systemLimit) {
    if (numOfFlows * sizeof(TrafficFlow) > systemLimit || maxPayloadSize * numOfFlows > systemLimit) {
        return (InitResult){.errorCode = INVALID_PARAMETERS};
    }

    TrafficFlow* trafficFlowArray = malloc(numOfFlows * sizeof(TrafficFlow));
    if (!trafficFlowArray) {
        return (InitResult){.errorCode = OUT_OF_MEMORY};
    }

    memset(trafficFlowArray, 0, numOfFlows * sizeof(TrafficFlow));

    for (size_t i = 0; i < numOfFlows; ++i) {
        trafficFlowArray[i].PayloadSize = maxPayloadSize;
    }

    return (InitResult){.errorCode = SUCCESS, .trafficFlowArray = trafficFlowArray};
}
