typedef struct Log {
    int logLevel;
    time_t timestamp;
    int priorityLevel;
    struct Log* next;
} Log;

Log* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(int logLevel, time_t timestamp, int priorityLevel) {
    pthread_mutex_lock(&lock);

    Log* newLog = malloc(sizeof(Log));
    newLog->logLevel = logLevel;
    newLog->timestamp = timestamp;
    newLog->priorityLevel = priorityLevel;
    newLog->next = head;
    head = newLog;

    pthread_mutex_unlock(&lock);
}

void delete(int logLevel, time_t timestamp) {
    pthread_mutex_lock(&lock);

    Log* prev = NULL;
    for (Log* curr = head; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->logLevel == logLevel && curr->timestamp == timestamp) {
            if (prev == NULL) {
                head = curr->next;
            } else {
                prev->next = curr->next;
            }

            free(curr);
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

Log* retrieve(int logLevel, time_t timestamp) {
    pthread_mutex_lock(&lock);

    for (Log* curr = head; curr != NULL; curr = curr->next) {
        if (curr->logLevel == logLevel && curr->timestamp == timestamp) {
            pthread_mutex_unlock(&lock);
            return curr;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

Log* filter(int priorityLevel) {
    pthread_mutex_lock(&lock);

    Log* result = NULL;
    for (Log* curr = head; curr != NULL; curr = curr->next) {
        if (curr->priorityLevel == priorityLevel) {
            Log* newLog = malloc(sizeof(Log));
            *newLog = *curr;
            newLog->next = result;
            result = newLog;
        }
    }

    pthread_mutex_unlock(&lock);
    return result;
}
```
