['Here is a basic implementation in C using a priority queue (heap) for managing items based on their priority. This code does not include error handling or concurrency control, which would be necessary to handle real-world scenarios. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    int priority;
} Item;

typedef struct {
    size_t capacity;
    size_t size;
    Item *items;
} PriorityQueue;

PriorityQueue* createQueue(size_t initialCapacity) {
    PriorityQueue *queue = malloc(sizeof(PriorityQueue));
    queue->capacity = initialCapacity;
    queue->size = 0;
    queue->items = malloc(initialCapacity * sizeof(Item));
    return queue;
}

void destroyQueue(PriorityQueue *queue) {
    free(queue->items);
    free(queue);
}

void resizeQueue(PriorityQueue *queue, size_t newCapacity) {
    Item *newItems = realloc(queue->items, newCapacity * sizeof(Item));
    if (newItems != NULL) {
        queue->capacity = newCapacity;
        queue->items = newItems;
    }
}

void addToQueue(PriorityQueue *queue, Item item) {
    if (queue->size == queue->capacity) {
        resizeQueue(queue, 2 * queue->capacity);
    }

    size_t index = queue->size;
    while (index > 0 && queue->items[index - 1].priority > item.priority) {
        queue->items[index] = queue->items[index - 1];
        --index;
    }

    queue->items[index] = item;
    ++queue->size;
}

Item removeFromQueue(PriorityQueue *queue) {
    if (queue->size == 0) {
        // Handle error: Queue is empty
    }

    Item item = queue->items[--queue->size];

    if (4 * queue->size == queue->capacity) {
        resizeQueue(queue, queue->capacity / 2);
    }

    return item;
}

Item getHighestPriorityItem(const PriorityQueue *queue) {
    if (queue->size == 0) {
        // Handle error: Queue is empty
    }

    return queue->items[queue->size - 1];
}
```
This code uses a priority queue implemented as an array, where the highest priority item is always at the end of the array. Adding and removing items from the queue involves maintaining the heap property by sifting up or down as necessary. The resize operation ensures that the queue has enough capacity to accommodate new items without frequent reallocations.
']

