['Here is a basic implementation in C using linked list for managing multiple Network Interface Configurations (NICs). This code does not include all the features you mentioned, but it should give you a good starting point. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct NIC {
    char mac_address[18];
    char ip_address[16];
    char subnet_mask[16];
    struct NIC *next;
} NIC;

NIC *head = NULL;
int count = 0;

void add_nic(char *mac, char *ip, char *subnet) {
    if (count >= 1000) {
        printf("Maximum limit reached.\n");
        return;
    }

    NIC *new_node = malloc(sizeof(NIC));
    strcpy(new_node->mac_address, mac);
    strcpy(new_node->ip_address, ip);
    strcpy(new_node->subnet_mask, subnet);
    new_node->next = head;
    head = new_node;

    count++;
}

void remove_nic(char *mac) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }

    NIC *temp = head, *prev = NULL;

    while (temp != NULL && strcmp(temp->mac_address, mac)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("MAC address not found.\n");
        return;
    }

    if (prev != NULL)
        prev->next = temp->next;

    if (temp == head)
        head = head->next;

    free(temp);

    count--;
}

void print_list() {
    NIC *temp = head;

    while (temp != NULL) {
        printf("MAC: %s, IP: %s, Subnet Mask: %s\n", temp->mac_address, temp->ip_address, temp->subnet_mask);
        temp = temp->next;
    }
}
```
This code only covers the basic functionality of adding and removing NIC configurations. It does not include error handling for invalid IP addresses or subnet masks, nor does it integrate with an external network status monitoring service. You would need to add these features yourself based on your specific requirements. 

