```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <zlib.h>
#include <jansson.h>

typedef struct {
    int UE_ID;
    long RF_RX_TIMESTAMP;
} NFAPI_RX_FRAME_INFO_T;

typedef struct {
    void *data;
    size_t size;
} RRC_CONNECTION_RECONFIGURATION_TAG;

typedef struct Node {
    NFAPI_RX_FRAME_INFO_T info;
    RRC_CONNECTION_RECONFIGURATION_TAG tag;
    struct Node *next;
} Node;

Node *head = NULL;
size_t totalSize = 0;
const size_t MAX_SIZE = 10 * 1024 * 1024; // 10 MB

void add(NFAPI_RX_FRAME_INFO_T info, RRC_CONNECTION_RECONFIGURATION_TAG tag) {
    if (totalSize + sizeof(Node) > MAX_SIZE) {
        printf("Memory budget exceeded\n");
        return;
    }

    Node *newNode = malloc(sizeof(Node));
    newNode->info = info;
    newNode->tag = tag;
    newNode->next = head;
    head = newNode;
    totalSize += sizeof(Node);
}

void remove() {
    if (head == NULL) return;

    Node *temp = head;
    head = head->next;
    free(temp);
    totalSize -= sizeof(Node);
}

void serializeToBinaryFile(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return;
    }

    Node *current = head;
    while (current != NULL) {
        fwrite(&current->info, sizeof(NFAPI_RX_FRAME_INFO_T), 1, file);
        fwrite(&current->tag.size, sizeof(size_t), 1, file);
        fwrite(current->tag.data, current->tag.size, 1, file);
        current = current->next;
    }

    fclose(file);
}

void serializeToCompressedJsonFile(const char* filename) {
    json_t *root = json_object();
    Node *current = head;
    while (current != NULL) {
        json_t *infoObject = json_pack("{sis}", "UE_ID", current->info.UE_ID, "RF_RX_TIMESTAMP", current->info.RF_RX_TIMESTAMP);
        json_object_set(root, "NFAPI_RX_FRAME_INFO_T", infoObject);

        // Compress the tag data using zlib
        uLongf compressedSize = compressBound(current->tag.size);
        Bytef *compressedData = malloc(compressedSize);
        compress(compressedData, &compressedSize, current->tag.data, current->tag.size);

        json_t *tagObject = json_pack("{s#}", "RRC_CONNECTION_RECONFIGURATION_TAG", compressedData, compressedSize);
        json_object_set(root, "RRC_CONNECTION_RECONFIGURATION_TAG", tagObject);

        free(compressedData);
        current = current->next;
    }

    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Failed to open file for writing\n");
        return;
    }

    json_dumpf(root, file, JSON_COMPACT);
    fclose(file);
    json_decref(root);
