typedef struct {
    pthread_mutex_t lock;
    int maxFrames;
    int currentFrameCount;
    NFAPI_RX_FRAME_INFO** frames;
} FrameManager;

void initFrameManager(FrameManager* manager, int maxFrames) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->maxFrames = maxFrames;
    manager->currentFrameCount = 0;
    manager->frames = malloc(sizeof(NFAPI_RX_FRAME_INFO*) * maxFrames);
}

void addFrame(FrameManager* manager, NFAPI_RX_FRAME_INFO* frame) {
    pthread_mutex_lock(&manager->lock);

    if (manager->currentFrameCount < manager->maxFrames) {
        manager->frames[manager->currentFrameCount++] = frame;
    } else {
        // Handle buffer overflow here, e.g., by reallocating more memory
    }

    pthread_mutex_unlock(&manager->lock);
}

void iterateFrames(FrameManager* manager, void (*callback)(NFAPI_RX_FRAME_INFO*)) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->currentFrameCount; ++i) {
        callback(manager->frames[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}
```
