void insert(NetworkInterfaceConfig config) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->config = config;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void delete(char* id) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev;

    if (temp != NULL && strcmp(temp->config.id, id) == 0) {
        head = temp->next;  
        free(temp);              
        return;
    }

    while (temp != NULL && strcmp(temp->config.id, id) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);
}

