    pthread_mutex_lock(&lock);

    Node *node = head;

    while (node != NULL && strcmp(node->config.id, id) != 0) {
        node = node->next;
    }

    if (node == NULL) return NULL;

    NetworkInterfaceConfig* config = &(node->config);

    pthread_mutex_unlock(&lock);

    return config;
}
