#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char interface_id[10];
    char ip_address[20];
    char subnet_mask[20];
    char gateway[20];
} NetworkInterface;

typedef struct Node {
    NetworkInterface data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(NetworkInterface ni) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*) malloc(sizeof(Node));
    strcpy(new_node->data.interface_id, ni.interface_id);
    strcpy(new_node->data.ip_address, ni.ip_address);
    strcpy(new_node->data.subnet_mask, ni.subnet_mask);
    strcpy(new_node->data.gateway, ni.gateway);

    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void update(char* interface_id, NetworkInterface ni) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->data.interface_id, interface_id) == 0) {
            strcpy(temp->data.ip_address, ni.ip_address);
            strcpy(temp->data.subnet_mask, ni.subnet_mask);
            strcpy(temp->data.gateway, ni.gateway);
            break;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

void delete(char* interface_id) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev = NULL;
    while (temp != NULL && strcmp(temp->data.interface_id, interface_id) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    if (prev != NULL) prev->next = temp->next;
    if (head == temp) head = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);
}

int size() {
    pthread_mutex_lock(&lock);

    int count = 0;
    Node* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);

    return count;
}

void print() {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        printf("Interface ID: %s, IP Address: %s, Subnet Mask: %s, Gateway: %s\n", 
               temp->data.interface_id, temp->data.ip_address, temp->data.subnet_mask, temp->data.gateway);
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}
```
