void addNode(int id, int replicationFactor, char consistencyLevel[]) {
    pthread_mutex_lock(&lock);

    if (nodeCount >= 10000) {
        printf("Error: Maximum node limit reached.\n");
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->id = id;
    newNode->replicationFactor = replicationFactor;
    strcpy(newNode->consistencyLevel, consistencyLevel);

    nodes[nodeCount++] = newNode;

    pthread_mutex_unlock(&lock);
}

void removeNode(int id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < nodeCount; ++i) {
        if (nodes[i]->id == id) {
            free(nodes[i]);

            // Shift all nodes after the removed one to fill the gap.
            for (int j = i; j < nodeCount - 1; ++j) {
                nodes[j] = nodes[j + 1];
            }

            --nodeCount;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
