['Here is an example of how you might implement this function in C using POSIX threads for thread safety and getaddrinfo() for DNS resolution. This code does not include all the features mentioned in your requirements due to their complexity, but it should give you a good starting point. 

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <pthread.h>

// Global mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int resolveHostnameToIpArray(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int errcode;
    void *ptr;

    // Lock the mutex before accessing shared resources
    pthread_mutex_lock(&lock);

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("getaddrinfo");
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning
        return -1;
    }

    switch(res->ai_family) {
        case AF_INET: 
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
            ptr = &(ipv4->sin_addr);
            break;

        default:
            printf("Unsupported address family\n");
            pthread_mutex_unlock(&lock); // Unlock the mutex before returning
            return -1;
    }

    inet_ntop (res->ai_family, ptr, ip, sizeof(ip));

    freeaddrinfo(res);

    pthread_mutex_unlock(&lock); // Unlock the mutex before returning
    return 0;
}
```
This function takes a hostname as input and returns an array of bytes representing the IP address. It uses getaddrinfo() to perform DNS resolution, which is thread-safe on most systems. The function also locks a global mutex before accessing shared resources to ensure thread safety.
