    int SESSION_ID;
    char* USER_NAME;
    time_t LAST_ACTIVE_TIME;
} USER_SESSION_DATA;

typedef struct {
    USER_SESSION_DATA** data;
    size_t capacity;
    size_t size;
} HashTable;

HashTable* init_hash_table(int C, unsigned int seed) {
    if (C <= 0) {
        return NULL; // Invalid capacity
    }

    srand(seed);

    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        return NULL; // Memory allocation failed
    }

    ht->capacity = C;
    ht->size = 0;
    ht->data = calloc(C, sizeof(USER_SESSION_DATA*));
    if (!ht->data) {
        free(ht); // Memory allocation failed
        return NULL;
    }

    return ht;
}

void add_session(HashTable* ht, USER_SESSION_DATA* session) {
    if (ht->size >= ht->capacity) {
        resize_hash_table(ht); // Resize the hash table when it's full
    }

    int index = rand() % ht->capacity; // Randomly distribute keys
    while (ht->data[index] != NULL) {
        index = (index + 1) % ht->capacity; // Handle collisions
    }

    ht->data[index] = session;
    ht->size++;
}

void resize_hash_table(HashTable* ht) {
    size_t newCapacity = 2 * ht->capacity; // Double the capacity for simplicity

    USER_SESSION_DATA** newData = calloc(newCapacity, sizeof(USER_SESSION_DATA*));
    if (!newData) {
        return; // Memory allocation failed
    }

    for (size_t i = 0; i < ht->capacity; ++i) {
        USER_SESSION_DATA* session = ht->data[i];
        if (session != NULL) {
            int index = session->SESSION_ID % newCapacity; // Rehash keys
            while (newData[index] != NULL) {
                index = (index + 1) % newCapacity; // Handle collisions
            }

            newData[index] = session;
        }
    }

    free(ht->data);
    ht->data = newData;
    ht->capacity = newCapacity;
}
```
This code initializes a hash table with a given capacity and seed for random number generation. It also includes functions to add sessions to the hash table, which handles collisions by linear probing, and resize the hash table when it's full. 

Please note that this is a very basic implementation and does not include all the features you asked for (like handling varying update frequencies based on session data characteristics). You would need to extend this code to add these features. Also, please remember to free any allocated memory in case of failure or when you're done with it to avoid memory leaks.
"]

