typedef struct entry {
    Data* data;
    struct entry* next;
} Entry;

typedef struct list {
    pthread_mutex_t lock;
    Entry* head;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        printf("\n mutex init failed\n");
        return NULL;
    }
    list->head = NULL;
    return list;
}

Data* create_data(char* str, int num) {
    Data* data = malloc(sizeof(Data));
    data->str = malloc((strlen(str) + 1) * sizeof(char));
    strcpy(data->str, str);
    data->num = num;
    return data;
}

Entry* create_entry(Data* data) {
    Entry* entry = malloc(sizeof(Entry));
    entry->data = data;
    entry->next = NULL;
    return entry;
}

void add_entry(List* list, Data* data) {
    pthread_mutex_lock(&list->lock);

    Entry* newEntry = create_entry(data);
    if (list->head == NULL) {
        list->head = newEntry;
    } else {
        Entry* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_entry(List* list, int index) {
    pthread_mutex_lock(&list->lock);

    if (index == 0) {
        Entry* temp = list->head;
        list->head = list->head->next;
        free(temp->data->str);
        free(temp->data);
        free(temp);
    } else {
        Entry* current = list->head;
        for (int i = 0; i < index - 1; ++i) {
            if (current->next == NULL) return;
            current = current->next;
        }

        Entry* temp = current->next;
        current->next = temp->next;
        free(temp->data->str);
        free(temp->data);
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
}

void update_integer(List* list, int index, int newNum) {
    pthread_mutex_lock(&list->lock);

    Entry* current = list->head;
    for (int i = 0; i < index; ++i) {
        if (current == NULL) return;
        current = current->next;
    }

    if (current != NULL) {
        current->data->num = newNum;
    }

    pthread_mutex_unlock(&list->lock);
}
```
