typedef struct Node {
    MAC_CONTEXT_T context;
    MAC_PDU mac_pdu;
    PDCP_PDU pdcp_pdu;
    struct Node* next;
} Node;

Node* createNode(MAC_CONTEXT_T context, MAC_PDU mac_pdu, PDCP_PDU pdcp_pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error\n");
        return NULL;
    }

    newNode->context = context;
    newNode->mac_pdu = mac_pdu;
    newNode->pdcp_pdu = pdcp_pdu;
    newNode->next = NULL;

    return newNode;
}

void addEdge(Node* src, Node* dest) {
    if (!src || !dest) {
        printf("Invalid nodes\n");
        return;
    }

    Node* node = src;
    while (node->next) {
        node = node->next;
    }

    node->next = dest;
}

void bfs(Node* root, void (*process)(Node*)) {
    if (!root || !process) {
        printf("Invalid arguments\n");
        return;
    }

    Node** queue = (Node**)malloc(sizeof(Node*) * 100); // Assuming max size of queue is 100 for simplicity
    int front = 0, rear = 0;

    Node* visited[100] = {0}; // Assuming max number of nodes is 100 for simplicity

    queue[rear++] = root;
    visited[(int)root->context.MAC_ADDRESS] = 1;

    while (front != rear) {
        Node* node = queue[front++];

        process(node);

        Node* neighbor = node->next;
        while (neighbor) {
            if (!visited[(int)neighbor->context.MAC_ADDRESS]) {
                queue[rear++] = neighbor;
                visited[(int)neighbor->context.MAC_ADDRESS] = 1;
            }

            neighbor = neighbor->next;
        }
    }

    free(queue);
}
```
This code creates a graph structure using linked lists, where each node contains a MAC_CONTEXT_T, MAC_PDU, and PDCP_PDU. The `bfs` function performs a breadth-first search on the graph starting from the root node, applying a provided processing function to each visited node.

