```c
#include <stdlib.h>
#include <pthread.h>

typedef struct packet_queue {
    int size;
    int capacity;
    void **packets;
    pthread_mutex_t lock;
} PacketQueue;

PacketQueue *initialize_queue(int initialCapacity) {
    PacketQueue *q = malloc(sizeof(PacketQueue));
    q->capacity = initialCapacity;
    q->size = 0;
    q->packets = malloc(initialCapacity * sizeof(void*));
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

int enqueue(PacketQueue *q, void *packet) {
    pthread_mutex_lock(&q->lock);

    if (q->size == q->capacity) {
        // Dynamically scale the queue
        q->capacity *= 2;
        q->packets = realloc(q->packets, q->capacity * sizeof(void*));
    }

    // Check for duplicates (this is a simple example and may not be efficient)
    int i;
    for (i = 0; i < q->size; ++i) {
        if (q->packets[i] == packet) {
            pthread_mutex_unlock(&q->lock);
            return 1; // Duplicate found, do not enqueue
        }
    }

    q->packets[q->size++] = packet;

    pthread_mutex_unlock(&q->lock);
    return 0; // No duplicate found, successfully enqueued
}

void *dequeue(PacketQueue *q) {
    pthread_mutex_lock(&q->lock);

    if (q->size == 0) {
        pthread_mutex_unlock(&q->lock);
        return NULL; // Queue is empty
    }

    void *packet = q->packets[--q->size];

    pthread_mutex_unlock(&q->lock);
    return packet;
}
```
