['Here is a basic implementation of such a function in C using pthreads and linked list. This code does not include the actual network interface communication or packet generation/reception logic, but it provides a good starting point for managing a queue of packets with unique sequence numbers and timeout mechanism. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 1024

typedef struct PacketHeader {
    // Define your packet header fields here
} PacketHeader;

typedef struct PacketQueueEntry {
    PacketHeader header;
    size_t payloadLength;
    unsigned int sequenceNumber;
    time_t timestamp;
    struct PacketQueueEntry* next;
} PacketQueueEntry;

static pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
static PacketQueueEntry* packetQueueHead = NULL;
static unsigned int currentSequenceNumber = 0;

void addPacketToQueue(const PacketHeader header, size_t payloadLength) {
    pthread_mutex_lock(&queueMutex);

    if (packetQueueSize >= MAX_QUEUE_SIZE) {
        fprintf(stderr, "Error: Queue is full. Cannot add packet.\n");
        pthread_mutex_unlock(&queueMutex);
        return;
    }

    PacketQueueEntry* newEntry = malloc(sizeof(PacketQueueEntry));
    if (newEntry == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for packet queue entry.\n");
        pthread_mutex_unlock(&queueMutex);
        return;
    }

    newEntry->header = header;
    newEntry->payloadLength = payloadLength;
    newEntry->sequenceNumber = currentSequenceNumber++;
    newEntry->timestamp = time(NULL);
    newEntry->next = packetQueueHead;
    packetQueueHead = newEntry;

    pthread_mutex_unlock(&queueMutex);
}

void removeOldPacketsFromQueue(time_t timeoutPeriod) {
    pthread_mutex_lock(&queueMutex);

    time_t currentTime = time(NULL);
    PacketQueueEntry** prevNextPtr = &packetQueueHead;
    while (*prevNextPtr != NULL) {
        if (currentTime - (*prevNextPtr)->timestamp > timeoutPeriod) {
            PacketQueueEntry* oldEntry = *prevNextPtr;
            *prevNextPtr = (*prevNextPtr)->next;
            free(oldEntry);
        } else {
            prevNextPtr = &(*prevNextPtr)->next;
        }
    }

    pthread_mutex_unlock(&queueMutex);
}
```
This code provides a basic queue management system with thread-safe operations. It uses a linked list to store the packets, and each packet has a unique sequence number assigned upon addition to the queue. The `removeOldPacketsFromQueue` function checks for and removes any packets that have been inactive (based on their timestamp) for longer than the specified timeout period.
