    }
    q->head = q->tail = NULL;
}

void enqueue(Queue* q, int size) {
    pthread_mutex_lock(&q->lock);

    Packet* newPacket = (Packet*)malloc(sizeof(Packet));
    if (newPacket == NULL) {
        printf("\n malloc failed\n");
        return;
    }
    newPacket->size = size;
    newPacket->next = NULL;

    if (q->tail != NULL) {
        q->tail->next = newPacket;
    } else {
        q->head = newPacket;
    }
    q->tail = newPacket;

    pthread_mutex_unlock(&q->lock);
}

int reduce(Queue* q, int initialValue, int (*callback)(int, int)) {
    pthread_mutex_lock(&q->lock);

    Packet* current = q->head;
    int result = initialValue;

    while (current != NULL) {
        result = callback(result, current->size);
        current = current->next;
    }

    pthread_mutex_unlock(&q->lock);

    return result;
}
```
This code creates a basic queue data structure and provides functions to initialize it, enqueue packets into the queue, and perform a reduction operation on the packet sizes. The `reduce` function takes an initial value and a callback function that computes the next accumulated value from the current accumulated value and the current packet size.

Please note that this is a very basic implementation and does not include features like handling duplicate entries, integrating with external data sources for real-time network status updates, or asynchronous processing modes. Implementing these features would require a more complex design and potentially significant additional code.
']

