    }

    // Compute MD5 hash of the concatenated string
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)concatStr, strlen(concatStr), md5Hash);

    // Convert MD5 hash to hexadecimal string
    char* md5String = malloc(2 * MD5_DIGEST_LENGTH + 1);
    if (md5String == NULL) {
        printf("Memory allocation failed.\n");
        free(pduList);
        free(concatStr);
        return NULL;
