    TRANSPORT_LAYER_INFO transportLayerInfo;
    int sequenceNumber;
    char* payloadData;
} MAC_PACKET_T;

typedef struct Node {
    MAC_PACKET_T packet;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addPacket(MAC_PACKET_T packet) {
    pthread_mutex_lock(&lock);

    if (packet.sequenceNumber < 1 || packet.sequenceNumber > MAX_SEQUENCE_NUMBER) {
        // Handle invalid sequence number
        return;
    }

    Node* current = head;
    while(current != NULL) {
        if (current->packet.sequenceNumber == packet.sequenceNumber) {
            // Handle duplicate sequence number
            return;
        }
        current = current->next;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->packet = packet;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removePacket(int sequenceNumber) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->packet.sequenceNumber == sequenceNumber) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void updatePayloadData(int sequenceNumber, char* newPayload) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->packet.sequenceNumber == sequenceNumber) {
            free(current->packet.payloadData);
            current->packet.payloadData = newPayload;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
