    DL_FRAME_INFO *data;
    struct Node *next;
} Node;

Node **hashTable = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int hashTableSize = 256; // PCI values range from 0 to 255

void initHashTable() {
    hashTable = malloc(sizeof(Node*) * hashTableSize);
    for (int i = 0; i < hashTableSize; ++i) {
        hashTable[i] = NULL;
    }
}

unsigned int hashFunction(int pci) {
    return pci % hashTableSize; // Simple hash function
}

void addElement(DL_FRAME_INFO *data) {
    if (data->pci < 0 || data->pci > 255) {
        printf("Invalid PCI value\n");
        return;
    }

    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    unsigned int hash = hashFunction(data->pci);
    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = hashTable[hash];
    hashTable[hash] = newNode;

    pthread_mutex_unlock(&lock); // Unlock after operation
}

void removeElement(int pci) {
    unsigned int hash = hashFunction(pci);

    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    Node *prevNode = NULL;
    for (Node *node = hashTable[hash]; node != NULL; prevNode = node, node = node->next) {
        if (node->data->pci == pci) {
            if (prevNode != NULL) {
                prevNode->next = node->next;
            } else {
                hashTable[hash] = node->next;
            }

            free(node); // Free memory
            break;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock after operation
}
```
This code uses a simple hash function and a linked list for collision resolution. It also uses a mutex to ensure thread safety, but this is not enough for handling concurrent access from multiple threads safely as it only protects the critical sections of code (add/remove operations). For true concurrency control, you would need to use more advanced synchronization primitives such as semaphores or condition variables.
