typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NetworkEventLogEntry** entries;
} LogArray;

void initLogArray(LogArray* array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->size = 0;
    array->entries = malloc(initialCapacity * sizeof(NetworkEventLogEntry*));
    pthread_mutex_init(&array->lock, NULL);
}

void appendToLogArray(LogArray* array, NetworkEventLogEntry* entry) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // Double the capacity when full
        array->entries = realloc(array->entries, 2 * array->capacity * sizeof(NetworkEventLogEntry*));
        array->capacity *= 2;
    }

    array->entries[array->size++] = entry;

    pthread_mutex_unlock(&array->lock);
}

void cleanupUnusedEntries(LogArray* array) {
    // Implement your own logic here to determine which entries are unused.
