typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add(NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        // Handle memory allocation failure
        return;
    }

    newNode->data = item;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void remove(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev;

    if (temp != NULL && temp->data.RNTI == RNTI) {
        head = temp->next;  
        free(temp);              
        return;
    }

    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Item not found

    prev->next = temp->next;
    free(temp); 

    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* get(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL && temp->data.RNTI != RNTI) {
        temp = temp->next;
    }

    if(temp == NULL) return NULL; // Item not found

    NFAPI_CRC_INDICATION_PDU_T* item = &(temp->data);

    pthread_mutex_unlock(&lock);

    return item;
}
