```c
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int LTE_PHY_TransportChannel_tag;
    int RB_start;
    int RB_end;
    int SFN;
} LTE_PHY_TransportChannel;

typedef struct {
    pthread_mutex_t lock;
    LTE_PHY_TransportChannel* array;
    size_t used;
    size_t size;
} DynamicArray;

void initArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_PHY_TransportChannel*)malloc(initialSize * sizeof(LTE_PHY_TransportChannel));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertArray(DynamicArray *a, LTE_PHY_TransportChannel element) {
    pthread_mutex_lock(&a->lock);

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_PHY_TransportChannel*)realloc(a->array, a->size * sizeof(LTE_PHY_TransportChannel));
    }

    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);
}

void freeArray(DynamicArray *a) {
    pthread_mutex_destroy(&a->lock);
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
```
This code provides a simple dynamic array with thread safety. The `initArray` function initializes the array, allocating memory for the specified number of elements and initializing the mutex lock. The `insertArray` function adds an element to the end of the array, resizing it if necessary using realloc. Finally, the `freeArray` function frees the allocated memory and destroys the mutex lock.
