#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define your structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

typedef struct List {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t lock;
    int size;
} List;

List* createList() {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL; // Handle allocation failure

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;

    return list;
}

void addElement(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    ListNode* node = malloc(sizeof(ListNode));
    if (node == NULL) return; // Handle allocation failure

    node->data = data;
    node->next = list->head;
    node->prev = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head != NULL) {
        list->head->prev = node;
    } else {
        list->tail = node;
    }
    list->head = node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(List* list, int index) {
    if (index < 0 || index >= list->size) return NULL; // Handle out of bounds access

    ListNode* node = list->head;
    for (int i = 0; i < index; i++) {
        node = node->next;
    }

    return node->data;
}

void freeList(List* list) {
    pthread_mutex_lock(&list->lock);
    ListNode* node = list->head;
    while (node != NULL) {
        ListNode* next = node->next;
        free(node->data);
        free(node);
        node = next;
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

