#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    // Define your MIB_T structure here
} MIB_T;

typedef enum {
    SYNCED,
    UNSYNCED
} SNTP_SYNC_STATUS;

typedef struct {
    MIB_T mib;
    SNTP_SYNC_STATUS syncStatus;
} LTE_PHY_MIB_TABLE_T;

typedef struct {
    LTE_PHY_MIB_TABLE_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->array = (LTE_PHY_MIB_TABLE_T *)malloc(initialSize * sizeof(LTE_PHY_MIB_TABLE_T));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insertArray(Array *a, LTE_PHY_MIB_TABLE_T element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_PHY_MIB_TABLE_T *)realloc(a->array, a->size * sizeof(LTE_PHY_MIB_TABLE_T));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

void freeArray(Array *a) {
    pthread_mutex_destroy(&a->lock);
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
```
This code provides basic thread safety for inserting elements into the array. It uses a mutex to ensure that only one thread can modify the array at a time, preventing race conditions and ensuring data consistency. The `insertArray` function automatically resizes the array when it becomes full, minimizing memory usage while still allowing efficient insertions.
