    struct CacheNode *next, *prev;
} CacheNode;

CacheNode *cacheHead = NULL;
pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;

void addToCache(ThemeConfig config) {
    pthread_mutex_lock(&cacheLock);

    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    node->config = config;
    node->next = cacheHead;
    node->prev = NULL;

    if (cacheHead != NULL) {
        cacheHead->prev = node;
    }

    cacheHead = node;

    pthread_mutex_unlock(&cacheLock);
}

void processThemeConfig(char* line) {
