    int i = 0;
    while ((token = strsep(&string, ",")) != NULL) {
        if (i == 0) {
            config.theme = strdup(token);
        } else if (i == 1) {
            config.field1 = atoi(token);
        } else if (i == 2) {
            config.field2 = atoi(token);
        }
        ++i;
    }

    addToCache(config);

    free(tofree);
}

