#include <boost/thread/shared_mutex.hpp>
#include <unordered_map>
#include <openssl/md5.h>
#include <random>

struct LTE_PDCP_SDU_T {
    int PSN;
    int SNR;
    std::string PCI;
};

class PDCPSDUManager {
private:
    boost::shared_mutex mtx_;
    std::unordered_map<int, LTE_PDCP_SDU_T> sdus_;
    std::random_device rd_;
    std::mt19937 gen_{rd_()};
    std::uniform_int_distribution<> dis_{0, 255};

public:
    void add(LTE_PDCP_SDU_T sdu) {
        boost::unique_lock<boost::shared_mutex> lock(mtx_);
        sdus_.insert({sdu.PSN, sdu});
    }

    void remove(int psn) {
        boost::unique_lock<boost::shared_mutex> lock(mtx_);
        sdus_.erase(psn);
    }

    void update(LTE_PDCP_SDU_T sdu) {
        boost::upgrade_lock<boost::shared_mutex> lock(mtx_);
        boost::upgrade_to_unique_lock<boost::shared_mutex> uniqueLock(lock);
        auto it = sdus_.find(sdu.PSN);
        if (it != sdus_.end()) {
            it->second = sdu;
        } else {
            throw std::runtime_error("SDU not found");
        }
    }

    LTE_PDCP_SDU_T get(int psn) const {
        boost::shared_lock<boost::shared_mutex> lock(mtx_);
        auto it = sdus_.find(psn);
        if (it != sdus_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("SDU not found");
        }
    }

    std::string getMD5Hash(int psn) const {
        LTE_PDCP_SDU_T sdu = get(psn);

        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)&sdu, sizeof(sdu), (unsigned char*)&digest);    

        std::stringstream ss;
        for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
            ss << std::hex << std::setw(2) << std::setfill('0') << (unsigned int)digest[i]; 

        return ss.str();
    }
};
```
This code uses a `std::unordered_map` to store the SDUs, which is an efficient hash table implementation in C++. The `boost::shared_mutex` and `boost::upgrade_lock` are used for thread safety, allowing multiple threads to read from the map concurrently while only one thread can write at a time.

The `getMD5Hash()` function uses OpenSSL's MD5 implementation to generate an MD5 hash of the SDU. This is done by converting the SDU structure into a byte array and passing it to the MD5 function. The resulting digest is then converted back into a hexadecimal string for easy comparison and storage.
