#define MAX_ELEMENTS 10000

NFAPI_CRC_INDICATION_PDU_T *array = NULL;
int arraySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addElement(RX_UE_INFORMATION_TAG element) {
    pthread_mutex_lock(&mutex);

    if (arraySize >= MAX_ELEMENTS) {
        printf("Array is full\n");
        return;
    }

    array[arraySize] = element.pdu;
    arraySize++;

    // Sort the array based on RNTI values
    for (int i = arraySize - 1; i > 0 && array[i].RNTI < array[i-1].RNTI; i--) {
        NFAPI_CRC_INDICATION_PDU_T temp = array[i];
        array[i] = array[i-1];
        array[i-1] = temp;
    }

    pthread_mutex_unlock(&mutex);
}

void updateCRCFLAG(float probability) {
    srand(time(NULL));

    for (int i = 0; i < arraySize; i++) {
        float random = ((float) rand()) / RAND_MAX;

        if (random <= probability) {
            array[i].CRCFLAG = !array[i].CRCFLAG;
        }
    }
}

void initializeCRCFLAG(float probability) {
    srand(time(NULL));

    for (int i = 0; i < arraySize; i++) {
        float random = ((float) rand()) / RAND_MAX;

        if (random <= probability) {
            array[i].CRCFLAG = 1;
        } else {
            array[i].CRCFLAG = 0;
        }
    }
}

int main() {
    // Allocate memory for the array
    array = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Add elements to the array
    for (int i = 0; i < 5; i++) {
        RX_UE_INFORMATION_TAG element = {i, {i, i, i}};
        addElement(element);
    }

    // Update CRCFLAG values based on a probability
    updateCRCFLAG(0.5f);

    // Initialize CRCFLAG values based on a probability
    initializeCRCFLAG(0.7f);

    // Free allocated memory
    free(array);

    return 0;
}
```
