    for (int i = 0; i < N;) {
        int id = rand() % idRangeSize + minId;
        if (usedIds[id - minId]) continue; // ID already used, try again

        array[i].tag = 1; // set valid tag
        array[i].id = id;
        array[i].channel.frequency = 0; // set frequency and bandwidth to 0 for now
        array[i].channel.bandwidth = 0;

        usedIds[id - minId] = 1;
        ++i;
    }

    free(usedIds);

    return array;
}
