#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_RRC_MESSAGE_T {
    void* RRC_CONNECTION_RECONFIGURATION_TAG;
    int RRC_MESSAGE_TYPE;
    void* BSR_CONFIG_TAG;
    struct NFAPI_RRC_MESSAGE_T *prev, *next;
} NFAPI_RRC_MESSAGE_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_RRC_MESSAGE_T* head;
    NFAPI_RRC_MESSAGE_T* tail;
} LinkedList;

LinkedList list = {PTHREAD_MUTEX_INITIALIZER, NULL, NULL};

void insert(NFAPI_RRC_MESSAGE_T* node) {
    pthread_mutex_lock(&list.lock);

    if (list.tail == NULL) {
        list.head = list.tail = node;
    } else {
        node->prev = list.tail;
        list.tail->next = node;
        list.tail = node;
    }

    pthread_mutex_unlock(&list.lock);
}

void delete(NFAPI_RRC_MESSAGE_T* node) {
    pthread_mutex_lock(&list.lock);

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list.head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list.tail = node->prev;
    }

    free(node);

    pthread_mutex_unlock(&list.lock);
}
```
