['Here is an example of how you might implement this in C using a hash table (std::unordered_map) from the Standard Template Library (STL). This solution assumes that `UE_ID` is an integer type, and that `Measurement_Report` and `Transmission_Log` are structs with appropriate fields.

```c
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <string.h>
#include <assert.h>

typedef struct {
    int frequency;
    int signal_strength;
} Measurement_Report;

typedef struct {
    time_t timestamp;
    int transmission_power;
} Transmission_Log;

typedef struct {
    pthread_mutex_t lock;
    Measurement_Report measurement_report;
    Transmission_Log transmission_log;
} UE_Status_Report;

static atomic_int _id = 0;
static pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
static sem_t semaphore;
static size_t max_size;

// Hash table to store UE_Status_Report structures.
UE_Status_Report* hash_table;

void init(size_t size) {
    assert(sem_init(&semaphore, 0, size) == 0);
    max_size = size;
    atomic_store(&_id, 0);
    hash_table = (UE_Status_Report*)calloc(max_size, sizeof(UE_Status_Report));
}

int add_entry(Measurement_Report measurement_report, Transmission_Log transmission_log) {
    sem_wait(&semaphore);
    int id = atomic_fetch_add(&_id, 1);
    if (id >= max_size) {
        sem_post(&semaphore);
        return -1; // Return error code for overflow.
    }

    pthread_mutex_init(&hash_table[id].lock, NULL);
    hash_table[id].measurement_report = measurement_report;
    hash_table[id].transmission_log = transmission_log;
    sem_post(&semaphore);

    return id;
}

bool update_entry(int UE_ID, Measurement_Report measurement_report, Transmission_Log transmission_log) {
    if (UE_ID >= max_size || UE_ID < 0) {
        return false; // Return error code for invalid ID.
    }

    pthread_rwlock_rdlock(&rwlock);
    hash_table[UE_ID].measurement_report = measurement_report;
    hash_table[UE_ID].transmission_log = transmission_log;
    pthread_rwlock_unlock(&rwlock);

    return true;
}

Measurement_Report get_latest_measurement(int UE_ID) {
    if (UE_ID >= max_size || UE_ID < 0) {
        Measurement_Report report = {-1, -1}; // Return error code for invalid ID.
        return report;
