typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = element;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeElementByRNTI(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev = NULL;
    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // element not found

    if (prev != NULL) prev->next = temp->next;
    else head = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);
}

void updateCRCFLAGByRNTI(int RNTI, int newValue) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL && temp->data.RNTI != RNTI) {
        temp = temp->next;
    }

    if (temp == NULL) return; // element not found

    temp->data.CRC_INDICATION_REL8_TAG = newValue;

    pthread_mutex_unlock(&lock);
}
