    // Add your PUSCH_TX_REQ_PDU, TX_CONFIG_DCI, PUSCH_GRANT and PUSCH_TX_PARAMS here
} NFAPI_MESSAGE_T;

typedef struct MessageArray {
    _Atomic(NFAPI_MESSAGE_T*) messages;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

MessageArray* createMessageArray(size_t initialCapacity) {
    MessageArray* array = malloc(sizeof(MessageArray));
    if (array == NULL) return NULL;

    atomic_init(&array->messages, calloc(initialCapacity, sizeof(NFAPI_MESSAGE_T)));
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroyMessageArray(MessageArray* array) {
    free(atomic_load(&array->messages));
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int processNfarequests(MessageArray* array, NFAPI_MESSAGE_T* message) {
    pthread_mutex_lock(&array->lock);

    // Check if the array is full and needs to be resized
    size_t currentSize = (sizeof(NFAPI_MESSAGE_T*) / sizeof(NFAPI_MESSAGE_T)) - 1;
    if (currentSize >= array->capacity) {
        // Resize the array by doubling its capacity
        NFAPI_MESSAGE_T* newMessages = calloc(array->capacity * 2, sizeof(NFAPI_MESSAGE_T));
        if (newMessages == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Error code for memory allocation failure
        }

        NFAPI_MESSAGE_T* oldMessages = atomic_load(&array->messages);
        memcpy(newMessages, oldMessages, array->capacity * sizeof(NFAPI_MESSAGE_T));
        free(oldMessages);

        atomic_store(&array->messages, newMessages);
        array->capacity *= 2;
    }

    // Add the message to the array
    NFAPI_MESSAGE_T* messages = atomic_load(&array->messages);
    messages[currentSize] = *message;

    pthread_mutex_unlock(&array->lock);

    return 0; // Success code
}
```
