void add(int id, char ip[], int port, int status) {
    pthread_mutex_lock(&lock);

    Connection* newNode = (Connection*)malloc(sizeof(Connection));
    newNode->id = id;
    strcpy(newNode->ip, ip);
    newNode->port = port;
    newNode->status = status;
