typedef struct Node {
    int value;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* hashTable[1000000]; // Assuming a large prime number for hashing

void addToHashTable(int value) {
    pthread_mutex_lock(&lock);
    int index = abs(value % 1000000);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->value = value;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
    pthread_mutex_unlock(&lock);
}

int checkDuplicate(int value) {
    int index = abs(value % 1000000);
    Node* temp = hashTable[index];
    while (temp != NULL) {
        if (temp->value == value) return 1;
        temp = temp->next;
    }
    return 0;
}

char* constructString(Node* head) {
    char* result = malloc(sizeof(char));
    if (!result) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    *result = '\0';
    int sum = 0;
    while (head != NULL) {
        if (!checkDuplicate(head->value)) {
            addToHashTable(head->value);
            char buffer[12]; // Assuming the maximum length of an integer is 11 digits
            sprintf(buffer, "%d", head->value);
            if (*result != '\0') strcat(result, "-");
            result = realloc(result, (strlen(result) + strlen(buffer) + 2) * sizeof(char));
            if (!result) {
                printf("Memory allocation failed\n");
                return NULL;
            }
            strcat(result, buffer);
        }
        head = head->next;
    }
    return result;
}
```
