typedef struct DynamicArray {
    pthread_mutex_t lock;
    LTE_RRC_UE_CONTEXT** contexts;
    int count;
    int capacity;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = 10;
    array->contexts = malloc(sizeof(LTE_RRC_UE_CONTEXT*) * array->capacity);
    return array;
}

void addContext(DynamicArray* array, LTE_RRC_UE_CONTEXT* context) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->contexts = realloc(array->contexts, sizeof(LTE_RRC_UE_CONTEXT*) * array->capacity);
    }

    array->contexts[array->count++] = context;

    pthread_mutex_unlock(&array->lock);
}

void removeContext(DynamicArray* array, int UE_ID) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->count; ++i) {
        if (array->contexts[i]->UE_ID == UE_ID) {
            free(array->contexts[i]);

            // Shift all elements after the removed one to fill the gap.
            for (int j = i; j < array->count - 1; ++j) {
                array->contexts[j] = array->contexts[j + 1];
            }

            --array->count;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

LTE_RRC_UE_CONTEXT* getContext(DynamicArray* array, int UE_ID) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->count; ++i) {
        if (array->contexts[i]->UE_ID == UE_ID) {
            LTE_RRC_UE_CONTEXT* context = array->contexts[i];

            pthread_mutex_unlock(&array->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}
```
