ContextManager* createContextManager() {
    ContextManager* manager = malloc(sizeof(ContextManager));
    if (manager == NULL) return NULL;

    manager->contexts = NULL;
    manager->contextCount = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroyContextManager(ContextManager* manager) {
    for (size_t i = 0; i < manager->contextCount; ++i) {
        free(manager->contexts[i]->messages);
        free(manager->contexts[i]);
    }

    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void addContext(ContextManager* manager, LTE_RRC_UE_CONTEXT* context) {
    pthread_mutex_lock(&manager->lock);

    // Resize the contexts array if necessary
    manager->contexts = realloc(manager->contexts, (manager->contextCount + 1) * sizeof(LTE_RRC_UE_CONTEXT*));
    manager->contexts[manager->contextCount] = context;
    ++manager->contextCount;

    pthread_mutex_unlock(&manager->lock);
}

void removeContext(ContextManager* manager, int UE_ID) {
    pthread_mutex_lock(&manager->lock);

    // Find the context with the given UE_ID and remove it
    for (size_t i = 0; i < manager->contextCount; ++i) {
        if (manager->contexts[i]->UE_ID == UE_ID) {
            free(manager->contexts[i]->messages);

            // Shift all contexts after the removed one to fill the gap
            for (size_t j = i; j < manager->contextCount - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }

            --manager->contextCount;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
