    // Derive the encryption key and IV from the passphrase using PBKDF2 with HMAC-SHA256
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));
    unsigned char key[32], iv[16];  // AES-256 and GCM use 256 bit keys and 96 bit IVs
    PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase), salt, sizeof(salt), 1000, 32 + 16, key);
    memcpy(iv, &key[32], 16);  // Last 16 bytes of the derived key are used as IV

    // Initialize the cipher context with AES-256-GCM and set the encryption key and IV
    EVP_EncryptInit_ex(context->ctx, EVP_aes_256_gcm(), NULL, key, iv);

    return context;
}
