void initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (LTE_PHY_RX_FRAME_T*)malloc(initialSize * sizeof(LTE_PHY_RX_FRAME_T));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->mutex, NULL);
}

void insertDynamicArray(DynamicArray *a, LTE_PHY_RX_FRAME_T element) {
    pthread_mutex_lock(&a->mutex);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (LTE_PHY_RX_FRAME_T*)realloc(a->array, a->size * sizeof(LTE_PHY_RX_FRAME_T));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->mutex);
}

void freeDynamicArray(DynamicArray *a) {
    pthread_mutex_destroy(&a->mutex);
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
