    pthread_mutex_t lock;
    int count;
    LTE_PHY_RX_FRAME_T** frames;
} FrameCollection;

FrameCollection* create_collection() {
    FrameCollection* collection = malloc(sizeof(FrameCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;
    collection->frames = NULL;

    return collection;
}

void add_frame(FrameCollection* collection, LTE_DL_CCCH_Message_T dl_message, LTE_RRC_CCH_Message_T rrc_message) {
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for a new frame and copy the message data into it.
    LTE_PHY_RX_FRAME_T* frame = malloc(sizeof(LTE_PHY_RX_FRAME_T));
    if (frame == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    time(&frame->timestamp);
    frame->dl_message = dl_message;
    frame->rrc_message = rrc_message;

    // Generate a hash of the message content.
    SHA256_CTX context;
    if(!SHA256_Init(&context)) {
        free(frame);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    // ... Add message content to the hash function here.

    if(!SHA256_Final(frame->hash, &context)) {
        free(frame);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    // Add the new frame to the collection.
    collection->frames = realloc(collection->frames, (collection->count + 1) * sizeof(LTE_PHY_RX_FRAME_T*));
    if (collection->frames == NULL) {
        free(frame);
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    collection->frames[collection->count] = frame;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
}
