void allocate_records(long numOffsets, int numKeys, int numRecords) {
    if (numOffsets <= 0 || numKeys <= 0 || numRecords <= 0) return;

    srand((unsigned int)time(NULL)); // seed the random number generator

    long *offsets = malloc(sizeof(long) * numOffsets);
    for (int i = 0; i < numOffsets; ++i) {
        offsets[i] = rand() % 10000; // generate a random number in [0, 10000)
    }

    int *keys = malloc(sizeof(int) * numKeys);
    for (int i = 0; i < numKeys; ++i) {
        int key;
        do {
            key = rand() % 10000; // generate a random number in [0, 10000)
        } while (contains(keys, key, i)); // check for duplicates
        keys[i] = key;
    }

    record *records = malloc(sizeof(record) * numRecords);
    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = offsets[rand() % numOffsets]; // select a random offset
        records[i].key = keys[rand() % numKeys]; // select a random key
        records[i].value = records[i].offset + records[i].key; // calculate the value
    }

    free(offsets);
    free(keys);
    free(records);
}

int contains(int *array, int val, int size) {
    for (int i = 0; i < size; ++i) {
        if (array[i] == val) return 1; // found a duplicate
    }
    return 0; // no duplicates found
}
