    pthread_mutex_lock(&lock);
    newNode->next = head;
    head = newNode;
    total_connection_attempts++;
    if(strcmp(record.status, "Success") == 0) {
        successful_handshakes++;
    }
    pthread_mutex_unlock(&lock);
}

