    SensorReading sensorReading;
    EnvironmentalData envData;
} Device;

typedef struct {
    size_t count;
    size_t capacity;
    Device* devices;
} DeviceList;

DeviceList createDeviceList(size_t initialCapacity) {
    DeviceList list = {0, initialCapacity, malloc(initialCapacity * sizeof(Device))};
    return list;
}

void destroyDeviceList(DeviceList* list) {
    free(list->devices);
    list->count = 0;
    list->capacity = 0;
    list->devices = NULL;
}

void addDevice(DeviceList* list, Device device) {
    if (list->count == list->capacity) {
        // Double the capacity when full
        list->capacity *= 2;
        list->devices = realloc(list->devices, list->capacity * sizeof(Device));
    }

    list->devices[list->count++] = device;
}

void removeDevice(DeviceList* list, size_t index) {
    if (index < list->count) {
        // Shift all elements after the removed one to fill the gap
        memmove(&list->devices[index], &list->devices[index + 1], (--list->count - index) * sizeof(Device));

        if (list->count <= list->capacity / 4 && list->capacity > 2) {
            // Halve the capacity when it's a quarter full
            list->capacity /= 2;
            list->devices = realloc(list->devices, list->capacity * sizeof(Device));
        }
    }
}
```
This code uses dynamic memory allocation to manage the list of devices. It starts with a small initial capacity and doubles it whenever the list is full. When the list is only a quarter full, it halves its capacity to save memory. This approach balances performance (constant time operations) and memory usage (no wasted space).
