Event *head = NULL;

void addEvent(char* tag, time_t ts, int* sids, int num) {
    Event *newEvent = (Event*) malloc(sizeof(Event));
    newEvent->EVENT_TAG = tag;
    newEvent->timestamp = ts;
    newEvent->SIDs = sids;
    newEvent->numSIDs = num;
    newEvent->next = head;
    head = newEvent;
}

void updateEvent(char* tag, time_t ts, int* sids, int num) {
    Event *current = head;
    while (current != NULL) {
        if (strcmp(current->EVENT_TAG, tag) == 0 && current->timestamp == ts) {
            free(current->SIDs); // Free old SIDs
            current->SIDs = sids;
            current->numSIDs = num;
            return;
        }
        current = current->next;
    }
}

Event* getEventsInRange(time_t start, time_t end) {
    Event *current = head;
    Event *resultHead = NULL;
    while (current != NULL) {
        if (current->timestamp >= start && current->timestamp <= end) {
            Event *newEvent = (Event*) malloc(sizeof(Event));
            newEvent->EVENT_TAG = current->EVENT_TAG;
            newEvent->timestamp = current->timestamp;
            newEvent->SIDs = current->SIDs;
            newEvent->numSIDs = current->numSIDs;
            newEvent->next = resultHead;
            resultHead = newEvent;
