#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct {
    int type;
    time_t timestamp;
    unsigned long sequenceNumber;
    char* payload;
} Message;

Message* createMessages(size_t size, size_t payloadSize) {
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of messages
    Message* messages = (Message*)malloc(size * sizeof(Message));
    if (!messages) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Initialize each message in the array
    for (size_t i = 0; i < size; ++i) {
        messages[i].type = rand();  // Random type
        messages[i].timestamp = time(NULL);  // Current timestamp
        messages[i].sequenceNumber = rand();  // Random sequence number

        // Allocate memory for the payload
        messages[i].payload = (char*)malloc(payloadSize * sizeof(char));
        if (!messages[i].payload) {
            perror("Failed to allocate memory");

            // Free previously allocated memory before returning
            for (size_t j = 0; j < i; ++j) {
                free(messages[j].payload);
            }
            free(messages);

            return NULL;
        }

        // Initialize the payload with random data
        for (size_t j = 0; j < payloadSize; ++j) {
            messages[i].payload[j] = rand() % 256;
        }
    }

    return messages;
}
```
This function creates an array of `Message` structures, each with a dynamically allocated payload. It uses the `rand()` function to generate random data for the message type and sequence number, and also for initializing the payload. If memory allocation fails at any point, it frees all previously allocated memory before returning NULL.

