    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulate(int N, int minRnti, int maxRnti) {
    srand(time(NULL)); // seed the random number generator

    if (N > (maxRnti - minRnti + 1)) {
        printf("Error: Not enough unique RNTI values in range.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int usedRnti[maxRnti - minRnti + 1] = {0}; // array to track used RNTI values

    for (int i = 0; i < N; i++) {
        int rnti;

        do {
            rnti = rand() % (maxRnti - minRnti + 1) + minRnti; // generate a random RNTI within the range
        } while(usedRnti[rnti - minRnti]);

        usedRnti[rnti - minRnti] = 1; // mark this RNTI as used

        array[i].RX_UE_INFORMATION_TAG = i + 1; // set the tag to a valid value
        array[i].RNTI = rnti; // set the RNTI to the generated unique value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // generate a pseudo-random CRCFLAG
    }

    return array;
}
