typedef struct List {
    Record** records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} List;

List* createList(size_t initialCapacity) {
    List* list = malloc(sizeof(List));
    list->records = malloc(initialCapacity * sizeof(Record*));
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addToList(List* list, Record* record) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        list->records = realloc(list->records, 2 * list->capacity * sizeof(Record*));
        list->capacity *= 2;
    }

    list->records[list->size++] = record;

    pthread_mutex_unlock(&list->lock);
}

void destroyList(List* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->records[i]->identifier);
        free(list->records[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list->records);
    free(list);
}
```
