["Here is a basic implementation of your requirements using C11's `_Atomic` types and POSIX threads (pthreads). This code does not include all the features you requested, such as scalability or operational constraints handling, but it provides a good starting point for building a high-performance video streaming service.

```c
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    // Define your VIDEO_FRAME structure here
} VIDEO_FRAME;

typedef struct {
    int STREAM_ID;
    int USER_ID;
    _Atomic(VIDEO_FRAME*) frames;
    pthread_mutex_t lock;
} MEDIA_STREAM;

MEDIA_STREAM* createStream(int streamId, int userId) {
    MEDIA_STREAM* stream = malloc(sizeof(MEDIA_STREAM));
    if (stream == NULL) return NULL;

    stream->STREAM_ID = streamId;
    stream->USER_ID = userId;
    atomic_init(&stream->frames, NULL);
    pthread_mutex_init(&stream->lock, NULL);

    return stream;
}

void addFrame(MEDIA_STREAM* stream, VIDEO_FRAME* frame) {
    pthread_mutex_lock(&stream->lock);

    // Add the frame to the end of the linked list
    VIDEO_FRAME** current = atomic_load(&stream->frames);
    while (*current != NULL) {
        current = &(*current)->next;
    }
    *current = frame;

    pthread_mutex_unlock(&stream->lock);
}

VIDEO_FRAME* removeFrame(MEDIA_STREAM* stream) {
    pthread_mutex_lock(&stream->lock);

    // Remove the first frame from the linked list
    VIDEO_FRAME** current = atomic_load(&stream->frames);
    if (*current == NULL) {
        pthread_mutex_unlock(&stream->lock);
        return NULL;
    }

    VIDEO_FRAME* frame = *current;
    *current = frame->next;

    pthread_mutex_unlock(&stream->lock);

    return frame;
}

void destroyStream(MEDIA_STREAM* stream) {
    // Free all frames in the linked list
    VIDEO_FRAME* current = atomic_load(&stream->frames);
    while (current != NULL) {
        VIDEO_FRAME* next = current->next;
        free(current);
        current = next;
    }

    // Destroy the mutex and the stream itself
    pthread_mutex_destroy(&stream->lock);
    free(stream);
}
```
This code uses a linked list to store frames in each `MEDIA_STREAM`. It uses an atomic operation to load and store the head of the list, which ensures that all threads see a consistent state of the list. The mutex is used to ensure that only one thread can modify the list at a time, preventing data corruption due to concurrent modifications.

Please note that this code does not include error handling for malloc failures or other potential issues. In a real-world application, you would want to add appropriate error checking and recovery mechanisms. Also, please replace `VIDEO_FRAME` with your actual structure definition.
"]

