['Here is a basic implementation in C that meets your specifications. This example does not include dynamic resizing, as it would require more complex logic to handle memory allocation and deallocation efficiently. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* string;
} item;

typedef struct {
    char* key;
    int default_value;
} config_option;

typedef struct {
    item* items;
    size_t num_items;
    config_option* options;
    size_t num_options;
} config;

config read_input(FILE* input) {
    config cfg = {0};

    // Read number of items and options
    fscanf(input, "%zu %zu", &cfg.num_items, &cfg.num_options);

    // Allocate memory for items and options
    cfg.items = malloc(sizeof(item) * cfg.num_items);
    cfg.options = malloc(sizeof(config_option) * cfg.num_options);

    // Read item values and strings
    for (size_t i = 0; i < cfg.num_items; ++i) {
        fscanf(input, "%lf", &cfg.items[i].value);

        char buffer[128];
        fgets(buffer, sizeof(buffer), input);
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len-1] == '\n') {
            buffer[--len] = 0; // Remove trailing newline
        }

        cfg.items[i].string = malloc(len + 1);
        strcpy(cfg.items[i].string, buffer);
    }

    // Read option keys and default values
    for (size_t i = 0; i < cfg.num_options; ++i) {
        char buffer[64];
        fscanf(input, "%s %d", buffer, &cfg.options[i].default_value);

        size_t len = strlen(buffer);
        cfg.options[i].key = malloc(len + 1);
        strcpy(cfg.options[i].key, buffer);
    }

    return cfg;
}

void free_config(config* cfg) {
    // Free item strings and array
    for (size_t i = 0; i < cfg->num_items; ++i) {
        free(cfg->items[i].string);
    }
    free(cfg->items);

    // Free option keys and array
    for (size_t i = 0; i < cfg->num_options; ++i) {
        free(cfg->options[i].key);
    }
    free(cfg->options);
}
```
This code reads the number of items and options, then allocates memory for them. It uses `fscanf` to read the item values and strings, and `fgets` to read the option keys and default values. The function returns a `config` structure that contains the allocated memory. 

The `free_config` function frees all dynamically allocated memory when it's no longer needed. It must be called whenever you're done with the `config` structure, to prevent memory leaks.
