#include <stdatomic.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    _Atomic(struct Node*) next;
    NFAPI_CRC_INDICATION_PDU_T data;
} Node;

Node* createList(int size) {
    srand(time(NULL));
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < size; ++i) {
        Node *newNode = malloc(sizeof(Node));
        newNode->data.RX_UE_INFORMATION_TAG = rand();
        newNode->data.RNTI = rand();
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRC flag
        atomic_init(&newNode->next, NULL);

        if (head == NULL) {
            head = tail = newNode;
        } else {
            atomic_store(&tail->next, newNode);
            tail = newNode;
        }
    }
    return head;
}

void insert(Node **head, Node *newNode) {
    newNode->next = NULL;
    if (*head == NULL) {
        atomic_store(&(*head), newNode);
    } else {
        Node *current = *head;
        while (atomic_load(&current->next)) {
            current = atomic_load(&current->next);
        }
        atomic_store(&(current->next), newNode);
    }
}

void delete(Node **head, int RNTI) {
    Node *prev = NULL;
    Node *curr = *head;

    while (curr != NULL && curr->data.RNTI != RNTI) {
        prev = curr;
        curr = atomic_load(&(curr->next));
    }

    if (curr == NULL) return; // Not found

    if (prev == NULL) {
        *head = curr->next;
    } else {
        prev->next = curr->next;
    }

    free(curr);
}
```
