record* process_csv(const char* filename, size_t memory_limit, int key_range, int* num_records) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open the file.\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = allocate_memory(sizeof(long), memory_limit);
    int* keys = allocate_memory(sizeof(int) * key_range, memory_limit);
    memset(keys, 0, sizeof(int) * key_range); // Initialize all elements to zero.

    record* records = NULL;
    size_t num_allocated = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int key;
        double value;

        if (sscanf(line, "%d,%lf", &key, &value) != 2) {
            printf("Invalid format in the CSV file.\n");
            continue;
        }

        // Check for key uniqueness.
        if (keys[key] == 1) {
            printf("Duplicate key found: %d\n", key);
            continue;
        }
        keys[key] = 1;

        // If the number of records exceeds the allocated size, reallocate memory for the array.
        if (*num_records >= num_allocated) {
            num_allocated = num_allocated == 0 ? 1 : num_allocated * 2;
            records = realloc(records, sizeof(record) * num_allocated);
            if (records == NULL) {
                printf("Memory allocation failed.\n");
                exit(EXIT_FAILURE);
            }
        }

        // Set the record values.
        records[*num_records].key = key;
        records[*num_records].value = value;
        (*num_records)++;
    }

    fclose(file);
    free(offsets);
    free(keys);

    return records;
}
```
