```c
#include <stdlib.h>
#include <pthread.h>

typedef struct MAC_SUB_LAYER_CONFIGURATION_T {
    // Add your fields here
} MAC_SUB_LAYER_CONFIGURATION_T;

typedef struct PHY_LAYER_CONFIGURATION_T {
    // Add your fields here
} PHY_LAYER_CONFIGURATION_T;

typedef struct NetworkInterfaceConfig {
    int interfaceID;
    MAC_SUB_LAYER_CONFIGURATION_T macSubLayerConfig;
    PHY_LAYER_CONFIGURATION_T phyLayerConfig;
    struct NetworkInterfaceConfig* next;
} NetworkInterfaceConfig;

NetworkInterfaceConfig* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addOrUpdate(int interfaceID, MAC_SUB_LAYER_CONFIGURATION_T macSubLayerConfig, PHY_LAYER_CONFIGURATION_T phyLayerConfig) {
    pthread_mutex_lock(&lock);

    NetworkInterfaceConfig* current = head;
    while (current != NULL && current->interfaceID != interfaceID) {
        if (current->next == NULL || current->next->interfaceID > interfaceID) break;
        current = current->next;
    }

    if (current != NULL && current->interfaceID == interfaceID) {
        // Update existing config
        current->macSubLayerConfig = macSubLayerConfig;
        current->phyLayerConfig = phyLayerConfig;
    } else {
        // Add new node
        NetworkInterfaceConfig* newNode = malloc(sizeof(NetworkInterfaceConfig));
        newNode->interfaceID = interfaceID;
        newNode->macSubLayerConfig = macSubLayerConfig;
        newNode->phyLayerConfig = phyLayerConfig;

        if (current != NULL) {
            // Insert in the middle of list
            newNode->next = current->next;
            current->next = newNode;
        } else {
            // Append to end of list
            newNode->next = head;
            head = newNode;
        }
    }

    pthread_mutex_unlock(&lock);
}

NetworkInterfaceConfig* get(int interfaceID) {
    pthread_mutex_lock(&lock);

    NetworkInterfaceConfig* current = head;
    while (current != NULL && current->interfaceID < interfaceID) {
        current = current->next;
    }

    if (current != NULL && current->interfaceID == interfaceID) {
        pthread_mutex_unlock(&lock);
        return current;
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}
```
