    if (table == NULL) return NULL;

    pthread_mutex_init(&table->lock, NULL);
    table->contexts = calloc(1024, sizeof(LTE_RRC_UE_CONTEXT*)); // Start with 1024 slots
    if (table->contexts == NULL) {
        free(table);
        return NULL;
    }

    table->count = 1024;
