}

LTE_RRC_UE_CONTEXT* getContext(HashTable* table, int UE_ID) {
    pthread_mutex_lock(&table->lock);
    LTE_RRC_UE_CONTEXT* context = table->contexts[UE_ID % table->count];
    pthread_mutex_unlock(&table->lock);

    return context;
}

void addContext(HashTable* table, int UE_ID) {
