    pthread_mutex_unlock(&table->lock);
}

void removeContext(HashTable* table, int UE_ID) {
    pthread_mutex_lock(&table->lock);
    LTE_RRC_UE_CONTEXT* context = table->contexts[UE_ID % table->count];
    if (context != NULL) {
        free(context->messages); // Free messages first to avoid memory leak
        pthread_mutex_destroy(&context->lock);
        free(context);
        table->contexts[UE_ID % table->count] = NULL;
    }
    pthread_mutex_unlock(&table->lock);
}

char* appendSlashIfNeeded(const char* input, size_t maxSize) {
    if (strlen(input) >= maxSize) return NULL;

    size_t newLength = strlen(input) + 2; // +1 for '/', +1 for '\0'
    char* output = malloc(newLength);
    if (output == NULL) return NULL;

    strcpy(output, input);
    output[newLength - 2] = '/';
    output[newLength - 1] = '\0';

    return output;
}
