#include <mutex>

class Buffer {
public:
    void appendData(const std::string& data) {
        // Append the data to your buffer here.
    }
};

std::mutex mtx;  // mutex for critical section

void insertOrAppendData(std::vector<std::shared_ptr<Buffer>>& bufferPool, size_t index, const std::string& data) {
    std::lock_guard<std::mutex> lock(mtx);

    if (index < bufferPool.size()) {
        bufferPool[index]->appendData(data);
    } else {
        auto newBuffer = std::make_shared<Buffer>();
        newBuffer->appendData(data);
        bufferPool.push_back(newBuffer);
    }
}
