void addToList(DynamicList* list, Record* record) {
    pthread_mutex_lock(&list->lock);

    if (list->currentSize == list->maxSize) {
        // Resize the list
        list->maxSize *= 2;
        list->records = realloc(list->records, list->maxSize * sizeof(Record*));
    }

    list->records[list->currentSize++] = record;

    pthread_mutex_unlock(&list->lock);
}

