typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->data == NULL) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}

int add_to_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Error: Out of memory
        }

        array->capacity = new_capacity;
        array->data = new_data;
    }

    array->data[array->size++] = value;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}
```
