import java.nio.file.Paths;
import java.util.logging.Logger;

public class StateLoader {
    private static final Logger logger = Logger.getLogger(StateLoader.class.getName());

    public MoSTState loadStateFromFile(String filePath) {
        if (!filePath.endsWith(".state") && !filePath.endsWith(".old-state")) {
            logger.warning("Invalid file extension: " + filePath);
            return null;
        }

        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = in.readObject();

            if (!(obj instanceof MoSTState)) {
                logger.warning("Deserialized object is not a MoSTState: " + filePath);
                return null;
            }

            return (MoSTState) obj;
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Failed to load state from file: " + filePath);
            e.printStackTrace();
            return null;
        }
    }
}
```

