['Here is a basic implementation of `CombatManager` class in C++. This code does not include all the features you mentioned, but it provides a starting point for your requirements. 

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <chrono>

class Entity {
public:
    int id;
    double energy;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime;
};

class Attack {
public:
    int id;
    double energyCost;
    std::chrono::duration<double> cooldownDuration;
};

class CombatManager {
private:
    std::unordered_map<int, Entity*> entities;
    std::unordered_map<int, Attack*> attacks;
public:
    void addEntity(int id) {
        if (entities.find(id) == entities.end()) {
            entities[id] = new Entity{id, 100.0}; // Initial energy is set to 100
        } else {
            std::cout << "Entity with id " << id << " already exists." << std::endl;
        }
    }

    void addAttack(int id, double energyCost, std::chrono::duration<double> cooldownDuration) {
        if (attacks.find(id) == attacks.end()) {
            attacks[id] = new Attack{id, energyCost, cooldownDuration};
        } else {
            std::cout << "Attack with id " << id << " already exists." << std::endl;
        }
    }

    bool performAttack(int entityId, int attackId) {
        if (entities.find(entityId) == entities.end()) {
            std::cout << "Entity with id " << entityId << " does not exist." << std::endl;
            return false;
        }

        if (attacks.find(attackId) == attacks.end()) {
            std::cout << "Attack with id " << attackId << " does not exist." << std::endl;
            return false;
        }

        Entity* entity = entities[entityId];
        Attack* attack = attacks[attackId];

        auto now = std::chrono::system_clock::now();
        if (entity->energy >= attack->energyCost && 
            now - entity->lastAttackTime > attack->cooldownDuration) {

            entity->energy -= attack->energyCost;
            entity->lastAttackTime = now;
            std::cout << "Entity with id " << entityId 
                      << " performed attack with id " << attackId << std::endl;
            return true;
        } else {
            std::cout << "Cannot perform attack. Either not enough energy or on cooldown." << std::endl;
            return false;
        }
    }

    void regenerateEnergy(double rate) {
        for (auto& pair : entities) {
            Entity* entity = pair.second;
            auto now = std::chrono::system_clock::now();

            if (entity->energy < 100 && 
                now - entity->lastAttackTime > std::chrono::seconds(1)) { // Regenerate every second

                entity->energy += rate;
                if (entity->energy > 100) {
                    entity->energy = 100;
                }
            }
        }
    }
};
```
This code does not include logging, analytics or fallback actions. Also, it doesn't handle concurrent access to the entities and attacks maps which would require synchronization mechanisms like locks or atomic operations. It also doesn't support scaling up to thousands of entities or adding new attacks dynamically. 

For a production-grade system, you would need to add these features and consider other trade-offs such as memory usage, code complexity, and performance under different load conditions. You might also want to use a more sophisticated data structure for the entities and attacks maps if they grow large, or use a database instead of in-memory storage.
