#include <stdbool.h>
#include "cJSON.h"

// Function to validate OAuth2 access token response
bool validate_access_token(const char* json) {
    // Parse the JSON object
    cJSON *root = cJSON_Parse(json);
    if (root == NULL) {
        return false;  // Invalid JSON format
    }

    // Check for required fields
    cJSON *access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    cJSON *expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    cJSON *token_type = cJSON_GetObjectItemCaseSensitive(root, "token_type");

    if (!cJSON_IsString(access_token) || !cJSON_IsNumber(expires_in) || !cJSON_IsString(token_type)) {
        return false;  // Missing or invalid field types
    }

    // Check for optional fields
    cJSON *refresh_token = cJSON_GetObjectItemCaseSensitive(root, "refresh_token");
    if (refresh_token != NULL && !cJSON_IsString(refresh_token)) {
        return false;  // Invalid refresh_token field type
    }

    // Check for specific values
    if (strcmp(token_type->valuestring, "Bearer") != 0 || expires_in->valueint <= 0) {
        return false;  // Unexpected token_type or non-positive expires_in value
    }

    // Cleanup and return success
    cJSON_Delete(root);
    return true;
}
```

This function uses the `cJSON` library to parse the JSON object, then checks for the existence and types of required fields. It also checks for an optional refresh token field and specific values for token type and expires in. If any check fails, it returns false indicating invalid access token response. 

