['Here is a basic implementation of your requirements in C. This code does not cover all aspects you mentioned due to complexity but it gives an idea about how to manage memory for three distinct data structures. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char* buffer;
} record;

void manage_memory(int key_count, long offset_range) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays
    int* keys = malloc(key_count * sizeof(int));
    long* offsets = malloc(key_count * sizeof(long));
    record* records = malloc(key_count * sizeof(record));

    if (keys == NULL || offsets == NULL || records == NULL) {
        // Handle memory allocation failure
        exit(-1);
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < key_count; ++i) {
        keys[i] = i;  // Initialize 'int' keys array with sequential integers
    }
    pthread_mutex_unlock(&lock);

    srand(time(NULL));
    for (int i = 0; i < key_count; ++i) {
        offsets[i] = rand() % offset_range;  // Initialize 'long' offsets array with random values
    }

    for (int i = 0; i < key_count; ++i) {
        records[i].value = rand();  // Populate the 'record' structures with a random integer value

        char buffer[16];
        sprintf(buffer, "%d", keys[i]);
        size_t len = strlen(buffer);
        records[i].buffer = malloc(len + 1);  // Allocate memory for the record's char buffer

        if (records[i].buffer == NULL) {
            // Handle memory allocation failure
            exit(-1);
        }

        strcpy(records[i].buffer, buffer);  // Initialize the record's char buffer with a unique string identifier
    }

    // Free allocated memory before function exits
    for (int i = 0; i < key_count; ++i) {
        free(records[i].buffer);
    }

    free(keys);
    free(offsets);
    free(records);
}
```
This code is a basic example and does not cover all aspects you mentioned due to complexity. It's recommended to use more advanced memory management techniques, such as memory pools or garbage collection strategies for handling large amounts of data efficiently. Also, it's important to consider the system load and resource contention during garbage collection to prevent performance bottlenecks.
