    PHY_LAYER_PAYLOAD payload;
    FRAME_HEADER header;
} DL_FRAME_USER_DATA;

typedef struct {
    int UE_INDEX;
    int RNTI;
    DL_FRAME_USER_DATA data;
} LTE_DL_FRAME_USER;

typedef struct {
    pthread_mutex_t lock;
    size_t bufferSize;
    size_t currentIndex;
    LTE_DL_FRAME_USER* buffer;
} DynamicBuffer;

DynamicBuffer* createBuffer(size_t initialSize) {
    DynamicBuffer* buf = malloc(sizeof(DynamicBuffer));
    if (buf == NULL) return NULL; // Handle allocation failure

    pthread_mutex_init(&buf->lock, NULL);
    buf->bufferSize = initialSize;
    buf->currentIndex = 0;
    buf->buffer = malloc(sizeof(LTE_DL_FRAME_USER) * initialSize);

    if (buf->buffer == NULL) { // Handle allocation failure
        free(buf);
        return NULL;
    }

    return buf;
}

void destroyBuffer(DynamicBuffer* buf) {
    pthread_mutex_destroy(&buf->lock);
    free(buf->buffer);
    free(buf);
}

int addToBuffer(DynamicBuffer* buf, LTE_DL_FRAME_USER data) {
    pthread_mutex_lock(&buf->lock);

    if (buf->currentIndex >= buf->bufferSize) {
        // Reallocate buffer with double the size
        LTE_DL_FRAME_USER* newBuffer = realloc(buf->buffer, sizeof(LTE_DL_FRAME_USER) * buf->bufferSize * 2);

        if (newBuffer == NULL) { // Handle allocation failure
            pthread_mutex_unlock(&buf->lock);
            return -1;
        }

        buf->buffer = newBuffer;
        buf->bufferSize *= 2;
    }

    memcpy(&buf->buffer[buf->currentIndex++], &data, sizeof(LTE_DL_FRAME_USER));

    pthread_mutex_unlock(&buf->lock);
    return 0; // Success
}
```
This code creates a dynamic buffer that can be accessed concurrently from multiple threads. It uses a mutex to ensure thread safety, and automatically resizes the buffer when it becomes full. Note that this is just a basic example and does not include all of your requested features. You would need to add more error checking, logging, and other features as needed for your specific application.
