void init_and_manage_pool(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&lock);

    if (pool_size >= MAX_POOL_SIZE) {
        // Handle pool full scenario, e.g., resize the pool
        printf("Pool is full\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    int rnti = data->RNTI;
    if (rnti < VALID_RANGE_START || rnti > VALID_RANGE_END) {
        // Handle invalid RNTI scenario
        printf("Invalid RNTI: %d\n", rnti);
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < pool_size; ++i) {
        if (pool[i]->RNTI == rnti) {
            // Handle duplicate RNTI scenario, e.g., skip or log a warning message
            printf("Duplicate RNTI: %d\n", rnti);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    pool[pool_size++] = data;
    // Generate CRC flag based on a seeded random number generator
    data->CRC_INDICATION_REL8_TAG = rand();

    pthread_mutex_unlock(&lock);
}
