pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* createArray(int N) {
    pthread_mutex_lock(&lock);

    static int currentSize = 0;
    static NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    if (N > currentSize) {
        currentSize = N * 2; // Double the size to reduce reallocations
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * currentSize);

        for (int i = N; i < currentSize; ++i) {
