    pthread_mutex_t lock;
    size_t allocated;
    size_t used;
    NFAPI_CRC_INDICATION_PDU_T *array;
} ArrayManager;

ArrayManager* createArray(size_t initialSize) {
    ArrayManager *manager = malloc(sizeof(ArrayManager));
    if (manager == NULL) return NULL;

    manager->array = calloc(initialSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->array == NULL) {
        free(manager);
        return NULL;
    }

    manager->allocated = initialSize;
    manager->used = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroyArray(ArrayManager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addElement(ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used == manager->allocated) {
        size_t newSize = manager->allocated * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(manager->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (newArray == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->array = newArray;
        manager->allocated = newSize;
    }

    manager->array[manager->used] = element;
    manager->used++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}
