```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    // Add your data here
} UEContext;

typedef struct {
    pthread_mutex_t lock;
    UEContext *contexts;
    size_t capacity;
    size_t size;
} UEContextManager;

UEContextManager* create_manager(size_t initialCapacity) {
    UEContextManager *manager = malloc(sizeof(UEContextManager));
    if (manager == NULL) return NULL;

    manager->contexts = calloc(initialCapacity, sizeof(UEContext));
    if (manager->contexts == NULL) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(UEContextManager *manager) {
    assert(manager != NULL);

    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_context(UEContextManager *manager, UEContext context) {
    assert(manager != NULL);

    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        UEContext *newContexts = realloc(manager->contexts, newCapacity * sizeof(UEContext));

        if (newContexts == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }

        manager->capacity = newCapacity;
        manager->contexts = newContexts;
    }

    manager->contexts[manager->size++] = context;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}
```
This code creates a `UEContextManager` that manages an array of `UEContext` structures. It uses a mutex to ensure thread safety during initialization and data manipulation. The manager dynamically resizes the array when it's full, which can be inefficient if done frequently. You might want to consider a different strategy for dynamic resizing based on your specific use case.
