```c
#include <stdlib.h>
#include <pthread.h>
#include <glib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t mutex;
    int maxSize;
    int size;
} LinkedList;

LinkedList* createList(int maxSize) {
    LinkedList* list = g_new0(LinkedList, 1);
    list->maxSize = maxSize;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void addToList(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->maxSize) {
        // Handle error: list is full
        return;
    }

    Node* node = g_new0(Node, 1);
    node->data = data;
    node->next = list->head;
    list->head = node;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

int getListSize(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    int size = list->size;
    pthread_mutex_unlock(&list->mutex);

    return size;
}

void iterateOverList(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->mutex);

    Node* node = list->head;
    while (node != NULL) {
        callback(node->data);
        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex);
}
```
This code creates a linked list that can be safely accessed from multiple threads. It uses glib for memory management, which is efficient and thread-safe. The `addToList` function adds an element to the list, while `getListSize` returns the current size of the list. The `iterateOverList` function allows you to iterate over all elements in the list by providing a callback function that will be called for each element.
