    int sequenceNumber;
    char* payload;
    unsigned checksum;
    struct MAC_PDU* next;
} MAC_PDU;

typedef struct LinkedList {
    atomic_int size;
    pthread_mutex_t lock;
    MAC_PDU* head;
    MAC_PDU* tail;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    return list;
}

void addToList(LinkedList* list, MAC_PDU* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = pdu;
        list->tail = pdu;
    } else {
        list->tail->next = pdu;
        list->tail = pdu;
    }

    atomic_fetch_add(&list->size, 1);

    pthread_mutex_unlock(&list->lock);
}

MAC_PDU* removeFromList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    MAC_PDU* pdu = list->head;
    list->head = list->head->next;
    if (list->head == NULL) {
        list->tail = NULL;
    }

    atomic_fetch_sub(&list->size, 1);

    pthread_mutex_unlock(&list->lock);

    return pdu;
}

int getListSize(LinkedList* list) {
    return atomic_load(&list->size);
}
```
