void add(NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    newNode->data = value;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeByRNTI(int rnti) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && temp->data.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // value not found

    if (prev != NULL) 
