import java.io.*;
import java.util.*;
import java.util.concurrent.locks.*;
import org.apache.log4j.Logger;

public class ThemeCacheManager {
    private static final Logger logger = Logger.getLogger(ThemeCacheManager.class);

    // Cache map to store theme bitmaps
    private Map<String, Bitmap> cacheMap = new HashMap<>();
    private ReadWriteLock lock = new ReentrantReadWriteLock();

    // Default theme directory and other directories with priority levels
    private String defaultThemeDir;
    private List<Pair<String, Integer>> themeDirs = new ArrayList<>();

    public ThemeCacheManager(String defaultThemeDir) {
        this.defaultThemeDir = defaultThemeDir;
    }

    // Add a directory with priority level
    public void addThemeDirectory(String dirPath, int priority) {
        themeDirs.add(new Pair<>(dirPath, priority));
        Collections.sort(themeDirs, Comparator.comparingInt(Pair::second));
    }

    // Get a bitmap from cache or load it if not present
    public Bitmap getBitmap(String themeName) {
        lock.readLock().lock();
        try {
            Bitmap bitmap = cacheMap.get(themeName);
            if (bitmap != null) return bitmap;

            // Load from directories in priority order
            for (Pair<String, Integer> dir : themeDirs) {
                File file = new File(dir.first + "/" + themeName + ".png");
                if (file.exists()) {
                    bitmap = loadBitmapFromFile(file);
                    cacheMap.put(themeName, bitmap);
                    return bitmap;
                }
            }

            // Load from default directory if not found in other directories
            File file = new File(defaultThemeDir + "/" + themeName + ".png");
            if (file.exists()) {
                bitmap = loadBitmapFromFile(file);
                cacheMap.put(themeName, bitmap);
                return bitmap;
            }
        } finally {
            lock.readLock().unlock();
        }

        logger.error("Theme not found: " + themeName);
        return null;
    }

    // Load a bitmap from file and validate it
    private Bitmap loadBitmapFromFile(File file) {
        try (InputStream is = new FileInputStream(file)) {
            byte[] bytes = is.readAllBytes();

            // Validate file size, format, integrity etc.
            if (!validateFile(bytes)) {
                logger.error("Invalid theme file: " + file.getName());
                return null;
            }

            Bitmap bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            return bitmap;
        } catch (IOException e) {
            logger.error("Error loading theme: " + file.getName(), e);
            return null;
        }
    }

    // Validate a file
    private boolean validateFile(byte[] bytes) {
        // Implement validation logic here
        return true;
    }
}
