```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char** fields;
    int num_fields;
} LineData;

void* processFile(void* fileName) {
    FILE *file = fopen((char*)fileName, "r");
    if (file == NULL) {
        printf("Could not open file %s\n", (char*)fileName);
        pthread_exit(NULL);
    }

    char line[256];
    int totalLines = 0;
    int skippedLines = 0;
    while (fgets(line, sizeof(line), file)) {
        totalLines++;

        // Split the line into fields
        LineData* data = malloc(sizeof(LineData));
        char *token = strtok(line, " ");
        int numFields = 0;
        while (token != NULL) {
            if (numFields == 0) {
                data->fields = realloc(data->fields, sizeof(char*) * (numFields + 1));
            }
            data->fields[numFields++] = strdup(token);
            token = strtok(NULL, " ");
        }

        // Check if there are at least three numeric fields
        if (numFields < 3) {
            skippedLines++;
            continue;
        }

        // Calculate the average of the last three numeric fields
        double sum = 0.0;
        for (int i = numFields - 3; i < numFields; i++) {
            sum += atof(data->fields[i]);
        }
        int avg = (int)(sum / 3.0 + 0.5); // Round to nearest integer

        printf("Average of last three fields in line %d: %d\n", totalLines, avg);
    }

    fclose(file);
    printf("Processed %d lines (skipped %d due to insufficient numeric fields)\n", totalLines, skippedLines);
    pthread_exit(NULL);
}

int main() {
    char* fileNames[] = {"file1.txt", "file2.txt"}; // Replace with actual filenames
    int numFiles = sizeof(fileNames) / sizeof(char*);

    pthread_t threads[numFiles];
    for (int i = 0; i < numFiles; i++) {
        if (pthread_create(&threads[i], NULL, processFile, fileNames[i])) {
            printf("Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numFiles; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
