    pthread_mutex_lock(&array->lock);

    // Reallocate the array if necessary
    for (int i = 0; i < array->size; ++i) {
        if (array->tables[i] == NULL) {
            array->tables[i] = table;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    // If we're here, the array is full. Double its size and add the new table.
    int oldSize = array->size;
    array->tables = realloc(array->tables, 2 * oldSize * sizeof(LTE_PHY_MIB_TABLE_T*));

    // Initialize the newly allocated memory to NULL
    for (int i = oldSize; i < 2 * oldSize; ++i) {
        array->tables[i] = NULL;
    }

    array->size = 2 * oldSize;
    array->tables[oldSize] = table;

    pthread_mutex_unlock(&array->lock);
}
```
This code creates a dynamic array of `LTE_PHY_MIB_TABLE_T` structures, each containing a valid `MIB_T`, `SNTP_SYNC_STATUS`, and a list of `NFAPI_CRC_INDICATION_PDU_T` structures. The array is thread-safe for concurrent updates thanks to the use of pthread mutexes.
"]

