void addUEContext(UEContext* newUEContext) {
    if (newUEContext == NULL || newUEContext->uei == 0) return; // Ensure proper initialization of newUEContext

    Node* newNode = malloc(sizeof(Node));
    newNode->data = newUEContext;
    newNode->next = head;
    head = newNode;
    size++;
}

void removeByUEI(int uei) {
    Node* temp = head, *prev = NULL;

    if (temp != NULL && temp->data->uei == uei) { // If UEI is in the head node
        head = temp->next;
        free(temp);
        size--;
        return;
    }

    while (temp != NULL && temp->data->uei != uei) { // Else search for UEI in the list
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // If UEI was not present in linked list

    prev->next = temp->next; // Unlink the node from linked list
    free(temp); // Free memory
    size--;
}

UEContext* getByIndex(int index) {
    if (index < 0 || index >= size) return NULL;

    Node* current = head;
    int count = 0;
    while (current != NULL) {
        if (count++ == index)
            return current->data;
        current = current->next;
    }
    return NULL; // If node not found
}
