            for (j = 0; j < i; ++j) {
                if (identifiers[j] == randomIdentifier) break; // check for duplicates
            }
        } while (j < i);

        identifiers[i] = randomIdentifier;
    }

    for (i = 0; i < num_records; ++i) {
