    struct HashTableNode *next;
} HashTableNode;

typedef struct HashTable {
    int size;
    int capacity;
    double loadFactor;
    pthread_mutex_t lock;
    HashTableNode **table;
} HashTable;

HashTable* createHashTable(int initialCapacity, double loadFactor) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->capacity = initialCapacity;
    ht->loadFactor = loadFactor;
    ht->table = calloc(initialCapacity, sizeof(HashTableNode*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void resize(HashTable *ht) {
    // Resize the hash table and rehash all entries.
    // This should be done in a way that minimizes lock contention.
}

int hashCode(LTE_ENB_NODE_CONFIG_T *value, int capacity) {
    // A simple hash function for demonstration purposes.
    return value->ENB_ID % capacity;
}

void put(HashTable *ht, LTE_ENB_NODE_CONFIG_T *value) {
    pthread_mutex_lock(&ht->lock);

    if (ht->size / ht->capacity > ht->loadFactor) {
        resize(ht);
    }

    int index = hashCode(value, ht->capacity);
    HashTableNode *node = malloc(sizeof(HashTableNode));
    node->value = value;
    node->next = ht->table[index];
    ht->table[index] = node;

    pthread_mutex_unlock(&ht->lock);
}

LTE_ENB_NODE_CONFIG_T* get(HashTable *ht, int ENB_ID) {
    pthread_mutex_lock(&ht->lock);

    int index = hashCode(&(LTE_ENB_NODE_CONFIG_T){.ENB_ID=ENB_ID}, ht->capacity);
    HashTableNode *node = ht->table[index];
    while (node != NULL) {
        if (node->value->ENB_ID == ENB_ID) {
            pthread_mutex_unlock(&ht->lock);
            return node->value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}
```
This code uses a simple hash function and linear probing to handle collisions. It also uses a single lock for the entire table, which could lead to performance bottlenecks under high concurrency. A more efficient approach would be to use separate locks for each bucket in the table, but this would require more complex code and potentially more memory usage.

