["Here is a basic implementation in C that meets the requirements. It uses OpenSSL for hashing and random string generation. Note that this is a simplified version of what you might need to implement such a function. 

```c
#include <openssl/sha.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

char *generateRandomString(int length, const char *charset) {
    char *randomString = malloc(length + 1);
    if (!randomString) return NULL;

    for (int n = 0;n < length;n++) {
        int key = RAND_bytes((unsigned char*)&key, sizeof(key));
        randomString[n] = charset[key % strlen(charset)];
    }
    randomString[length] = '\0';

    return randomString;
}

void hashString(const unsigned char *string, unsigned char **digest, unsigned int *digest_length) {
    SHA256_CTX context;
    if(!SHA256_Init(&context)) goto error;

    if(!SHA256_Update(&context, string, strlen((char*)string))) goto error;

    *digest = malloc(SHA256_DIGEST_LENGTH);
    if (!*digest) goto error;

    if(!SHA256_Final(*digest, &context)) goto error;

    *digest_length = SHA256_DIGEST_LENGTH;
    return;
error:
    free(randomString);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* manageList(int N, const char *charset) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < N; i++) {
        char* randomString = generateRandomString(16, charset);

        unsigned char *digest;
        unsigned int digest_length;
        hashString((unsigned char*)randomString, &digest, &digest_length);

        list[i].RX_UE_INFORMATION_TAG = randomString;
        list[i].CRCFLAG = *(int*)digest; // Assuming digest is small enough to fit into an int.
    }

    return list;
}
```
This code generates a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a randomly generated string and its SHA256 hash. The length of the random strings is set to 16 characters for simplicity, but it can be adjusted as needed. The hash function used here is SHA-256, which provides good security while being relatively fast.
