typedef struct {
    int value;
} IntegerStream;

IntegerStream* stream = NULL;
size_t streamSize = 0;
int maxValue = INT_MIN;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processStream(void* arg) {
    IntegerStream* localStream = (IntegerStream*)arg;
    int localMax = INT_MIN;

    for (size_t i = 0; i < streamSize; ++i) {
        if (localStream[i].value > localMax) {
            localMax = localStream[i].value;
        }
    }

    pthread_mutex_lock(&lock);
    if (localMax > maxValue) {
        maxValue = localMax;
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    // Allocate memory for the stream
    printf("Enter the size of the integer stream: ");
    scanf("%zu", &streamSize);
    stream = (IntegerStream*)malloc(sizeof(IntegerStream) * streamSize);

    if (!stream) {
        fprintf(stderr, "Failed to allocate memory for the stream\n");
        return 1;
    }

    // Populate the stream with random integers
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < streamSize; ++i) {
        stream[i].value = rand();
    }

    // Create a thread to process the stream
    pthread_t thread;
    if (pthread_create(&thread, NULL, &processStream, stream)) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    // Wait for the thread to finish and print the maximum value
    pthread_join(thread, NULL);
    printf("Maximum value in the stream: %d\n", maxValue);

    free(stream);

    return 0;
}
