    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp; // for aging mechanism
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head;
} LinkedList;

LinkedList list = { PTHREAD_MUTEX_INITIALIZER, NULL };
time_t ageThreshold = 60; // 1 minute

void addElement(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list.lock);

    NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    newElement->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newElement->CRCFLAG = CRCFLAG;
    newElement->timestamp = time(NULL);

    newElement->next = list.head;
    list.head = newElement;

    pthread_mutex_unlock(&list.lock);
}

void pruneList() {
    pthread_mutex_lock(&list.lock);

    time_t currentTime = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T *currentElement = list.head;
    NFAPI_CRC_INDICATION_PDU_T *previousElement = NULL;

    while (currentElement != NULL) {
        if (difftime(currentTime, currentElement->timestamp) > ageThreshold) {
            // Remove the element from the list
            if (previousElement == NULL) {
                list.head = currentElement->next;
            } else {
                previousElement->next = currentElement->next;
            }

            free(currentElement);
        }

        previousElement = currentElement;
        currentElement = currentElement->next;
    }

    pthread_mutex_unlock(&list.lock);
}
```
