#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *array;
    int size;
    int capacity;
} DynamicArray;

DynamicArray array = {.size = 0, .capacity = 1};

void init() {
    pthread_mutex_init(&array.lock, NULL);
    array.array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array.lock);

    for (int i = 0; i < array.size; ++i) {
        if (array.array[i].RNTI == element.RNTI) {
            pthread_mutex_unlock(&array.lock);
            return -1; // Duplicate RNTI found, no addition made
        }
    }

    if (array.size >= array.capacity) {
        array.capacity *= 2;
        array.array = realloc(array.array, array.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    array.array[array.size++] = element;

    pthread_mutex_unlock(&array.lock);
    return 0; // Element added successfully
}

void removeElement(int RNTI) {
    pthread_mutex_lock(&array.lock);

    for (int i = 0; i < array.size; ++i) {
        if (array.array[i].RNTI == RNTI) {
            memmove(array.array + i, array.array + i + 1, (array.size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array.size;
            break;
        }
    }

    pthread_mutex_unlock(&array.lock);
}

void resetFlags() {
    pthread_mutex_lock(&array.lock);

    for (int i = 0; i < array.size; ++i) {
        array.array[i].CRC_INDICATION_REL8_TAG = 0; // Reset CRCFLAG to default value
    }

    pthread_mutex_unlock(&array.lock);
}
