    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES256GCM;

AES256GCM* aes256gcm_init(const char *password, int keylen, int ivlen) {
    AES256GCM *aes = malloc(sizeof(AES256GCM));
    if (!aes) return NULL;

