    if (!EVP_EncryptInit_ex(aes->ctx, EVP_aes_256_gcm(), NULL, aes->key, aes->iv)) {
        free(aes);
        return NULL;
    }

    return aes;
}

void aes256gcm_cleanup(AES256GCM *aes) {
    if (aes) {
        EVP_CIPHER_CTX_cleanup(aes->ctx);
        free(aes);
    }
}
