#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t lastCleanup = 0;
const time_t CLEANUP_INTERVAL = 60; // 1 minute

void* allocateAndInitialize(int tag, int rnti) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return NULL;

    newNode->data.RX_UE_INFORMATION_TAG = tag;
    newNode->data.RNTI = rnti;
    newNode->data.CRC_INDICATION_REL8_TAG = 0; // initialize to 0 for example
    newNode->data.CRCFLAG = rand() % 2; // randomly set CRCFLAG

    return newNode;
}

void addToList(int tag, int rnti) {
    pthread_mutex_lock(&lock);

    Node* node = allocateAndInitialize(tag, rnti);
    if (node == NULL) {
        // handle memory allocation failure
        pthread_mutex_unlock(&lock);
        return;
    }

    node->next = head;
    head = node;

    time_t currentTime = time(NULL);
    if (currentTime - lastCleanup >= CLEANUP_INTERVAL) {
        cleanList(); // remove old nodes and update lastCleanup
        lastCleanup = currentTime;
    }

    pthread_mutex_unlock(&lock);
}

void cleanList() {
    Node* node = head;
    while (node != NULL) {
        if (time(NULL) - node->data.RX_UE_INFORMATION_TAG >= CLEANUP_INTERVAL) {
            // remove node from list
            pthread_mutex_lock(&lock);

            Node* temp = node;
            node = node->next;
            free(temp);

            pthread_mutex_unlock(&lock);
        } else {
            node = node->next;
        }
    }
}
```
This code uses a simple linked list with a global lock for synchronization. It also includes a rudimentary cleanup mechanism that removes nodes older than the specified timeout after each addition to the list. 

