typedef struct UE_Context_Manager {
    LTE_RRC_UE_CONTEXT_T* contexts;
    size_t count;
    sem_t mutex;
    // other fields for performance metrics, error counts, etc.
} UE_Context_Manager;

// Initialize the context manager
void init_context_manager(UE_Context_Manager* mgr) {
    // initialize fields and allocate memory as needed
    sem_init(&mgr->mutex, 0, 1);
}

// Add a new UE context to the manager
int add_ue_context(UE_Context_Manager* mgr, LTE_RRC_UE_CONTEXT_T* ctx) {
    sem_wait(&mgr->mutex); // lock for concurrent access

    // validate and sanitize input
    if (!validate_ue_context(ctx)) {
        sem_post(&mgr->mutex); // unlock
        return -1; // invalid context
    }

    // resize the array to accommodate new context
    mgr->contexts = realloc(mgr->contexts, (mgr->count + 1) * sizeof(LTE_RRC_UE_CONTEXT_T));
    if (!mgr->contexts) {
        sem_post(&mgr->mutex); // unlock
        return -2; // allocation failed
    }

    mgr->contexts[mgr->count++] = *ctx; // add new context to array

    sem_post(&mgr->mutex); // unlock
    return 0; // success
}

// Remove a UE context from the manager
int remove_ue_context(UE_Context_Manager* mgr, LTE_RRC_UE_CONTEXT_T* ctx) {
    sem_wait(&mgr->mutex); // lock for concurrent access

    // find and remove context from array
    for (size_t i = 0; i < mgr->count; ++i) {
        if (compare_ue_contexts(ctx, &mgr->contexts[i])) {
            memmove(&mgr->contexts[i], &mgr->contexts[i + 1], (mgr->count - i - 1) * sizeof(LTE_RRC_UE_CONTEXT_T));
            mgr->contexts = realloc(mgr->contexts, --mgr->count * sizeof(LTE_RRC_UE_CONTEXT_T));

            sem_post(&mgr->mutex); // unlock
            return 0; // success
        }
    }

    sem_post(&mgr->mutex); // unlock
    return -1; // context not found
}
