        manager->capacity *= 2;
        manager->instances = realloc(manager->instances, sizeof(VNFInstance*) * manager->capacity);
    }

    manager->instances[manager->count++] = instance;

    pthread_mutex_unlock(&manager->lock);
}

void NFVManager_deployAllInstances(NFVManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        VNFInstance* instance = manager->instances[i];

        // initialize VNF descriptor and instantiation request
        instance->vnfDescriptor = initializeVNFD();
        instance->instantiationRequest = createInstantiationRequest();

        // deploy instance
        instance->deploymentStatus = deployInstance(instance);
    }
}
