#define MAX_CACHE_SIZE 10000
LTE_UESRVCC_STATE cache[MAX_CACHE_SIZE];
pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;
int cacheSize = 0;

void addToCache(LTE_UESRVCC_STATE state) {
    pthread_mutex_lock(&cacheLock);

    if (cacheSize < MAX_CACHE_SIZE) {
        cache[cacheSize++] = state;
    } else {
        // Cache is full, replace the oldest entry
        for(int i = 0; i < cacheSize - 1; ++i) {
            cache[i] = cache[i + 1];
        }
        cache[cacheSize - 1] = state;
    }

    pthread_mutex_unlock(&cacheLock);
}

LTE_UESRVCC_STATE* getFromCache(int UE_ID) {
    pthread_mutex_lock(&cacheLock);

    for (int i = 0; i < cacheSize; ++i) {
        if (cache[i].UE_ID == UE_ID) {
            pthread_mutex_unlock(&cacheLock);
            return &(cache[i]);
        }
    }

    pthread_mutex_unlock(&cacheLock);
    return NULL; // Not found in cache
}
