#include <chrono>
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <vector>

struct Event {
    std::string timestamp;
    int eventId;
    std::string sourceIp;
    std::string destIp;
    // Additional metadata fields...
};

class EventManager {
public:
    explicit EventManager(int maxEvents) : maxEvents_(maxEvents), nextEventId_(0) {}
    ~EventManager() = default;

    void addEvent(const std::string& sourceIp, const std::string& destIp) {
        std::lock_guard<std::mutex> lock(eventsMutex_);

        if (events_.size() >= maxEvents_) {
            // Handle error: maximum number of events reached.
            return;
        }

        Event event;
        event.timestamp = getCurrentTime();
        event.eventId = nextEventId_++;
        event.sourceIp = sourceIp;
        event.destIp = destIp;

        events_.insert({event.eventId, event});
    }

    void removeEvent(int eventId) {
        std::lock_guard<std::mutex> lock(eventsMutex_);
        events_.erase(eventId);
    }

    Event getEvent(int eventId) const {
        std::lock_guard<std::mutex> lock(eventsMutex_);
        auto it = events_.find(eventId);
        if (it != events_.end()) {
            return it->second;
        } else {
            // Handle error: event not found.
            return Event();
        }
    }

    std::vector<Event> getAllEvents() const {
        std::lock_guard<std::mutex> lock(eventsMutex_);

        std::vector<Event> allEvents;
        for (const auto& kv : events_) {
            allEvents.push_back(kv.second);
        }
        return allEvents;
    }

private:
    std::string getCurrentTime() const {
        auto now = std::chrono::system_clock::now();
        auto timeT = std::chrono::system_clock::to_time_t(now);
        return std::ctime(&timeT);
    }

    int maxEvents_;
    mutable std::mutex eventsMutex_;
    std::unordered_map<int, Event> events_;
    int nextEventId_;
};
```
