["Here is an example implementation in C using pthreads for thread safety and a hash table (glib) for efficient lookup by `PHY_TRANSPORT_CHANNEL_ID`. This code does not include error handling or memory cleanup, which would be necessary to make this production-ready:

```c
#include <pthread.h>
#include <stdlib.h>
#include <glib.h>

typedef struct {
    int PHY_TRANSPORT_CHANNEL_ID;
    size_t PDU_SIZE;
    void* data;
} LTE_PHY_RLC_PDU;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
GHashTable *table;

void init() {
    table = g_hash_table_new(g_direct_hash, g_direct_equal);
}

int addPDU(LTE_PHY_RLC_PDU* pdu) {
    pthread_mutex_lock(&lock);
    gpointer oldValue = g_hash_table_insert(table, GINT_TO_POINTER(pdu->PHY_TRANSPORT_CHANNEL_ID), pdu);
    if (oldValue) {
        // Update existing PDU
        LTE_PHY_RLC_PDU* oldPdu = (LTE_PHY_RLC_PDU*) oldValue;
        free(oldPdu->data);
        oldPdu->PDU_SIZE = pdu->PDU_SIZE;
        oldPdu->data = pdu->data;
    } else {
        // Add new PDU
        g_hash_table_insert(table, GINT_TO_POINTER(pdu->PHY_TRANSPORT_CHANNEL_ID), pdu);
    }
    pthread_mutex_unlock(&lock);
}

LTE_PHY_RLC_PDU* getPDU(int PHY_TRANSPORT_CHANNEL_ID) {
    pthread_mutex_lock(&lock);
    LTE_PHY_RLC_PDU* pdu = (LTE_PHY_RLC_PDU*) g_hash_table_lookup(table, GINT_TO_POINTER(PHY_TRANSPORT_CHANNEL_ID));
    pthread_mutex_unlock(&lock);
    return pdu;
}
