    array->capacity = initialCapacity;
    array->size = 0;
    array->headers = calloc(initialCapacity, sizeof(NICPHeader));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void addToArray(DynamicArray *array, NICPHeader header) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // Double the capacity when full
        array->headers = realloc(array->headers, 2 * array->capacity * sizeof(NICPHeader));
        array->capacity *= 2;
    }

    array->headers[array->size++] = header;

    pthread_mutex_unlock(&array->lock);
}

void destroyArray(DynamicArray *array) {
    free(array->headers);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
