['This is a complex task that requires a deep understanding of web development, databases, and system design principles. Here's an example of how you might structure your API using Node.js with Express.js for the server and MongoDB as the database. 

```javascript
const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');
const User = require('./models/User');
const Role = require('./models/Role');

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/myapp', { useNewUrlParser: true, useUnifiedTopology: true });

const app = express();
app.use(bodyParser.json());

// Create a new role
app.post('/roles', async (req, res) => {
  const role = new Role({ name: req.body.name });
  await role.save();
  res.send(role);
});

// Get all roles
app.get('/roles', async (req, res) => {
  const roles = await Role.find();
  res.send(roles);
});

// Update a role
app.put('/roles/:id', async (req, res) => {
  const role = await Role.findByIdAndUpdate(req.params.id, req.body, { new: true });
  if (!role) return res.status(404).send('Role not found');
  res.send(role);
});

// Delete a role
app.delete('/roles/:id', async (req, res) => {
  const role = await Role.findByIdAndDelete(req.params.id);
  if (!role) return res.status(404).send('Role not found');
  res.status(204).send();
});

// Get user counts per role
app.get('/roles/count', async (req, res) => {
  const roles = await Role.aggregate([{ $lookup: { from: 'users', localField: '_id', foreignField: 'role', as: 'user_count' } }, { $project: { name: 1, count: { $size: "$user_count" } } }]);
  res.send(roles);
});

// Batch update roles
app.put('/roles/batch', async (req, res) => {
  const bulkOps = req.body.map((item) => ({
    updateOne: {
      filter: { _id: item._id },
      update: item,
    }
  }));
  await Role.bulkWrite(bulkOps);
  res.send('Roles updated');
});

app.listen(3000, () => console.log('Server is running on port 3000'));
```

This code assumes you have a User and Role model defined in your MongoDB database. The `User` model should contain a reference to the role it belongs to. This example does not include any authentication or authorization, which would be necessary for a real-world application. 

