#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
size_t size = 0;
size_t capacity = 0;

void add_to_list(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        // Double the capacity each time we run out of space.
        size_t new_capacity = capacity == 0 ? 1 : capacity * 2;

        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, new_capacity * sizeof(*new_list));
        if (new_list == NULL) {
            // Log error and return.
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        list = new_list;
        capacity = new_capacity;
    }

    list[size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list[size].RNTI = RNTI;
    srand(time(NULL)); // Seed the random number generator.
    list[size].CRCFLAG = rand(); // Generate a random CRCFLAG.

    size++;

    pthread_mutex_unlock(&lock);
}
```
This code uses a mutex to ensure that only one thread can modify the list at a time, preventing race conditions and deadlocks. It also dynamically resizes the list using realloc when it runs out of space, minimizing the number of reallocations needed. The CRCFLAG is generated randomly for each PDU structure.

