typedef struct timestamp {
    time_t seconds;
    long nanoseconds;
} timestamp_t;

typedef struct record {
    int value;
    char name[65];
    timestamp_t timestamp;
} record_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generate_structures(long *offsets, int *keys, record_t **records, size_t maxSize) {
    pthread_mutex_lock(&lock);

    srand(time(NULL));
    long totalSize = 0;
    for (size_t i = 0; i < maxSize / sizeof(long); ++i) {
        offsets[i] = rand();
        totalSize += sizeof(long);

        if (totalSize > maxSize) {
            pthread_mutex_unlock(&lock);
            return -1; // Error: Max size exceeded.
        }
    }

    for (size_t i = 0; i < maxSize / sizeof(int); ++i) {
        keys[i] = rand();
        totalSize += sizeof(int);

        if (totalSize > maxSize) {
            pthread_mutex_unlock(&lock);
            return -1; // Error: Max size exceeded.
        }
    }

    for (size_t i = 0; i < maxSize / sizeof(record_t); ++i) {
        records[i] = malloc(sizeof(record_t));
        if (!records[i]) {
            pthread_mutex_unlock(&lock);
            return -1; // Error: Memory allocation failed.
        }

        records[i]->value = rand();
        strncpy(records[i]->name, "Record", sizeof(records[i]->name));
        clock_gettime(CLOCK_REALTIME, &records[i]->timestamp);
        totalSize += sizeof(record_t);

        if (totalSize > maxSize) {
            pthread_mutex_unlock(&lock);
            return -1; // Error: Max size exceeded.
        }
    }

    pthread_mutex_unlock(&lock);
    return 0; // Success.
}
```
