```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct timestamp {
    time_t seconds;
    int nanoseconds;
} timestamp;

typedef struct record {
    int value;
    char name[64];
    timestamp creationTime;
} record;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    long offset;
    int key;
    record data;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t size, size_t maxSize) {
    pthread_mutex_lock(&lock);

    static size_t totalAllocated = 0;
    if (totalAllocated + size > maxSize) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    void* memory = malloc(size);
    if (memory != NULL) {
        totalAllocated += size;
    }

    pthread_mutex_unlock(&lock);
    return memory;
}

void freeMemory(void* memory, size_t size) {
    pthread_mutex_lock(&lock);

    static size_t totalAllocated = 0;
    if (totalAllocated >= size) {
        totalAllocated -= size;
        free(memory);
    }

    pthread_mutex_unlock(&lock);
