```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int execution_time;
    int priority;
    int resource_requirements;
} TASK_REQUEST_T;

typedef struct Node {
    TASK_REQUEST_T task;
    struct Node* next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
    int size;
} Queue;

Queue queue = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void enqueue(TASK_REQUEST_T task) {
    Node* newNode = malloc(sizeof(Node));
    newNode->task = task;
    newNode->next = NULL;

    pthread_mutex_lock(&queue.lock);
    if (queue.tail != NULL) {
        queue.tail->next = newNode;
    } else {
        queue.head = newNode;
    }
    queue.tail = newNode;
    queue.size++;
    pthread_mutex_unlock(&queue.lock);
}

TASK_REQUEST_T dequeue() {
    pthread_mutex_lock(&queue.lock);
    if (queue.head == NULL) {
        // handle error: queue is empty
    } else {
        Node* oldHead = queue.head;
        TASK_REQUEST_T task = oldHead->task;
        queue.head = oldHead->next;
        free(oldHead);
        if (queue.head == NULL) {
            queue.tail = NULL;
        }
        queue.size--;
        pthread_mutex_unlock(&queue.lock);
        return task;
    }
}
```
This is a simple thread-safe queue implementation in C using mutex locks for synchronization. The `enqueue` function adds tasks to the end of the queue, and the `dequeue` function removes them from the front. 

