Record* createRecords(int size, int range) {
    if (size <= 0 || range <= 0) {
        printf("Invalid input: size and range must be positive integers.\n");
        return NULL;
    }

    // Allocate memory for the arrays
    long* offsets = malloc(size * sizeof(long));
    int* keys = calloc(size, sizeof(int));  // Initialize to zero
    Record* records = malloc(size * sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
