        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the arrays
    srand(time(NULL));  // Seed the random number generator
    for (int i = 0; i < size; i++) {
        int key;
        do {
            key = rand() % range + 1;  // Generate a random key within the specified range
        } while (keys[key] != 0);  // Ensure no duplicates

        keys[key] = 1;
        records[i].key = key;
    }

    for (int i = 0; i < size; i++) {
        long offset = rand() % range + 1;  // Generate a random offset within the specified range
        records[i].offset = offset;

        if (offset <= threshold) {  // Set status based on offset
