void init_frame_array() {
    frame_array.frames = malloc(sizeof(NFAPI_RX_FRAME_PDU_T) * frame_array.capacity);
}

void add_frame(NFAPI_RX_FRAME_PDU_T* frame) {
    if (frame_array.count == frame_array.capacity) {
        // resize array
        frame_array.capacity *= 2;
        frame_array.frames = realloc(frame_array.frames, sizeof(NFAPI_RX_FRAME_PDU_T) * frame_array.capacity);
    }

    frame_array.frames[frame_array.count++] = *frame;
}

void remove_frame(int measurement_tag) {
    for (size_t i = 0; i < frame_array.count; ++i) {
        if (frame_array.frames[i].measurement_tag == measurement_tag) {
            // move last element to this position and decrement count
            frame_array.frames[i] = frame_array.frames[--frame_array.count];
            return;
        }
    }
}

NFAPI_RX_FRAME_PDU_T* get_frame(int measurement_tag) {
    for (size_t i = 0; i < frame_array.count; ++i) {
        if (frame_array.frames[i].measurement_tag == measurement_tag) {
            return &frame_array.frames[i];
        }
    }

