    struct Node* next;
} Node;

Node* filter_frames(int (*filter)(NFAPI_RX_FRAME_PDU_T*)) {
    Node dummy = {NULL, NULL}, *tail = &dummy;

    for (size_t i = 0; i < frame_array.count; ++i) {
        if (filter(&frame_array.frames[i])) {
            tail->next = malloc(sizeof(Node));
            tail = tail->next;
            tail->frame = &frame_array.frames[i];
            tail->next = NULL;
        }
    }

    Node* result = dummy.next;
    free(&dummy); // don't leak memory
    return result;
}
