    strncpy(newNode->nic_conf.name, name, 31);
    newNode->nic_conf.name[31] = '\0';

    strncpy(newNode->nic_conf.mac, mac, 17);
    newNode->nic_conf.mac[17] = '\0';

    // Check for IP conflicts
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->nic_conf.ip, ip) == 0) {
            free(newNode);
            pthread_mutex_unlock(&lock);
            return -2; // IP conflict
        }
        current = current->next;
    }

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}
