#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_CONTEXT_TAG;
    int RRC_CONNECTION_TAG;
    void* buffer;
} NFAPI_RX_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_RX_PDU_T* data;
} NfarPduList;

int initializeNfarPduList(NfarPduList* list, size_t initialCapacity) {
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        return -1;  // failed to initialize lock
    }

    list->capacity = initialCapacity;
    list->size = 0;
    list->data = malloc(initialCapacity * sizeof(NFAPI_RX_PDU_T));
    if (list->data == NULL) {
        return -2;  // failed to allocate memory
    }

    return 0;  // success
}

int addNfarPdu(NfarPduList* list, NFAPI_RX_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_RX_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_RX_PDU_T));
        if (newData == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;  // failed to allocate memory
        }

        list->capacity = newCapacity;
        list->data = newData;
    }

    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);

    return 0;  // success
}
```
