```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct TrafficFlowConfig {
    int flowId;
    char destinationAddress[256];
    unsigned short maxPacketSize;
} TrafficFlowConfig;

typedef struct Node {
    TrafficFlowConfig config;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int validate(TrafficFlowConfig config) {
    if (config.maxPacketSize > 65535) return 0;
    Node* current = head;
    while (current != NULL) {
        if (current->config.flowId == config.flowId) return 0;
        current = current->next;
    }
    return 1;
}

int add(TrafficFlowConfig config) {
    pthread_mutex_lock(&lock);
    if (!validate(config)) {
        pthread_mutex_unlock(&lock);
        return -1; // Error code for invalid configuration
    }
    Node* newNode = malloc(sizeof(Node));
    newNode->config = config;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
    return 0; // Success code
}

int update(TrafficFlowConfig config) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        if (current->config.flowId == config.flowId) {
            current->config = config;
            pthread_mutex_unlock(&lock);
            return 0; // Success code
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return -1; // Error code for configuration not found
}

int delete(int flowId) {
    pthread_mutex_lock(&lock);
    Node* prev = NULL;
    Node* current = head;
    while (current != NULL) {
        if (current->config.flowId == flowId) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&lock);
            return 0; // Success code
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return -1; // Error code for configuration not found
}
```
