void addOrUpdateTrafficFlowConfig(int flowId, const char* destinationAddress, size_t maxPacketSize) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numConfigs; ++i) {
        if (configs[i]->flowId == flowId) {
            free(configs[i]->destinationAddress);
            configs[i]->destinationAddress = strdup(destinationAddress);
            configs[i]->maxPacketSize = maxPacketSize;
            pthread_mutex_unlock(&lock);
            return;
        }
