    newConfig->flowId = flowId;
    newConfig->destinationAddress = strdup(destinationAddress);
    newConfig->maxPacketSize = maxPacketSize;

    configs[numConfigs++] = newConfig;

    pthread_mutex_unlock(&lock);
}

TrafficFlowConfig* getTrafficFlowConfig(int flowId) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numConfigs; ++i) {
        if (configs[i]->flowId == flowId) {
            TrafficFlowConfig* result = malloc(sizeof(TrafficFlowConfig));
            memcpy(result, configs[i], sizeof(TrafficFlowConfig));
            pthread_mutex_unlock(&lock);
            return result;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

HashFunctionInfo* getAvailableHashFunctions() {
    OpenSSL_add_all_digests();

    HashFunctionInfo* available = malloc(EVP_MD_type(0) * sizeof(HashFunctionInfo));
    int count = 0;

    for (int i = 0; i < EVP_MD_type(i); ++i) {
        const EVP_MD *md = EVP_get_digestbynid(i);

        if (md != NULL) {
            available[count].type = md;
            available[count].hash = EVP_DigestInit_ex; // or similar function depending on OpenSSL version
            ++count;
        }
    }

    return available;
}
