typedef struct {
    int type; // PUSCH or PUCCH
} TransportChannel;

typedef struct {
    int UE_ID;
    int RRC_Connected_Mode;
    TransportChannel* TransportChannelList;
    size_t listSize;
    pthread_mutex_t lock;
} NR_Uplink_TransportChannelInfo;

NR_Uplink_TransportChannelInfo* createStructure(int UE_ID, int RRC_Connected_Mode) {
    if (UE_ID < 0 || RRC_Connected_Mode < 0) {
        printf("Invalid UE_ID or RRC_Connected_Mode\n");
        return NULL;
    }

    NR_Uplink_TransportChannelInfo* info = malloc(sizeof(NR_Uplink_TransportChannelInfo));
    if (info == NULL) {
        printf("Failed to allocate memory for structure\n");
        return NULL;
    }

    info->UE_ID = UE_ID;
    info->RRC_Connected_Mode = RRC_Connected_Mode;
    info->TransportChannelList = malloc(1000 * sizeof(TransportChannel));
    if (info->TransportChannelList == NULL) {
        printf("Failed to allocate memory for TransportChannelList\n");
        free(info);
        return NULL;
    }

    info->listSize = 0;
    pthread_mutex_init(&info->lock, NULL);

    return info;
}

void addTransportChannel(NR_Uplink_TransportChannelInfo* info, TransportChannel channel) {
    if (info == NULL || info->listSize >= 1000) {
        printf("Invalid structure or list is full\n");
        return;
    }

    pthread_mutex_lock(&info->lock);

    // Validate the channel before adding it to the list
    if (channel.type != PUSCH && channel.type != PUCCH) {
        printf("Invalid TransportChannel type\n");
        return;
    }

    info->TransportChannelList[info->listSize++] = channel;

    pthread_mutex_unlock(&info->lock);
}
