void insert(NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&lock);

    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }

    new_node->data = value;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void delete(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head, *prev = NULL;
    while (temp != NULL && atomic_load(&temp->data.RNTI) != RNTI) {
        prev = temp;
        temp = temp->next;
