['Here is an example implementation of such a task scheduler in C. This code uses a linked list for simplicity and efficiency, but other data structures could also be used depending on the specific requirements. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <time.h>

typedef struct Task {
    int id;
    char* name;
    struct timeval deadline;
    int priority;
    struct Task *next;
} Task;

Task *head = NULL;
int taskCount = 0;

// Function to add a new task
void add_task(char* name, int priority) {
    Task *newTask = (Task*) malloc(sizeof(Task));

    if(newTask == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    newTask->id = taskCount++;
    newTask->name = strdup(name);
    gettimeofday(&(newTask->deadline), NULL);
    newTask->priority = priority;
    newTask->next = head;

    // Update the head of the list
    head = newTask;
}

// Function to update a task's deadline
void update_task(int id, struct timeval newDeadline) {
    Task *current = head;

    while (current != NULL) {
        if (current->id == id) {
            current->deadline = newDeadline;
            return;
        }

        current = current->next;
    }

    printf("Task with ID %d not found.\n", id);
}

// Function to remove a task
void remove_task(int id) {
    Task *temp = head, *prev;

    // If the head itself holds the key to be deleted
    if (temp != NULL && temp->id == id) {
        head = temp->next; 
        free(temp);
        return;
    }

    // Search for the key to be deleted, keep track of the previous node as we need to change 'prev->next'
    while (temp != NULL && temp->id != id) {
        prev = temp;
        temp = temp->next;
    }

    // If the key was not present in linked list
    if (temp == NULL) return;

    // Unlink the node from linked list
    prev->next = temp->next;

    free(temp);  // Free memory
}

// Function to clear all tasks and free associated memory
void clear_tasks() {
    Task *current = head, *next;

    while (current != NULL) {
        next = current->next;
        free(current->name);
        free(current);
        current = next;
    }

    head = NULL;
}
```
This code provides a basic implementation of the task scheduler. It includes functions for adding, updating, and removing tasks, as well as clearing all tasks from memory when necessary. The `add_task` function generates a unique ID for each task by incrementing a global counter. The deadline is set to the current time plus a random duration between 1 and 1000 seconds.
']

