#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_CACHE 1024

typedef struct {
    char hostname[NI_MAXHOST];
    time_t timestamp;
} CacheEntry;

CacheEntry cache[MAX_CACHE];
int cacheSize = 0;

void logEvent(const char* event) {
    // Implement logging here. This is a placeholder and should be replaced with actual logging code.
    printf("Log: %s\n", event);
}

u_char* resolveHostname(const char* hostname, int af) {
    static u_char ip[INET6_ADDRSTRLEN];
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = af; // AF_UNSPEC for both IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    int i;
    for(i = 0; i < cacheSize; i++) {
        if(!strcmp(cache[i].hostname, hostname)) {
            logEvent("Cache hit");
            break;
        }
    }

    if(i == cacheSize) { // Not in cache
        int status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status != 0) {
            logEvent("DNS resolution failed");
            return NULL;
        }

        if(cacheSize < MAX_CACHE) { // Add to cache
            strcpy(cache[cacheSize].hostname, hostname);
            time(&cache[cacheSize].timestamp);
            cacheSize++;
        } else { // Replace oldest entry in cache
            int oldest = 0;
            for(i = 1; i < MAX_CACHE; i++) {
                if(difftime(cache[oldest].timestamp, cache[i].timestamp) > 0) {
                    oldest = i;
                }
            }
            strcpy(cache[oldest].hostname, hostname);
            time(&cache[oldest].timestamp);
        }

        if (af == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
            void *addr = &(ipv4->sin_addr);
            inet_ntop(res->ai_family, addr, ip, sizeof ip);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
            void *addr = &(ipv6->sin6_addr);
            inet_ntop(res->ai_family, addr, ip, sizeof ip);
        }

        freeaddrinfo(res); // Remember to free the linked list
    }

    return ip;
}
```
This code uses a simple cache mechanism with a fixed size. When the cache is full and a new hostname needs to be resolved, it replaces the oldest entry in the cache (the one that was added first). This ensures that the cache does not grow without bound. 

Please note that this is a basic implementation and may need further optimization or modification based on your specific requirements. For example, you might want to use a more efficient data structure for the cache, such as a hash table or a balanced binary search tree. You also might want to add error handling code for when the `getaddrinfo` function fails.
