```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int prb_index;
    char modulation[20]; // assuming a max length for modulation scheme name
    float rsp;
} LTEChannel;

typedef struct {
    LTEChannel *channels;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ChannelList;

void init_channel(LTEChannel *channel, int prb_index, const char *modulation, float rsp) {
    channel->prb_index = prb_index;
    strncpy(channel->modulation, modulation, sizeof(channel->modulation));
    channel->rsp = rsp;
}

void init_list(ChannelList *list, size_t initial_capacity) {
    list->channels = malloc(initial_capacity * sizeof(LTEChannel));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void add_channel(ChannelList *list, LTEChannel channel) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Double the capacity when full
        list->capacity *= 2;
        list->channels = realloc(list->channels, list->capacity * sizeof(LTEChannel));
    }

    list->channels[list->size++] = channel;

    pthread_mutex_unlock(&list->lock);
}

void free_list(ChannelList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->channels);
}
```
This code uses a dynamic array to store the channels. When the array is full, it doubles its size using `realloc`. The list operations are protected by a mutex for thread safety. 

Please note that this is a basic implementation and does not include error handling or data source integration. For production-level code, you would need to add appropriate error checking and handle potential synchronization issues with the external data source. Also, depending on your specific requirements, you might want to use a more efficient data structure for storing channels (e.g., a hash table) or consider using a library that provides such functionality out of the box.
