// Memory pool for efficient memory allocation
#define MAX_POOL_SIZE 1024 * 1024 // 1MB
static char memoryPool[MAX_POOL_SIZE];
static atomic_size_t offset = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Error handling callback function prototype
typedef void (*ErrorCallback)(const char* errorMessage);

void* allocateMemory(size_t size) {
    pthread_mutex_lock(&mutex);

    if (offset + size > MAX_POOL_SIZE) {
        // Handle out of memory scenario here
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    void* block = &memoryPool[atomic_fetch_add(&offset, size)];

    pthread_mutex_unlock(&mutex);

    return block;
}

DataPacket* generatePackets(size_t packetCount, size_t payloadSize, ErrorCallback errorCallback) {
    DataPacket* packets = malloc(packetCount * sizeof(DataPacket));
