        newNode->RNTI = rand() % 1000; // Assuming valid range is 0 to 999
        newNode->CRC_INDICATION_REL8_TAG = rand();
        newNode->TIMESTAMP = time(NULL);

        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = tail = newNode;
            head->prev = NULL;
            tail->next = NULL;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
            tail->next = NULL;
        }
        pthread_mutex_unlock(&lock);
    }

    return head;
}

void printList(NFAPI_CRC_INDICATION_PDU_T* node) {
