```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Event {
    time_t timestamp;
    char* type;
    char* payload;
    struct Event *next;
} Event;

Event* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_event(char* type, char* payload) {
    pthread_mutex_lock(&lock);

    Event *newEvent = malloc(sizeof(Event));
    newEvent->timestamp = time(NULL);
    newEvent->type = strdup(type);
    newEvent->payload = strdup(payload);
    newEvent->next = head;

    head = newEvent;

    pthread_mutex_unlock(&lock);
}

void remove_event(char* type) {
    pthread_mutex_lock(&lock);

    Event *current = head;
    Event *previous = NULL;

    while (current != NULL) {
        if (strcmp(current->type, type) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current->type);
            free(current->payload);
            free(current);
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void iterate_events() {
    pthread_mutex_lock(&lock);

    Event *current = head;

    while (current != NULL) {
        printf("Timestamp: %ld, Type: %s, Payload: %s\n", current->timestamp, current->type, current->payload);

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
