["Here is a basic implementation of the AES-256-GCM cipher in C using OpenSSL library. This code does not include all the functionalities you mentioned such as KMS integration, nonce generation and storage for preventing replay attacks, error handling and logging, etc. 

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

#define IV_LEN 12 // Default IV length for AES-GCM is 96 bits (12 bytes)
#define TAG_LEN 16 // Authentication tag length for AES-GCM is 128 bits (16 bytes)

int aes_gcm_encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key,
                    unsigned char *iv, unsigned char *ciphertext,
                    unsigned char *tag) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len = 0;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv))
        handleErrors();

    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();
    ciphertext_len = len;

    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) 
        handleErrors();
    ciphertext_len += len;

    /* Get the tag */
    if(1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, tag))
        handleErrors();

    /* Clean up */
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

int aes_gcm_decrypt(unsigned char *ciphertext, int ciphertext_len, unsigned char *key,
                    unsigned char *iv, unsigned char *tag, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len = 0;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if(1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv))
        handleErrors();

    if(1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        handleErrors();
    plaintext_len = len;

    /* Set expected tag value */
    if(1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, TAG_LEN, tag))
        handleErrors();

    /* Finalise the decryption. A negative return value indicates an error, but
     * we'll let the finalise operation finish cleanly at this point to avoid
     * leaking possible timing information via a fault message result */
    if(1 == EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        /* Success */
        plaintext_len += len;
    } else {
        /* Verify failed */
        handleErrors();
    }

    /* Clean up */
    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}
```
