typedef struct {
    int UE_ID;
    int Cell_ID;
} LTE_UERadioResourceManagerConfig;

typedef struct {
    int QoS_class;
    int priority;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} RadioBearerConfig;

typedef struct {
    LTE_UERadioResourceManagerConfig config;
    RadioBearerConfig* bearers;
    size_t num_bearers;
} UE_Info;

typedef struct {
    UE_Info* list;
    size_t capacity;
    size_t size;
} LTE_UERadioResourceManager;

LTE_UERadioResourceManager create_manager(size_t initial_capacity) {
    LTE_UERadioResourceManager manager;
    manager.list = malloc(initial_capacity * sizeof(UE_Info));
    manager.capacity = initial_capacity;
    manager.size = 0;
    return manager;
}

void add_ue(LTE_UERadioResourceManager* manager, LTE_UERadioResourceManagerConfig config) {
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->list = realloc(manager->list, manager->capacity * sizeof(UE_Info));
    }

    UE_Info new_ue;
    new_ue.config = config;
    new_ue.bearers = NULL;
    new_ue.num_bearers = 0;

    manager->list[manager->size] = new_ue;
    manager->size++;
}

void add_bearer(LTE_UERadioResourceManager* manager, int ue_index, RadioBearerConfig bearer) {
    UE_Info* ue = &manager->list[ue_index];

    if (ue->num_bearers == 0) {
        ue->bearers = malloc(sizeof(RadioBearerConfig));
    } else {
        ue->bearers = realloc(ue->bearers, (ue->num_bearers + 1) * sizeof(RadioBearerConfig));
    }

    ue->bearers[ue->num_bearers] = bearer;
    ue->num_bearers++;
}
```
