    pthread_mutex_init(&array->lock, NULL);
}

void insertEvent(EventArray* array, NetworkEvent* event) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        array->capacity = array->capacity ? array->capacity * 2 : 1;
        array->events = realloc(array->events, sizeof(NetworkEvent*) * array->capacity);
    }

    array->events[array->count++] = event;

    pthread_mutex_unlock(&array->lock);
}

void deleteEvent(EventArray* array, size_t index) {
    pthread_mutex_lock(&array->lock);

    if (index < array->count) {
        free(array->events[index]->payload);
        free(array->events[index]);

        for (size_t i = index; i < array->count - 1; ++i) {
            array->events[i] = array->events[i + 1];
        }

        --array->count;
    }

    pthread_mutex_unlock(&array->lock);
}

NetworkEvent* getEvent(EventArray* array, size_t index) {
    NetworkEvent* event = NULL;

    pthread_mutex_lock(&array->lock);

    if (index < array->count) {
        event = array->events[index];
    }

    pthread_mutex_unlock(&array->lock);

    return event;
}

void serializeArray(EventArray* array, const char* filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);

    if (fd == -1) {
        perror("open");
        return;
    }

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (write(fd, &array->events[i]->timestamp, sizeof(time_t)) == -1 ||
            write(fd, &array->events[i]->eventType, sizeof(int)) == -1 ||
            write(fd, array->events[i]->payload, strlen((char*)array->events[i]->payload) + 1) == -1) {

            perror("write");
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);

    close(fd);
}
```
This code provides a basic implementation of an array that manages `NetworkEvent` structures. It uses a mutex to ensure thread safety, and it handles memory allocation and deallocation properly. The serialization function writes each event's timestamp, type, and payload to disk in binary format. 

