['Here is a basic implementation of a linked list in C that meets your requirements. It includes error checking, thread safety using pthread mutexes, and optional metadata fields. 

```c
#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_MESSAGE_PDU_T {
    int UE_ID;
    int PREAMBLE_TYPE;
    float SNR;
    void* metadata; // Optional metadata field
    struct NFAPI_MESSAGE_PDU_T *next;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    NFAPI_MESSAGE_PDU_T *head;
    pthread_mutex_t lock;
} List;

List* createList() {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyList(List *list) {
    NFAPI_MESSAGE_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_MESSAGE_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertItem(List *list, NFAPI_MESSAGE_PDU_T *item) {
    if (item == NULL || item->UE_ID < 0 || item->PREAMBLE_TYPE < 0 || item->SNR <= 0.0f) return -1; // Error checking

    pthread_mutex_lock(&list->lock);

    NFAPI_MESSAGE_PDU_T *newItem = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
    if (newItem == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error checking
    }

    newItem->UE_ID = item->UE_ID;
    newItem->PREAMBLE_TYPE = item->PREAMBLE_TYPE;
    newItem->SNR = item->SNR;
    newItem->metadata = item->metadata; // Copy metadata field

    newItem->next = list->head;
    list->head = newItem;

    pthread_mutex_unlock(&list->lock);
    return 0;
}
```
This code creates a linked list of NFAPI_MESSAGE_PDU_T structures. Each structure contains an UE_ID, PREAMBLE_TYPE, and SNR value. The insertItem function checks that these values are valid before adding them to the list. It also uses a mutex to ensure thread safety.

