typedef struct {
    char* name;
    void* handle;
} Library;

Library libraries[10];
int library_count = 0;

void load_library(char* path) {
    void *handle = dlopen(path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        return;
    }

    libraries[library_count].name = path;
    libraries[library_count].handle = handle;
    library_count++;
}

void* get_symbol(Library lib, char* symbol) {
    void *func = dlsym(lib.handle, symbol);
    if (!func) {
        fprintf(stderr, "dlsym failed: %s\n", dlerror());
    }

    return func;
}
