['Here is a simplified version of what your code might look like in Java. This example does not cover all the points you mentioned due to complexity but it gives an idea about how you can approach this problem. 

```java
import java.io.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.*;
import org.slf4j.*;

public class FileHasher {
    private static final Logger logger = LoggerFactory.getLogger(FileHasher.class);
    private ExecutorService executor;

    public FileHasher() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    public String processFiles(List<String> filePaths) throws InterruptedException, ExecutionException {
        List<Future<String>> futures = new ArrayList<>();

        for (String path : filePaths) {
            Future<String> future = executor.submit(() -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    FileInputStream fis = new FileInputStream(path);

                    byte[] dataBytes = new byte[1024];

                    int nread = 0; 

                    while ((nread = fis.read(dataBytes)) != -1) {
                        md.update(dataBytes, 0, nread);
                    };

                    fis.close();

                    byte[] mdbytes = md.digest();

                    //convert the byte to hex format
                    StringBuffer sb = new StringBuffer();
                    for (int i = 0; i < mdbytes.length; i++) {
                        sb.append(Integer.toString((mdbytes[i] & 0xff) + 0x100, 16).substring(1));
                    }

                    logger.info("Successfully hashed file: " + path);
                    return sb.toString();
                } catch (Exception e) {
                    logger.error("Failed to hash file: " + path, e);
                    return null;
                }
            });

            futures.add(future);
        }

        executor.shutdown();

        StringBuilder result = new StringBuilder();
        for (Future<String> future : futures) {
            String hash = future.get();
            if (hash != null) {
                result.append(hash).append(",");
            }
        }

        return result.toString();
    }
}
```

This code uses a thread pool to concurrently process files, and Apache Commons Codec for MD5 hashing. It also uses SLF4J for logging. 

