#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Message {
    int id;
    time_t timestamp;
    size_t payloadSize;
} Message;

typedef struct Node {
    Message* message;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void addMessage(int id, time_t timestamp, size_t payloadSize) {
    pthread_mutex_lock(&lock);

    Message* message = (Message*)malloc(sizeof(Message));
    message->id = id;
    message->timestamp = timestamp;
    message->payloadSize = payloadSize;

    Node* node = (Node*)malloc(sizeof(Node));
    node->message = message;
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
}

void cleanupExpiredMessages(time_t timeout) {
    time_t expirationTime = time(NULL) - timeout;

    pthread_mutex_lock(&lock);

    Node* node = head;
    Node* prevNode = NULL;
    while (node != NULL) {
        if (node->message->timestamp < expirationTime) {
            if (prevNode == NULL) {
                head = node->next;
            } else {
                prevNode->next = node->next;
            }

            free(node->message);
            Node* temp = node;
            node = node->next;
            free(temp);
        } else {
            prevNode = node;
            node = node->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
