NFAPI_CRC_INDICATION_PDU_T* generateRandomNfadpIndications(int N, nfapiConfig config, FILE* logFile) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (indications == NULL) {
        fprintf(logFile, "Failed to allocate memory for indications\n");
        return NULL;
    }

    // Generate random strings and hashes
    unsigned char hash[SHA256_DIGEST_LENGTH];
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";

    for (int i = 0; i < N; ++i) {
        // Generate random string
        indications[i].random_str = malloc(config.stringLength + 1);

        if (indications[i].random_str == NULL) {
            fprintf(logFile, "Failed to allocate memory for random string\n");
            return NULL;
        }

        for (int j = 0; j < config.stringLength; ++j) {
            int key = rand() % (int)(sizeof(charset) - 1);
            indications[i].random_str[j] = charset[key];
        }

        indications[i].random_str[config.stringLength] = '\0'; // Null-terminate the string

        // Generate hash of random string
        SHA256((unsigned char*)indications[i].random_str, strlen(indications[i].random_str), hash);
        indications[i].hash = malloc(SHA256_DIGEST_LENGTH);

        if (indications[i].hash == NULL) {
