['This is a complex task that requires a deep understanding of data structures, algorithms, system programming, and network protocols. Here's an outline of how you might approach this problem using C. Note that the actual implementation would be much more complex due to the requirements mentioned above. 

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;
Node* tail = NULL;
int size = 0;

// Hash map for fast lookups
#define MAX_HASH 10007 // a prime number
typedef struct {
    int RNTI;
    Node* node;
} HashMapEntry;
HashMapEntry hashmap[MAX_HASH];

int hash(int key) {
    return abs(key % MAX_HASH);
}

void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    // Check for duplicate RNTI values
    int index = hash(data.RNTI);
    while (hashmap[index].node != NULL && hashmap[index].RNTI != -1) {
        if (hashmap[index].RNTI == data.RNTI) {
            printf("Duplicate RNTI value found, ignoring\n");
            return;
        }
        index = (index + 1) % MAX_HASH;
    }

    Node* newNode = malloc(sizeof(Node));
    assert(newNode != NULL); // handle allocation failure
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = tail;

    if (tail == NULL) {
        head = newNode;
    } else {
        tail->next = newNode;
    }

    tail = newNode;
    size++;

    // Add to hash map
    hashmap[index].RNTI = data.RNTI;
    hashmap[index].node = newNode;
}

void removeNode(int RNTI) {
    int index = hash(RNTI);
    while (hashmap[index].node != NULL && hashmap[index].RNTI != -1) {
        if (hashmap[index].RNTI == RNTI) {
            Node* nodeToRemove = hashmap[index].node;

            // Update links in list
            if (nodeToRemove->prev != NULL) {
                nodeToRemove->prev->next = nodeToRemove->next;
            } else {
                head = nodeToRemove->next;
            }
            if (nodeToRemove->next != NULL) {
                nodeToRemove->next->prev = nodeToRemove->prev;
            } else {
                tail = nodeToRemove->prev;
            }

            // Remove from hash map
            hashmap[index].RNTI = -1;
            free(nodeToRemove);
            size--;
            return;
        }
        index = (index + 1) % MAX_HASH;
    }
}
```
