void addRRCMessage(int ueId, RRC_Message* message) {
    pthread_mutex_lock(&contextsLock);

    // Find or create the UE context for this UE ID
    UE_Context* context = NULL;
    for (size_t i = 0; i < numContexts; ++i) {
        if (contexts[i]->ueId == ueId) {
            context = contexts[i];
            break;
        }
    }

    if (!context) {
        // Create a new UE context for this UE ID
        context = malloc(sizeof(UE_Context));
        context->ueId = ueId;
        pthread_mutex_init(&context->lock, NULL);
        contexts = realloc(contexts, (numContexts + 1) * sizeof(UE_Context*));
        contexts[numContexts++] = context;
    }

    // Add the RRC message to this UE context
    pthread_mutex_lock(&context->lock);
    context->messages = realloc(context->messages, (context->numMessages + 1) * sizeof(RRC_Message));
    context->messages[context->numMessages++] = message;

    // Update the last activity time for this UE context
    context->lastActivityTime = time(NULL);

    pthread_mutex_unlock(&context->lock);
    pthread_mutex_unlock(&contextsLock);
}
