['Here is an example of how you might implement such a system in C using pthread mutexes for thread safety and a hash map for efficient lookups. This code does not include message prioritization or queuing mechanisms, as these would significantly complicate the implementation without providing significant performance benefits in a high-traffic environment:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct Message {
    int id;
    int type;
    char* destination;
    time_t timestamp;
    size_t payloadSize;
} Message;

typedef struct MessageList {
    pthread_mutex_t lock;
    Message** messages;
    int maxMessages;
    int currentMessages;
    int minType;
    int maxType;
    char** allowedDestinations;
    size_t numAllowedDestinations;
} MessageList;

MessageList* createMessageList(int maxMessages, int minType, int maxType, char** allowedDestinations, size_t numAllowedDestinations) {
    MessageList* list = malloc(sizeof(MessageList));
    pthread_mutex_init(&list->lock, NULL);
    list->messages = calloc(maxMessages, sizeof(Message*));
    list->maxMessages = maxMessages;
    list->currentMessages = 0;
    list->minType = minType;
    list->maxType = maxType;
    list->allowedDestinations = allowedDestinations;
    list->numAllowedDestinations = numAllowedDestinations;
    return list;
}

void addMessage(MessageList* list, Message* message) {
    assert(message->type >= list->minType && message->type <= list->maxType);

    for (size_t i = 0; i < list->numAllowedDestinations; ++i) {
        if (strcmp(list->allowedDestinations[i], message->destination) == 0) {
            goto destinationFound;
        }
    }

    fprintf(stderr, "Unsupported destination: %s\n", message->destination);
    free(message);
    return;

destinationFound:
    pthread_mutex_lock(&list->lock);

    if (list->currentMessages >= list->maxMessages) {
        fprintf(stderr, "Maximum number of messages reached\n");
        free(message);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->messages[list->currentMessages++] = message;

    pthread_mutex_unlock(&list->lock);
}
```
This code uses a mutex to ensure that only one thread can modify the message list at a time, which reduces lock contention and allows for efficient concurrency. It also checks if the maximum number of messages has been reached before adding a new message, reducing the impact on system performance when the workload is heavy.

Please note that this code does not include error handling for invalid inputs or memory management for payloads, which would be necessary in a production environment. Also, it assumes that the `destination` field of each `Message` points to a string literal, which may not be safe if the strings are modified after they have been added to the list.
']

