    RRC_Message** messages;
    int msgCount;
    pthread_mutex_t lock;
} UEContext;

UEContext** contexts;
int maxContexts = 100; // default maximum number of contexts
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void init() {
    contexts = malloc(sizeof(UEContext*) * maxContexts);
}

int addContext(int ueId) {
    pthread_mutex_lock(&globalLock);
    for (int i = 0; i < maxContexts; i++) {
        if (contexts[i] == NULL) {
            contexts[i] = malloc(sizeof(UEContext));
            contexts[i]->ueId = ueId;
            contexts[i]->messages = NULL;
            contexts[i]->msgCount = 0;
            pthread_mutex_init(&contexts[i]->lock, NULL);
            pthread_mutex_unlock(&globalLock);
            return i; // return the index of the added context
        }
    }
    pthread_mutex_unlock(&globalLock);
    return -1; // no space left for new contexts
}

void deleteContext(int index) {
    pthread_mutex_lock(&contexts[index]->lock);
    free(contexts[index]);
    contexts[index] = NULL;
    pthread_mutex_unlock(&contexts[index]->lock);
}

void appendRRCMessage(int index, RRC_Message* msg) {
    pthread_mutex_lock(&contexts[index]->lock);
    contexts[index]->messages = realloc(contexts[index]->messages, sizeof(RRC_Message*) * (contexts[index]->msgCount + 1));
    contexts[index]->messages[contexts[index]->msgCount] = msg;
    contexts[index]->msgCount++;
    pthread_mutex_unlock(&contexts[index]->lock);
}
