#define MAX_PDU_SESSIONS 1024
typedef struct HashTable {
    PDU_SESSION_CONTEXT_T* table[MAX_PDU_SESSIONS];
} HashTable;

HashTable hashTable;
int nextId = 0;

void initHashTable() {
    memset(hashTable.table, 0, sizeof(hashTable.table));
}

int getNextUniqueId() {
    while (hashTable.table[nextId] != NULL) {
        if (++nextId >= MAX_PDU_SESSIONS) nextId = 0; // wrap around
    }
    return nextId;
}

void addSession(int SEID, int QOS_PROFILE_ID) {
    PDU_SESSION_CONTEXT_T* session = malloc(sizeof(PDU_SESSION_CONTEXT_T));
    if (session == NULL) {
        // handle error...
        return;
    }

    int id = getNextUniqueId();
    session->PDU_SESSION_ID = id;
    session->SEID = SEID;
    session->QOS_PROFILE_ID = QOS_PROFILE_ID;
    // populate other parameters...

    hashTable.table[id] = session;
}
