    struct Node *next, *prev;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addEvent(NFAPI_CRC_INDICATION_PDU_T event) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node*) malloc(sizeof(Node));
    newNode->data = event;
    newNode->next = head;
    newNode->prev = NULL;

    if (head != NULL) {
        head->prev = newNode;
    }

    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeEvent(int (*condition)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        if (condition(current->data)) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                head = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            }

            free(current);
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void iterateEvents(void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This code uses a doubly linked list to store the events. It also uses a mutex for thread safety. The `addEvent` function adds an event at the beginning of the list, and the `removeEvent` function removes all events that satisfy a given condition. The `iterateEvents` function iterates over all events in reverse chronological order (from newest to oldest).

