    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int maxMemoryUsage = 1024 * 1024; // 1MB
int compactionThreshold = 60 * 1000; // 1 minute in milliseconds

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (!newNode) return; // Out of memory

    newNode->data = data;
    newNode->next = NULL;

    if (!head) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            if (current->data.RNTI == data.RNTI) {
                // Recycle the oldest unused RNTI from the list
                free(newNode);
                return;
            }
            current = current->next;
        }

        current->next = newNode;
    }

    maxMemoryUsage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (maxMemoryUsage <= 0) {
        // Out of memory, remove the oldest node
        Node* temp = head;
        head = head->next;
        free(temp);
        maxMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

void compact() {
    time_t currentTime = time(NULL);

    Node* previous = NULL;
    Node* current = head;
    while (current != NULL) {
        if (difftime(currentTime, current->data.timestamp) * 1000 > compactionThreshold) {
            // Remove the node
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            previous = current;
            current = current->next;
        }
    }
}
```
