```c
#include <stdatomic.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Your structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the lock-free list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

// Define the memory pool
#define POOL_SIZE 1024 // Adjust this based on your needs
Node* memoryPool[POOL_SIZE];
atomic_int poolIndex = ATOMIC_VAR_INIT(0);
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the memory pool
void initMemoryPool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            // Handle allocation failure gracefully
            continue;
        }
        memoryPool[i] = node;
    }
}

// Allocate a new node from the pool
Node* allocateNode() {
    int index = atomic_fetch_add(&poolIndex, 1) % POOL_SIZE;
    pthread_mutex_lock(&poolMutex);
    Node* node = memoryPool[index];
    pthread_mutex_unlock(&poolMutex);
    return node;
}

// Free a node back to the pool
void freeNode(Node* node) {
    if (!node) {
        // Handle null pointer gracefully
        return;
    }
    pthread_mutex_lock(&poolMutex);
    memoryPool[atomic_fetch_add(&poolIndex, 1) % POOL_SIZE] = node;
    pthread_mutex_unlock(&poolMutex);
}

// Define the lock-free list
Node* head = NULL;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Add a new node to the list
void addToList(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = allocateNode();
    if (!node) {
        // Handle allocation failure gracefully
        return;
    }
    node->data = data;
    pthread_mutex_lock(&listMutex);
    node->next = head;
    head = node;
    pthread_mutex_unlock(&listMutex);
}
```

