    private static final String DEFAULT_THEME_DIRECTORY = Environment.getExternalStorageDirectory() + "/themes";
    private ExecutorService executorService = Executors.newFixedThreadPool(5);
    private ConcurrentHashMap<String, Bitmap> themeCache = new ConcurrentHashMap<>();

    public ThemeCachingModule() {
        initializeThemeDirectory();
        startBackgroundCleanupService();
    }

    private void initializeThemeDirectory() {
        File directory = new File(DEFAULT_THEME_DIRECTORY);
        if (!directory.exists()) {
            directory.mkdirs();
        }
    }

