        return themeCache.get(themeName);
    }

    private void startBackgroundCleanupService() {
        executorService.submit(() -> {
            while (true) {
                // Clean up old bitmaps here...

                try { Thread.sleep(60 * 1000); } catch (InterruptedException e) {}
            }
        });
    }

