        executorService.submit(() -> {
            try {
                Bitmap bitmap = ImageProcessingLibrary.parsePNG(filePath);

                // Recycle old bitmaps and set to null...

                themeCache.put(themeName, bitmap);
            } catch (Exception e) {
                // Handle exceptions here...
            }
        });
    }
}
